    /// The command that does not send the line it was typed on. What goes to the planner is what
    /// was left after the interval was read off, which is what every later tick sends too.
    #[test]
    fn the_loop_command_sends_what_is_left_after_the_interval() {
        let mut session = Session::new("none");
        for c in "/loop 5m check the deploy".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("check the deploy".to_string())
        );
        assert!(session.input().is_empty(), "the command stayed on the line");
        assert_eq!(
            session.looping().map(|running| running.prompt()),
            Some("check the deploy")
        );
    }

    /// The command sends nothing when Enter is pressed: the line is held for later. A wrong
    /// implementation submits it at once, or reads a line with no delay as a request.
    #[test]
    fn the_after_command_holds_the_line_and_sends_nothing_now() {
        let mut session = Session::new("none");
        for c in "/after 5m check the deploy".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert_eq!(
            session.looping().map(|running| running.prompt()),
            Some("check the deploy")
        );

        let mut bare = Session::new("none");
        for c in "/after check the deploy".chars() {
            handle_key(&mut bare, key(KeyCode::Char(c)));
        }
        assert_eq!(handle_key(&mut bare, key(KeyCode::Enter)), Action::Redraw);
        assert!(bare.looping().is_none(), "a line with no delay was held");
    }

    /// The turn is sent the task and not the line, and it begins in plan mode (MODE-12). A wrong
    /// implementation sends `/plan fix the auth bug`, or starts the turn before the mode is set.
    #[test]
    fn the_plan_command_sets_plan_mode_and_sends_only_its_task() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        assert_eq!(session.permission_mode(), PermissionMode::Ask);
        for c in "/plan fix the auth bug".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("fix the auth bug".to_string())
        );
        assert_eq!(session.permission_mode(), PermissionMode::Plan);
        assert_eq!(session.status, Status::Working);
        assert_eq!(
            session.transcript.last().expect("the task is said").text,
            "fix the auth bug"
        );
    }

    /// Without a task there is nothing to send, so the word sets the mode and the session stays
    /// at rest. Typed from bypassing it narrows to planning.
    #[test]
    fn the_plan_command_without_a_task_sets_the_mode_and_sends_nothing() {
        use bravebot_agent::PermissionMode;
        for session in [
            Session::new("none"),
            Session::new("none").starting_in_bypass(),
        ] {
            let mut session = session;
            assert_eq!(
                dispatch_command(&mut session, commanded("/plan")),
                Action::Redraw
            );
            assert_eq!(session.permission_mode(), PermissionMode::Plan);
            assert_eq!(session.status, Status::Idle);
            assert!(session.transcript.is_empty(), "something was said");
        }
    }

    /// The word names plan mode, not the next rung: a session already planning stays there, and one
    /// asking is not moved to accepting edits. A longer word is a prompt.
    #[test]
    fn the_plan_command_sets_plan_mode_rather_than_cycling_to_the_next() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        for _ in 0..2 {
            dispatch_command(&mut session, commanded("/plan"));
            assert_eq!(session.permission_mode(), PermissionMode::Plan);
        }

        assert_eq!(command_typed("/planning the release"), None);
    }

    /// The word carries a prompt, which is a turn of its own, so it waits for the turn in flight
    /// and sets the mode when that prompt is run (MODE-12).
    #[test]
    fn the_plan_command_waits_for_the_turn_in_flight() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "/plan look at it".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        assert_eq!(session.permission_mode(), PermissionMode::Ask);
        assert_eq!(session.queued.len(), 1, "the command did not wait");
        assert_eq!(session.queued[0].prompt, "/plan look at it");
    }

    /// An interval with nothing after it is a loop somebody asked for and cannot have, so the
    /// interface says what the command needs rather than quietly doing nothing. Not read as the
    /// bare word either: a person halfway through typing a new interval is not asking about the
    /// loop they are replacing.
    #[test]
    fn an_interval_with_nothing_after_it_says_what_the_command_needs() {
        for line in ["/loop 5m", "/loop every 5m"] {
            let mut session = Session::new("none");
            for c in line.chars() {
                handle_key(&mut session, key(KeyCode::Char(c)));
            }

            assert_eq!(
                handle_key(&mut session, key(KeyCode::Enter)),
                Action::Redraw,
                "{line}"
            );
            assert!(session.looping().is_none(), "{line} started a loop");
            assert_eq!(session.transcript.len(), 1, "{line} said nothing");
            assert_eq!(
                session.transcript[0].text,
                t!(loop_needs_a_prompt),
                "{line}"
            );
        }
    }

    /// The frame a countdown is owed, and the ones it is not. A session with no loop in it is left
    /// alone, because nothing in its row goes stale on its own; a session drawn inside the last
    /// second is left alone too, since the row is spelled no finer than a second and a frame per
    /// pass is a spin.
    #[test]
    fn a_countdown_is_owed_a_frame_once_a_second_and_only_while_a_loop_runs() {
        assert!(!a_countdown_is_owed_a_frame(false, Duration::from_secs(9)));
        assert!(!a_countdown_is_owed_a_frame(
            true,
            COUNTDOWN - Duration::from_millis(1)
        ));
        assert!(a_countdown_is_owed_a_frame(true, COUNTDOWN));
        assert!(a_countdown_is_owed_a_frame(true, Duration::from_secs(9)));
    }

    /// The frame a face is owed, and the ones it is not. A face held as it was is left alone, and a
    /// screen that is not the opening one has no face to repaint, whatever the clock says.
    #[test]
    fn a_face_is_owed_a_frame_only_on_the_opening_screen_and_only_when_its_look_changed() {
        use crate::avatar::Look;
        let open = Look::default();
        let shut = Look {
            away: false,
            blink: true,
        };
        assert!(a_face_is_owed_a_frame(true, shut, open));
        assert!(a_face_is_owed_a_frame(true, open, shut));
        assert!(!a_face_is_owed_a_frame(true, open, open));
        assert!(!a_face_is_owed_a_frame(false, shut, open));
    }

    /// The short wait belongs to the opening screen with motion allowed, and to nothing else.
    #[test]
    fn the_wait_for_a_key_is_short_only_while_a_face_can_move() {
        assert_eq!(wait_for_a_key(true, false), FACE_POLL);
        assert_eq!(wait_for_a_key(true, true), POLL);
        assert_eq!(wait_for_a_key(false, false), POLL);
        assert_eq!(wait_for_a_key(false, true), POLL);
        assert!(FACE_POLL < POLL);
    }

    /// The bare word reads the loop rather than starting one, and sends nothing: between ticks the
    /// transcript is a record of what has already happened, and a loop is the part that has not.
    #[test]
    fn the_bare_loop_command_says_what_is_repeating() {
        let mut session = Session::new("none");
        // A line no message in the catalog quotes, so the sentence that says what the command needs
        // cannot be mistaken for the report: that sentence gives `check the deploy` as its example.
        session.start_loop(
            crate::loops::request("5m tail the log"),
            Vec::new(),
            Vec::new(),
        );
        session.complete("done", Vec::new(), 0);
        session.loop_turn_ended(None);
        session.transcript.clear();
        for c in LOOP_COMMAND.chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert_eq!(
            session.looping().map(|running| running.prompt()),
            Some("tail the log"),
            "the report ended the loop"
        );
        assert_eq!(session.transcript.len(), 2, "the report is not two lines");
        assert!(
            session.transcript[0].text.contains("tail the log"),
            "{}",
            session.transcript[0].text
        );
        assert_eq!(session.transcript[1].text, t!(loop_ends_with));
    }

    /// A held `/after` line is read as sending later, not as repeating (LOOP-18). A wrong
    /// implementation answers "repeating: ...".
    #[test]
    fn the_bare_loop_command_says_an_after_line_is_sending_later() {
        let mut session = Session::new("none");
        for c in "/after 5m tail the log".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        session.transcript.clear();
        for c in LOOP_COMMAND.chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));

        assert_eq!(session.transcript.len(), 2, "{:?}", session.transcript);
        assert!(
            session.transcript[0].text.contains("tail the log"),
            "{}",
            session.transcript[0].text
        );
        assert!(
            session.transcript[0].text.starts_with(
                t!(after_active, number = 1, prompt = "", when = "")
                    .split(':')
                    .next()
                    .unwrap()
            ),
            "{}",
            session.transcript[0].text
        );
        assert_eq!(session.transcript[1].text, t!(loop_ends_with));
        assert_eq!(session.loops().len(), 1, "the report ended it");
    }

    /// The ending a person can reach without also stopping the turn that is in flight, which is
    /// what Ctrl-C reaches first: a loop over a long turn is otherwise ended only by cancelling the
    /// work it has just started. Asked for at rest it takes effect on the press.
    #[test]
    fn the_loop_command_ends_the_loop_when_asked_to_stop() {
        let mut session = Session::new("none");
        session.start_loop(
            crate::loops::request("5m check the deploy"),
            Vec::new(),
            Vec::new(),
        );
        session.complete("done", Vec::new(), 0);
        for c in "/loop stop".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert!(session.looping().is_none(), "the loop is still running");
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(loop_stopped)),
            "the ending was not announced"
        );
    }

    /// LOOP-15: `/loop stop 2` typed in the box ends loop 2 and leaves loop 1, and a bare `stop`
    /// with both live ends neither.
    #[test]
    fn the_loop_command_ends_the_loop_it_names() {
        let mut session = Session::new("none");
        for line in ["5m check the deploy", "1h check the pull request"] {
            session.start_loop(crate::loops::request(line), Vec::new(), Vec::new());
            session.complete("done", Vec::new(), 0);
            session.loop_turn_ended(None);
        }
        let type_line = |session: &mut Session, line: &str| {
            for c in line.chars() {
                handle_key(session, key(KeyCode::Char(c)));
            }
            assert_eq!(handle_key(session, key(KeyCode::Enter)), Action::Redraw);
        };

        type_line(&mut session, "/loop stop");
        assert_eq!(session.loops().len(), 2, "a bare stop picked a loop");

        type_line(&mut session, "/loop stop 2");
        let left: Vec<usize> = session.loops().iter().map(|r| r.number()).collect();
        assert_eq!(left, [1]);
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(loop_stopped_numbered, number = 2)),
            "the ending was not announced"
        );
    }

    /// The same ending asked for during a turn, which is where a loop worth ending usually is. The
    /// line reads and ends the loop alone, and the tick in flight holds nothing of the loop, so it
    /// ends it on the press rather than when the queue is reached (CMD-8). The tick goes on, and the
    /// ending is said once that tick has ended.
    #[test]
    fn asking_to_stop_a_loop_during_a_turn_ends_it_as_it_is_typed() {
        let mut session = Session::new("none");
        session.start_loop(
            crate::loops::request("5m check the deploy"),
            Vec::new(),
            Vec::new(),
        );
        assert!(session.a_turn_is_running(), "the loop sent no first tick");
        for c in "/loop stop".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key_while_working(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert!(
            session.looping().is_none(),
            "the loop outlived the line that stopped it"
        );
        assert!(session.a_turn_is_running(), "the ending stopped the tick");
        assert!(session.queued.is_empty(), "the ending waited as well");

        session.complete("done", Vec::new(), 0);
        session.settle_what_was_said();
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(loop_stopped)),
            "the ending was not announced"
        );
    }

    /// Nothing to stop is worth saying, because the person believed there was something. A command
    /// that answered it with silence would leave them unable to tell which of the two it meant.
    #[test]
    fn asking_to_stop_a_loop_that_is_not_running_says_so() {
        let mut session = Session::new("none");
        for c in "/loop stop".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert_eq!(session.transcript.len(), 1);
        assert_eq!(session.transcript[0].text, t!(loop_none));
    }

    /// The one place in the command where a reserved word could eat a line somebody meant to have
    /// repeated. The word ends a loop as the whole argument, and starts one as the first word of a
    /// sentence.
    #[test]
    fn a_loop_over_a_line_beginning_with_stop_is_still_a_loop() {
        let mut session = Session::new("none");
        for c in "/loop stop the deploy if it is still going".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("stop the deploy if it is still going".to_string())
        );
        assert_eq!(
            session.looping().map(|running| running.prompt()),
            Some("stop the deploy if it is still going")
        );
    }

    /// A goal is a condition, not a prompt. Setting one that started a turn would send a line
    /// nobody typed, and there is no line: the argument is what stops the work, not what starts
    /// it.
    #[test]
    fn the_goal_command_sets_a_condition_without_sending_anything() {
        let mut session = Session::new("none");
        for c in "/goal cargo test exits 0".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert_eq!(
            session.goal().map(crate::goals::Running::condition),
            Some("cargo test exits 0")
        );
    }

    /// CMD-5's rule, on the one command whose argument is a whole sentence: the condition a judge
    /// is given has to be the characters the person endorsed.
    #[test]
    fn the_goal_command_carries_the_whole_condition() {
        let mut session = Session::new("none");
        for c in "/goal every test in bravebot-tui passes and clippy is clean".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));

        assert_eq!(
            session.goal().map(crate::goals::Running::condition),
            Some("every test in bravebot-tui passes and clippy is clean")
        );
    }

    #[test]
    fn the_goal_command_takes_the_goal_off_again() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());

        for c in "/goal clear".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert!(session.goal().is_none());
    }

    /// Pause and resume are typed by a person and touch only what the session keeps, so they run
    /// where `/goal clear` does, mid-turn, while setting a goal waits.
    #[test]
    fn the_goal_command_pauses_and_resumes_the_goal_even_mid_turn() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        for (line, paused) in [("/goal pause", true), ("/goal resume", false)] {
            assert!(runs_while_working(line), "{line} waited for the turn");
            for c in line.chars() {
                handle_key(&mut session, key(KeyCode::Char(c)));
            }
            assert_eq!(
                handle_key(&mut session, key(KeyCode::Enter)),
                Action::Redraw
            );
            assert_eq!(
                session.goal().map(crate::goals::Running::is_paused),
                Some(paused),
                "{line}"
            );
            assert_eq!(
                session.goal().map(crate::goals::Running::condition),
                Some("cargo test exits 0"),
                "{line} changed the condition"
            );
        }
        assert!(!runs_while_working("/goal pause the deploy first"));
    }

    /// With no condition there is no goal to set, and the interface says what it needs rather
    /// than quietly doing nothing.
    #[test]
    fn the_bare_goal_command_is_still_the_command() {
        let mut session = Session::new("none");
        for c in GOAL_COMMAND.chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Redraw
        );
        assert!(session.goal().is_none(), "the bare word set a goal");
        assert_eq!(session.transcript.len(), 1, "the bare word said nothing");
    }

    /// A `@path` is a person vouching for a file with their keystroke. The sentence a goal sends
    /// the work back with is this program's, quoting a judge, so a word beginning with `@` in one
    /// is prose: reading it as a path would open a file on the say-so of a model, wearing an
    /// endorsement nobody gave.
    ///
    /// Through what picks the next line after a turn, since that is where the sentence is marked
    /// as the driver's: a test of [`files_named_in`] alone passes with the mark on the wrong side.
    #[test]
    fn a_path_named_in_a_sentence_the_driver_wrote_vouches_for_nothing() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());

        let (carrying_on, wrote) = next_after_a_turn(&mut session, |session| {
            Ok(
                session.goal_judged(Ok(bravebot_agent::goal::Verdict::NotMet {
                    reason: "the failure is in @crates/core/src/policy.rs".to_string(),
                })),
            )
        })
        .expect("judging cannot fail here")
        .expect("a goal not met yet sends the work back");

        assert!(
            carrying_on.contains("@crates/core/src/policy.rs"),
            "the reason was not quoted, so nothing here could name a file: {carrying_on}"
        );
        assert!(
            files_named_in(&carrying_on, wrote, std::path::Path::new("."), &[]).is_empty(),
            "a sentence this program wrote opened a file"
        );
    }

    /// The other half: a line the person queued goes out before the goal is judged, as theirs, so
    /// a `@path` in it still names a file.
    #[test]
    fn a_path_named_in_a_line_the_person_queued_still_names_a_file() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        for c in "fix the build".chars() {
            session.type_char(c);
        }
        session.submit();
        for c in "look at @crates/core/src/policy.rs".chars() {
            session.type_char(c);
        }
        assert!(session.queue(), "the line was not queued");
        session.complete("done", Vec::new(), 0);

        let mut judged = false;
        let (queued, wrote) = next_after_a_turn(&mut session, |_| {
            judged = true;
            Ok(None)
        })
        .expect("judging cannot fail here")
        .expect("the queued line was not sent");

        assert!(!judged, "the goal was judged before the person's line went");
        assert_eq!(
            files_named_in(&queued, wrote, std::path::Path::new("."), &[]),
            vec!["crates/core/src/policy.rs".to_string()],
            "a line the person typed stopped naming its files"
        );
    }

    /// REFER-6: `@alias/path` in a line the person typed names the file in the reference's
    /// directory, and the same text in a line the driver wrote names nothing.
    #[test]
    fn a_name_under_a_reference_alias_names_the_file_in_its_directory() {
        let sources = vec![(
            "parser".to_string(),
            std::path::PathBuf::from("/refs/parser"),
        )];
        let line = "see @parser/src/lexer.rs and @crates/x.rs";
        assert_eq!(
            files_named_in(
                line,
                Wrote::ThePerson,
                std::path::Path::new("/work"),
                &sources
            ),
            vec![
                "/refs/parser/src/lexer.rs".to_string(),
                "crates/x.rs".to_string()
            ]
        );
        assert!(
            files_named_in(
                line,
                Wrote::TheDriver,
                std::path::Path::new("/work"),
                &sources
            )
            .is_empty()
        );
    }

    /// Leaving ends a goal, so a person who asked to leave during a turn does not wait on a check
    /// of it, or have the work carried on, before the session closes.
    #[test]
    fn a_goal_is_not_judged_after_the_person_asked_to_leave() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        session.quit();

        let mut judged = false;
        let sending = next_after_a_turn(&mut session, |_| {
            judged = true;
            Ok(Some("carry on".to_string()))
        })
        .expect("judging cannot fail here");

        assert!(
            !judged,
            "the goal was judged after the person asked to leave"
        );
        assert_eq!(
            sending, None,
            "a line went out after the person asked to leave"
        );
    }

    /// GOAL-10: `/exit` and `/clear` typed while a turn runs end the goal, so the goal does not
    /// send the work back before they are carried out.
    #[test]
    fn a_goal_is_not_judged_while_a_command_waits_in_the_queue() {
        for command in ["/exit", "/clear", "/goal cargo test exits 1", "/goal clear"] {
            let mut session = Session::new("none");
            session.start_goal("cargo test exits 0".to_string());
            for c in "fix the build".chars() {
                session.type_char(c);
            }
            session.submit();
            for c in command.chars() {
                session.type_char(c);
            }
            assert!(session.queue_command(), "{command} was not queued");
            session.complete("done", Vec::new(), 0);

            let mut judged = false;
            let sending = next_after_a_turn(&mut session, |_| {
                judged = true;
                Ok(Some("carry on".to_string()))
            })
            .expect("judging cannot fail here");

            assert!(!judged, "the goal was judged with {command} waiting");
            assert_eq!(sending, None, "work went out with {command} waiting");
            assert!(
                session.take_queued_command().is_some(),
                "{command} was not left for the loop to carry out"
            );
        }
    }

    /// RECALL-11. A fact file is untrusted text: control characters in what it says of itself are
    /// drawn as pictures and a very long value is cut, so one fact cannot repaint the screen.
    #[test]
    fn hostile_front_matter_is_drawn_as_harmless_text() {
        use bravebot_agent::recall::fact::{Fact, Scope, Source};
        use bravebot_agent::recall::overview::Overview;
        use bravebot_core::label::Confidentiality;
        let hostile = format!("2026\x1b[2J\x07{}", "9".repeat(10_000));
        let mut session = Session::new("none");
        session.report_recall(&Overview {
            rules: Vec::new(),
            facts: vec![(
                Scope::Project,
                Fact {
                    key: "k\x1b]0;x".to_string(),
                    source: Source::Agent,
                    label: Confidentiality::Private,
                    created: None,
                    verified: Some(hostile.clone()),
                    superseded_by: Some(hostile),
                    session: None,
                    tags: Vec::new(),
                    body: String::new(),
                },
            )],
        });
        for entry in session.transcript.iter() {
            assert!(
                !entry.text.chars().any(char::is_control),
                "{:?}",
                entry.text
            );
            assert!(entry.text.chars().count() < 1_000, "{}", entry.text.len());
        }
        assert_eq!(session.transcript.len(), 2);
    }

    /// RECALL-11. A fact with no verified date says so in the person's language.
    #[test]
    fn an_unverified_fact_says_never() {
        use bravebot_agent::recall::fact::{Fact, Scope};
        use bravebot_agent::recall::overview::Overview;
        let mut session = Session::new("none");
        session.report_recall(&Overview {
            rules: Vec::new(),
            facts: vec![(Scope::Project, Fact::parse("k", "text"))],
        });
        assert!(
            session.transcript[1]
                .text
                .contains(t!(memory_verified_never))
        );
    }

    /// RECALL-11. Each rule file is listed with its line count, and each fact with its key, scope,
    /// source, label, verified date and whether another fact replaced it. None kept is said.
    #[test]
    fn the_memory_listing_shows_rules_and_facts_with_their_standing() {
        use bravebot_agent::recall::fact::{Fact, Scope, Source};
        use bravebot_agent::recall::overview::{Overview, RuleFile};
        use bravebot_core::label::Confidentiality;
        let fact = |key: &str, superseded_by: Option<&str>| Fact {
            key: key.to_string(),
            source: Source::Person,
            label: Confidentiality::Public,
            created: None,
            verified: Some("2026-10-01".to_string()),
            superseded_by: superseded_by.map(str::to_string),
            session: None,
            tags: Vec::new(),
            body: "never shown\n".to_string(),
        };
        let mut session = Session::new("none");
        session.report_recall(&Overview::default());
        session.report_recall(&Overview {
            rules: vec![RuleFile {
                path: "/state/AGENTS.md".into(),
                lines: 3,
                more: false,
            }],
            facts: vec![
                (Scope::Project, fact("live-one", None)),
                (Scope::Everywhere, fact("old-one", Some("live-one"))),
            ],
        });
        let said: Vec<&str> = session
            .transcript
            .iter()
            .map(|entry| entry.text.as_str())
            .collect();
        assert_eq!(said[0], t!(memory_no_rules));
        assert_eq!(said[1], t!(memory_no_facts));
        assert_eq!(
            said[2],
            t!(memory_rules_file, path = "/state/AGENTS.md", lines = 3)
        );
        assert_eq!(said.len(), 5);
        for (line, key, standing) in [
            (said[3], "live-one", "live"),
            (said[4], "old-one", "superseded by live-one"),
        ] {
            assert!(
                line.contains(key) && line.contains("2026-10-01") && line.contains(standing),
                "{line}"
            );
            assert!(!line.contains("never shown"), "{line}");
        }
        assert!(said[3].contains("this project") && said[4].contains("every project"));
    }

    /// A queued command that leaves the goal alone does not stop the goal being judged, or the goal
    /// would sit idle after `/help`.
    #[test]
    fn a_goal_is_still_judged_with_a_command_waiting_that_leaves_it_alone() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        for c in "fix the build".chars() {
            session.type_char(c);
        }
        session.submit();
        for c in "/help".chars() {
            session.type_char(c);
        }
        assert!(session.queue_command(), "/help was not queued");
        session.complete("done", Vec::new(), 0);

        let sending = next_after_a_turn(&mut session, |_| Ok(Some("carry on".to_string())))
            .expect("judging cannot fail here");

        assert_eq!(
            sending,
            Some(("carry on".to_string(), Wrote::TheDriver)),
            "a harmless queued command held the goal still"
        );
    }

    /// A sentence mentioning it is a thing to say to the planner.
    #[test]
    fn a_prompt_containing_the_goal_command_is_still_a_prompt() {
        let mut session = Session::new("none");
        for c in "what does /goal do".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("what does /goal do".to_string())
        );
        assert!(session.goal().is_none());
    }

    #[test]
    fn a_longer_word_starting_with_goal_is_a_prompt() {
        let mut session = Session::new("none");
        for c in "/goals are useful".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("/goals are useful".to_string())
        );
        assert!(session.goal().is_none());
    }

    /// MANIFEST-9's other half: a session can reach the planning mode, so the word has to start a
    /// run and carry the whole task. The task is a sentence, like a goal's condition, so nothing
    /// may be cut off it: what the planner is shown is what it plans, and the planner is shown
    /// this and nothing else.
    #[test]
    fn a_session_can_ask_for_a_manifest_run() {
        let mut session = Session::new("none");
        for c in "/manifest summarise every doc under docs/specs".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Manifest(
                "summarise every doc under docs/specs".to_string(),
                Vec::new(),
                Vec::new()
            )
        );
        assert!(
            session.input().is_empty(),
            "the command is still in the box"
        );
    }

    /// The bare word plans nothing. There is no default task and there could not be one: the task
    /// string is the whole of a manifest run's input, so a run started without one would plan
    /// against nothing at all.
    #[test]
    fn a_manifest_run_needs_a_task_to_plan() {
        let mut session = Session::new("none");
        for c in MANIFEST_COMMAND.chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Manifest(String::new(), Vec::new(), Vec::new()),
            "the bare word has to reach the loop, which says what it needs"
        );
        assert!(
            t!(manifest_needs_a_task).contains(MANIFEST_COMMAND),
            "the answer does not name the command it is about"
        );
    }

    /// The set a person's line is compared against, as a session with one definition of their
    /// own resolves it.
    fn a_resolved_set(model: Option<&str>) -> bravebot_core::delegate::Definitions {
        let mut definitions = bravebot_core::delegate::Definitions::default();
        let definition = bravebot_core::delegate::Definition::from_file(
            "rule-reviewer",
            "Checks a diff.",
            bravebot_core::delegate::Kind::Reader,
            None,
            "REVIEW",
            "~/.bravebot/agents",
        );
        definitions.insert(match model {
            Some(model) => definition.with_model(model),
            None => definition,
        });
        definitions
    }

    /// A configuration whose models need nothing signed in.
    fn a_config_needing_no_sign_in() -> Config {
        Config::from_lookup(|key| match key {
            "SERVICES_KEY_AICHAT" => Some("test-key".into()),
            "BRAVE_SERVICES_KEY_ID" => Some("test-id".into()),
            "BRAVE_AI_CHAT_ENDPOINT" => Some("http://unused.invalid".into()),
            _ => None,
        })
        .expect("config")
    }

    /// Addresses whatever the session's line addressed, as the loop does once it has read the set.
    fn addressing(session: &mut Session, argument: &str, model: Option<&str>) -> Action {
        address(
            session,
            &a_config_needing_no_sign_in(),
            &a_resolved_set(model),
            argument,
            Vec::new(),
            Vec::new(),
        )
    }

    /// ADDRESS-2. The word is the program's and the name is an argument, carried to the loop whole
    /// because which names exist is read from the workspace and the trust map, both of which the
    /// loop owns. The box empties, as it does for every command.
    #[test]
    fn a_session_can_address_a_definition() {
        let mut session = Session::new("none");
        for c in "/agent rule-reviewer review the diff".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Address(
                "rule-reviewer review the diff".to_string(),
                Vec::new(),
                Vec::new()
            )
        );
        assert!(
            session.input().is_empty(),
            "the command is still in the box"
        );
    }

    /// A line typed while a turn ran was typed into the box as much as one typed at rest, so it
    /// addresses the definition once the turn ends, and the running turn is not the one addressed.
    #[test]
    fn a_line_addressing_a_definition_queued_while_a_turn_ran_addresses_it_when_the_turn_ends() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));

        for c in "/agent rule-reviewer review the diff".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        assert!(
            session.take_addressing().is_none(),
            "the turn already running was addressed"
        );

        session.complete("answered", Vec::new(), 0);
        assert_eq!(
            queued_next(&mut session),
            Some(Action::Address(
                "rule-reviewer review the diff".to_string(),
                Vec::new(),
                Vec::new()
            ))
        );
    }

    /// ADDRESS-2's last sentence. The whole word is the command, so a sentence that happens to
    /// start with a longer one is the person's prompt.
    #[test]
    fn a_longer_word_starting_with_agent_is_a_prompt() {
        let mut session = Session::new("none");
        for c in "/agents are useful".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Submit("/agents are useful".to_string())
        );
        assert!(session.take_addressing().is_none());
    }

    /// ADDRESS-10, and ADDRESS-3's other side. What the planner is given is the task and nothing
    /// of the command, the next turn is the session's own planner's again, and nothing but this
    /// line addressed anything: there is no mode to leave.
    #[test]
    fn an_addressed_line_runs_the_named_definition_on_its_task_for_one_turn() {
        let mut session = Session::new("none");

        assert_eq!(
            addressing(&mut session, "rule-reviewer   review the diff", None),
            Action::Submit("review the diff".to_string())
        );
        assert_eq!(
            session.take_addressing().map(|addressed| addressed.name),
            Some("rule-reviewer".to_string()),
            "the turn was not told which definition it runs under"
        );
        assert!(
            session.take_addressing().is_none(),
            "the next turn was addressed too"
        );
    }

    /// A stop hands the line back to be changed rather than retyped, and the line a person typed
    /// named a definition. Handed back as its task alone, Enter would send that task to the
    /// session's own planner, holding everything the definition was there to take away.
    #[test]
    fn a_stopped_addressed_turn_puts_the_whole_agent_line_back_in_the_box() {
        let mut session = Session::new("none");
        assert_eq!(
            addressing(&mut session, "rule-reviewer review the diff", None),
            Action::Submit("review the diff".to_string())
        );
        let addressed = session.take_addressing();

        finish_turn(
            &mut session,
            &a_config_needing_no_sign_in(),
            &workspace_for_test(),
            Line {
                text: "review the diff",
                addressed: addressed.as_ref(),
                offered_a_later_look: false,
            },
            FinishedTurn {
                decisions: None,
                work: bravebot_agent::Work::default(),
                outcome: Err(turn::TurnError::Cancelled { attempts: Some(0) }),
                conversation: Conversation::new(),
                sink: Trail::new(),
                servers: None,
            },
            RetainedTurn {
                files: bravebot_core::file_authority::FileAuthority::new(TrustStore::new("/work")),
                programs: TrustedPrograms::new(),
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
                began: Conversation::new().mark(),
            },
        );

        assert_eq!(session.input(), "/agent rule-reviewer review the diff");
        assert_eq!(
            handle_key(&mut session, key(KeyCode::Enter)),
            Action::Address(
                "rule-reviewer review the diff".to_string(),
                Vec::new(),
                Vec::new()
            ),
            "the line that came back no longer addressed the definition"
        );
    }

    /// ADDRESS-11 as the interface reads it. An addressed turn asks for its definition's model,
    /// so that is the name its reply is held against: held against the session's, every answer
    /// from the definition's model would be reported as the session's substituted.
    #[test]
    fn an_addressed_turn_is_held_against_the_model_its_definition_named() {
        let config = a_config_needing_no_sign_in();
        let mut session = Session::new("none");
        session.choose_model("the-sessions-model", &config);
        let named = crate::state::Addressed {
            name: "rule-reviewer".to_string(),
            model: Some("the-definitions-model".to_string()),
        };
        let unnamed = crate::state::Addressed {
            name: "plain-reader".to_string(),
            model: None,
        };
        let line = |addressed| Line {
            text: "review the diff",
            addressed,
            offered_a_later_look: false,
        };

        assert_eq!(
            line(Some(&named)).model(&session, &config),
            "the-definitions-model"
        );
        assert_eq!(
            line(Some(&unnamed)).model(&session, &config),
            "the-sessions-model",
            "a definition naming no model did not run on the session's"
        );
        assert_eq!(line(None).model(&session, &config), "the-sessions-model");
    }

    /// BACKEND-48: a definition naming a model this machine may not request is refused where the
    /// definition is read, so nothing is addressed to it and nothing is started for it.
    ///
    /// A delegate definition is the one route to a model that no picker and no prompt stands in
    /// front of: it is loaded from a vouched-for file, and a build that only checked the model a
    /// session settles on would let this one through.
    #[test]
    fn a_definition_naming_a_model_this_machine_may_not_request_is_refused() {
        let scratch = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../target/test-scratch")
            .join("tui-models-delegate");
        std::fs::create_dir_all(&scratch).expect("a scratch directory");
        let path = scratch.join("managed.json");
        std::fs::write(&path, r#"{"models": {"deny": ["an-expensive-model"]}}"#)
            .expect("a managed file");

        let definitions = a_resolved_set(Some("an-expensive-model"));
        let mut config = a_config_needing_no_sign_in();

        assert!(
            definition_named(&config, &definitions, "rule-reviewer").is_ok(),
            "a machine with no managed file refused a definition"
        );

        config.models = bravebot_config::Managed::at(&path).models().clone();
        let refused = definition_named(&config, &definitions, "rule-reviewer")
            .expect_err("the definition was addressed")
            .into_message();
        assert!(
            refused.contains("an-expensive-model") && refused.contains(&path.display().to_string()),
            "the refusal named neither the model nor the file that refused it: {refused}"
        );
    }

    /// `/agent` settles the model with the name, resolved as the driver resolves it, so what the
    /// interface asks about the turn is about the model the turn will run on.
    #[test]
    fn addressing_a_definition_that_names_a_model_carries_that_model() {
        let config = a_config_needing_no_sign_in();
        let mut session = Session::new("none");

        addressing(&mut session, "rule-reviewer review the diff", Some("haiku"));

        assert_eq!(
            session.take_addressing(),
            Some(crate::state::Addressed {
                name: "rule-reviewer".to_string(),
                model: Some(config.model_named("haiku")),
            })
        );
    }

    /// ADDRESS-6's first half. The bare word is where somebody asked what this session resolved,
    /// so it says, and starts nothing.
    #[test]
    fn the_bare_word_says_what_this_session_resolved() {
        let mut session = Session::new("none");

        assert_eq!(addressing(&mut session, "", None), Action::Redraw);
        assert_eq!(
            said_in_the_transcript(&session).last().map(String::as_str),
            Some(
                "this session resolved reader, checker, worker, rule-reviewer; address one with \
                 /agent <name> <task>"
            )
        );
        assert!(
            session.take_addressing().is_none(),
            "the bare word started a turn"
        );
    }

    /// ADDRESS-5's second paragraph. A definition started on an empty task would be run on
    /// nothing, so a name alone runs nothing and says what is missing.
    #[test]
    fn a_name_with_no_task_runs_nothing_and_says_a_task_is_needed() {
        let mut session = Session::new("none");

        assert_eq!(
            addressing(&mut session, "rule-reviewer", None),
            Action::Redraw
        );
        assert_eq!(
            said_in_the_transcript(&session).last().map(String::as_str),
            Some(
                "/agent rule-reviewer takes the task to do, as in /agent rule-reviewer review the diff"
            )
        );
        assert!(
            session.take_addressing().is_none(),
            "a turn started on no task"
        );
    }

    /// ADDRESS-5. Said before anything starts, because a turn refused once it has started is drawn
    /// as a failure whose reason nobody is shown. A name differing only in case is another name.
    #[test]
    fn a_name_this_session_did_not_resolve_runs_nothing_and_lists_what_it_did() {
        for typed in ["auditor", "Rule-Reviewer"] {
            let mut session = Session::new("none");

            assert_eq!(
                addressing(&mut session, &format!("{typed} review the diff"), None),
                Action::Redraw
            );
            assert_eq!(
                said_in_the_transcript(&session).last().cloned(),
                Some(format!(
                    "there is no definition called {typed}; this session resolved reader, \
                     checker, worker, rule-reviewer"
                ))
            );
            assert!(
                session.take_addressing().is_none(),
                "{typed} started a turn"
            );
        }
    }

    /// ADDRESS-11. A definition naming a model this machine has not signed in to does not run on
    /// the session's instead, and the person is told which asked for what before anything starts.
    /// The first case is the control: the same definition under a configuration needing no sign-in
    /// runs.
    #[test]
    fn a_definition_whose_model_needs_a_sign_in_runs_nothing_and_says_so() {
        use bravebot_config::env_var;
        let mut session = Session::new("none");
        assert!(
            matches!(
                addressing(&mut session, "rule-reviewer review the diff", Some("haiku")),
                Action::Submit(_)
            ),
            "the definition did not run where no sign-in was needed"
        );

        let bedrock = Config::from_lookup(|key| match key {
            env_var::USE_BEDROCK => Some("1".into()),
            env_var::AWS_REGION => Some("us-west-2".into()),
            env_var::BEDROCK_HAIKU_MODEL => Some("haiku-arn".into()),
            // A profile no machine has, so no session exists whoever runs this.
            env_var::AWS_PROFILE => Some("a-profile-no-machine-has".into()),
            _ => None,
        })
        .expect("config");
        let mut session = Session::new("none");
        assert_eq!(
            address(
                &mut session,
                &bedrock,
                &a_resolved_set(Some("haiku")),
                "rule-reviewer review the diff",
                Vec::new(),
                Vec::new()
            ),
            Action::Redraw
        );
        assert_eq!(
            said_in_the_transcript(&session).last().map(String::as_str),
            Some("rule-reviewer asked for haiku, which needs a sign-in first, so it did not run")
        );
        assert!(session.take_addressing().is_none(), "a turn started anyway");
    }

    /// The definition a session started under `--agent` works under, as the command line leaves
    /// it on the session.
    fn standing() -> crate::state::Addressed {
        crate::state::Addressed {
            name: "rule-reviewer".to_string(),
            model: None,
        }
    }

    /// CLI-19. Words given on the command line belong to the session, not to the first turn, so a
    /// second turn is built from the same words. The per-turn builder reads them from here.
    #[test]
    fn a_session_keeps_the_system_prompt_words_it_started_with_through_every_turn() {
        let words = bravebot_agent::turn::SystemPrompts {
            replacing: Some("You are a reviewer.".to_string()),
            appending: Some("Answer in French.".to_string()),
        };
        let mut session = Session::new("none").with_system_prompts(words.clone());

        for turn in ["first", "second"] {
            type_line(&mut session, turn);
            assert_eq!(
                handle_key(&mut session, key(KeyCode::Enter)),
                Action::Submit(turn.to_string())
            );
            assert_eq!(session.system_prompts(), &words, "lost before {turn:?}");
            session.complete("done", Vec::new(), 0);
        }
        assert_eq!(session.system_prompts(), &words, "lost after the turns");
        assert_eq!(
            Session::new("none").system_prompts(),
            &bravebot_agent::turn::SystemPrompts::default(),
            "a session given no words holds some"
        );
    }

    /// CLI-17. A session started under a definition addresses every turn to it, including a `/loop`
    /// tick. An unaddressed tick would have every tool the session has (ADDRESS-7). The name on the
    /// turn is also what makes the kernel withhold the later look and the watch (ADDRESS-8).
    #[test]
    fn a_session_started_under_a_definition_addresses_every_turn_a_loop_tick_included() {
        let mut session = Session::new("none");
        session.work_under(standing());

        for turn in ["review the diff", "and the tests"] {
            type_line(&mut session, turn);
            assert_eq!(
                handle_key(&mut session, key(KeyCode::Enter)),
                Action::Submit(turn.to_string())
            );
            assert_eq!(
                session.take_addressing().map(|addressed| addressed.name),
                Some("rule-reviewer".to_string()),
                "the typed turn {turn:?} went to the session's planner"
            );
            session.complete("reviewed", Vec::new(), 0);
        }

        assert!(
            session
                .start_loop(
                    crate::loops::request("5m check the build"),
                    Vec::new(),
                    Vec::new()
                )
                .is_some(),
            "the loop sent no first tick"
        );
        assert!(
            session
                .looping()
                .and_then(|running| running.tick())
                .is_some(),
            "the turn started is not a tick, so this says nothing about one"
        );
        assert_eq!(
            session.take_addressing().map(|addressed| addressed.name),
            Some("rule-reviewer".to_string()),
            "the loop's tick went to the session's planner"
        );
    }

    /// CLI-17's `/agent` inside such a session. The line addresses another definition for one turn,
    /// and the next turn goes to the session's definition again.
    #[test]
    fn a_definition_named_on_the_line_lasts_one_turn_under_the_one_the_session_works_under() {
        let mut session = Session::new("none");
        session.work_under(standing());
        let mut definitions = a_resolved_set(None);
        definitions.insert(bravebot_core::delegate::Definition::from_file(
            "diff-checker",
            "Checks a diff.",
            bravebot_core::delegate::Kind::Reader,
            None,
            "CHECK",
            "~/.bravebot/agents",
        ));

        assert_eq!(
            address(
                &mut session,
                &a_config_needing_no_sign_in(),
                &definitions,
                "diff-checker check the diff",
                Vec::new(),
                Vec::new()
            ),
            Action::Submit("check the diff".to_string())
        );
        assert_eq!(
            session.take_addressing().map(|addressed| addressed.name),
            Some("diff-checker".to_string()),
            "the line's definition was not the one its turn addressed"
        );
        assert_eq!(
            session.take_addressing().map(|addressed| addressed.name),
            Some("rule-reviewer".to_string()),
            "the next turn did not go back to the session's definition"
        );
    }

    /// CLI-17. A definition that names a model makes it the session's model, since every turn asks
    /// for it, and `/model` says so instead of opening a picker whose pick no turn would ask for.
    /// A definition naming no model leaves both alone.
    #[test]
    fn a_session_under_a_definition_naming_a_model_works_on_it_and_refuses_the_picker() {
        let open_the_picker = |session: &mut Session| {
            type_line(session, MODEL_COMMAND);
            handle_key(session, key(KeyCode::Enter))
        };

        let config = a_config_needing_no_sign_in();
        let mut session = Session::new("none");
        session.choose_model("the-sessions-model", &config);
        session.work_under(standing());
        assert_eq!(session.model(), Some("the-sessions-model"));
        assert_eq!(open_the_picker(&mut session), Action::ChooseModel);

        let config = a_config_needing_no_sign_in();
        let mut session = Session::new("none");
        session.choose_model("the-sessions-model", &config);
        session.work_under(crate::state::Addressed {
            model: Some("the-definitions-model".to_string()),
            ..standing()
        });
        assert_eq!(
            session.model(),
            Some("the-definitions-model"),
            "the window and the effort would be the model no turn asks for"
        );
        assert_eq!(
            open_the_picker(&mut session),
            Action::Redraw,
            "the picker opened although no turn would ask for its pick"
        );
        assert_eq!(
            said_in_the_transcript(&session).last().map(String::as_str),
            Some(
                "every turn is addressed to rule-reviewer, which asks for the-definitions-model, \
                 so /model has nothing to change; start bravebot without --agent to pick a model"
            )
        );
    }

    /// A stop puts the line back to be sent again, and Enter on a bare task in this session already
    /// addresses its definition. So a turn addressed to that definition comes back as the task
    /// alone, and only a line that named another definition comes back with the name.
    #[test]
    fn a_stopped_turn_comes_back_naming_a_definition_only_where_the_session_would_not() {
        let standing = standing();
        let other = crate::state::Addressed {
            name: "diff-checker".to_string(),
            model: None,
        };
        let line = |addressed| Line {
            text: "review the diff",
            addressed,
            offered_a_later_look: false,
        };

        assert_eq!(
            line(Some(&standing)).as_typed(Some(&standing)),
            "review the diff"
        );
        assert_eq!(
            line(Some(&other)).as_typed(Some(&standing)),
            "/agent diff-checker review the diff"
        );
        assert_eq!(
            line(Some(&standing)).as_typed(None),
            "/agent rule-reviewer review the diff",
            "a session under no definition lost the name its line typed"
        );
    }

    /// CLI-17. A name on the command line is matched against the set a turn starting now would
    /// resolve, as a `/agent` line is (ADDRESS-5). A name nobody wrote is refused with the names
    /// that exist and sets no definition, and a name that exists is announced once.
    #[test]
    fn a_name_from_the_command_line_is_worked_under_where_it_was_written_and_refused_where_not() {
        let home = crate::testutil::scratch_dir("bravebot-work-under-home");
        let _ = std::fs::remove_dir_all(&home);
        std::fs::create_dir_all(home.join("agents")).expect("scratch");
        std::fs::write(
            home.join("agents").join("rule-reviewer.md"),
            "---\nname: rule-reviewer\ndescription: Checks a diff.\nkind: reader\n---\n\nREVIEW\n",
        )
        .expect("write the definition");
        let workspace = workspace_for_test();
        let trust = TrustStore::new(workspace.root());
        let mut config = a_config_needing_no_sign_in();

        let mut session = Session::new("none");
        assert_eq!(
            work_under(
                &mut session,
                &mut config,
                &workspace,
                Some(&home),
                &trust,
                &Default::default(),
                "nobody"
            ),
            Err(Unusable::Missing(
                "there is no definition called nobody; this session resolved reader, checker, \
                 worker, rule-reviewer"
                    .to_string()
            ))
        );
        assert!(
            session.standing_definition().is_none(),
            "a refused name was worked under anyway"
        );

        assert_eq!(
            work_under(
                &mut session,
                &mut config,
                &workspace,
                Some(&home),
                &trust,
                &Default::default(),
                "rule-reviewer"
            ),
            Ok(())
        );
        assert_eq!(session.standing_definition(), Some(&standing()));
        assert_eq!(
            said_in_the_transcript(&session).last().map(String::as_str),
            Some(
                "every turn is addressed to rule-reviewer; /agent <name> <task> addresses another \
                 for one turn"
            )
        );
        let _ = std::fs::remove_dir_all(&home);
    }

    /// A home holding one definition of the person's own, for the tests of a resumed session.
    fn a_home_with_a_definition(label: &str, model: Option<&str>) -> std::path::PathBuf {
        let home = crate::testutil::scratch_dir(label);
        let _ = std::fs::remove_dir_all(&home);
        std::fs::create_dir_all(home.join("agents")).expect("scratch");
        let model = model.map_or(String::new(), |model| format!("model: {model}\n"));
        std::fs::write(
            home.join("agents").join("rule-reviewer.md"),
            format!(
                "---\nname: rule-reviewer\ndescription: Checks a diff.\nkind: reader\n{model}---\n\nREVIEW\n"
            ),
        )
        .expect("write the definition");
        home
    }

    fn a_handle_for_test(workspace: &Workspace) -> bravebot_session::sessions::Handle {
        bravebot_session::sessions::Handle::begin(
            workspace.root(),
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        )
    }

    /// ADDRESS-3. The name `--agent` gave is written into the session's record and is the only
    /// thing that puts it there; a session that names none writes none.
    #[test]
    fn a_resumed_session_works_under_the_definition_its_record_names() {
        let home = a_home_with_a_definition("bravebot-resume-under-home", None);
        let workspace = workspace_for_test();
        let trust = TrustStore::new(workspace.root());
        let mut config = a_config_needing_no_sign_in();

        let mut stored = a_handle_for_test(&workspace);
        let mut session = Session::new("none");
        settle_under(
            &mut session,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut stored,
            Some("rule-reviewer"),
            None,
            None,
        )
        .expect("the name is held");
        assert_eq!(stored.agent(), Some("rule-reviewer"));

        // The record read back is what a resume starts from, and it is addressed again from it.
        let mut resumed_session = Session::new("none");
        let mut resumed = a_handle_for_test(&workspace);
        resumed.set_agent(stored.agent().map(str::to_string));
        settle_under(
            &mut resumed_session,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut resumed,
            None,
            Some("rule-reviewer"),
            None,
        )
        .expect("the recorded name is held");
        assert_eq!(resumed_session.standing_definition(), Some(&standing()));
        assert_eq!(resumed.agent(), Some("rule-reviewer"));
        assert_eq!(
            resumed_session
                .take_addressing()
                .map(|addressed| addressed.name),
            Some("rule-reviewer".to_string()),
            "a turn of the resumed session was not addressed to the definition"
        );
        let _ = std::fs::remove_dir_all(&home);
    }

    /// SESSION-39. A session opened under a definition notes the turns of the directory's other
    /// sessions that were addressed to it for that turn alone, newest first, with the start of each
    /// reply, and counts the ones past the first three. The regressions it rejects are the notes
    /// left out, the newest left out for the oldest, and the session's own record noted as another.
    #[test]
    fn a_session_opened_under_a_definition_notes_the_turns_addressed_to_it_elsewhere() {
        use bravebot_agent::conversation::Address;
        use bravebot_agent::request_view::Provenance;
        use bravebot_aichat::protocol::Message;
        use bravebot_session::sessions::Standing;
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let home = a_home_with_a_definition("bravebot-addressed-elsewhere-home", None);
        let root = crate::test_profile::project("bravebot-addressed-elsewhere");
        std::fs::create_dir_all(&root).expect("create");
        let workspace = Workspace::new(&root).expect("a workspace");
        let trust = TrustStore::new(workspace.root());
        let mut config = a_config_needing_no_sign_in();

        let mut conversation = Conversation::new();
        let now = bravebot_session::sessions::now();
        for (turn, prompt) in ["first", "second", "third", "fourth"].iter().enumerate() {
            conversation.push_from(Message::user(*prompt), Provenance::Typed);
            conversation.address_last(Address {
                definition: "rule-reviewer".to_string(),
                standing: false,
                at: Some(now + turn as u64),
            });
            conversation.push(Message::assistant(format!(
                "reviewed the {prompt}\nin full"
            )));
        }
        let mut elsewhere = a_handle_for_test(&workspace);
        elsewhere.save(
            "review the diffs",
            Standing {
                history: None,
                conversation: &conversation.snapshot(),
                turns: 4,
                tokens: 0,
                split: Default::default(),
                spend: &Default::default(),
                timing: &Default::default(),
                model: None,
                todos: &Default::default(),
                asides: &[],
                trust: &trust,
                programs: &TrustedPrograms::new(),
                directories: &[],
                manifest: None,
                rewind: &[],
                checkouts: &[],
                touched: None,
                answered_by_mode: false,
            },
        );

        let mut opened = Session::new("none");
        let mut stored = a_handle_for_test(&workspace);
        settle_under(
            &mut opened,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut stored,
            Some("rule-reviewer"),
            None,
            None,
        )
        .expect("the name is held");
        let said = said_in_the_transcript(&opened);
        let noted: Vec<&str> = said
            .iter()
            .map(String::as_str)
            .skip_while(|line| !line.starts_with("every turn is addressed"))
            .skip(1)
            .collect();
        assert_eq!(
            noted,
            vec![
                "rule-reviewer answered in \"review the diffs\" just now: reviewed the fourth in full",
                "rule-reviewer answered in \"review the diffs\" just now: reviewed the third in full",
                "rule-reviewer answered in \"review the diffs\" just now: reviewed the second in full",
                "and 1 more turn; /resume lists the sessions",
            ],
            "{said:?}"
        );

        let mut resumed = Session::new("none");
        settle_under(
            &mut resumed,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut elsewhere,
            None,
            Some("rule-reviewer"),
            None,
        )
        .expect("the recorded name is held");
        let said = said_in_the_transcript(&resumed);
        assert!(
            !said.iter().any(|line| line.contains("answered in")),
            "the session's own turns were noted as another's: {said:?}"
        );
        let _ = std::fs::remove_dir_all(&home);
    }

    /// ADDRESS-3. A definition deleted since is said, naming it and that the narrowing is gone,
    /// and the session opens. It stops recording the name, because the turns from here are not the
    /// definition's.
    #[test]
    fn a_recorded_definition_that_is_gone_is_said_and_the_session_opens_without_it() {
        let home = a_home_with_a_definition("bravebot-resume-gone-home", None);
        let workspace = workspace_for_test();
        let trust = TrustStore::new(workspace.root());
        let mut config = a_config_needing_no_sign_in();
        let mut stored = a_handle_for_test(&workspace);
        stored.set_agent(Some("deleted-since".to_string()));
        let mut session = Session::new("none");

        let settled = settle_under(
            &mut session,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut stored,
            None,
            Some("deleted-since"),
            None,
        );

        assert_eq!(settled, Ok(()), "the session did not open");
        assert!(
            session.standing_definition().is_none(),
            "the session was addressed to a definition that does not exist"
        );
        assert_eq!(stored.agent(), None, "the record went on naming it");
        let said = said_in_the_transcript(&session).join("\n");
        assert!(
            said.contains("deleted-since") && said.contains("the narrowing is gone"),
            "the loss was not said: {said}"
        );
        let _ = std::fs::remove_dir_all(&home);
    }

    /// ADDRESS-11, CLI-9. A definition that is there and names a model needing a sign-in is not
    /// a definition that went away: going on would run the planner on its own model in place of
    /// the one the definition asked for.
    #[test]
    fn a_recorded_definition_whose_model_needs_a_sign_in_is_refused_not_replaced() {
        let home = a_home_with_a_definition("bravebot-resume-signin-home", Some("haiku"));
        let workspace = workspace_for_test();
        let trust = TrustStore::new(workspace.root());
        let mut config = Config::from_lookup(|key| match key {
            "SERVICES_KEY_AICHAT" => Some("test-key".into()),
            "BRAVE_SERVICES_KEY_ID" => Some("test-id".into()),
            "BRAVE_AI_CHAT_ENDPOINT" => Some("http://unused.invalid".into()),
            bravebot_config::env_var::USE_BEDROCK => Some("1".into()),
            bravebot_config::env_var::AWS_REGION => Some("us-west-2".into()),
            bravebot_config::env_var::BEDROCK_HAIKU_MODEL => Some("haiku-arn".into()),
            bravebot_config::env_var::AWS_PROFILE => Some("a-profile-no-machine-has".into()),
            _ => None,
        })
        .expect("config");
        let mut stored = a_handle_for_test(&workspace);
        stored.set_agent(Some("rule-reviewer".to_string()));
        let mut session = Session::new("none");

        let settled = settle_under(
            &mut session,
            &mut config,
            &workspace,
            Some(&home),
            &trust,
            &Default::default(),
            &mut stored,
            None,
            Some("rule-reviewer"),
            None,
        );

        let refused = settled.expect_err("the session opened on the planner's model");
        assert!(
            refused.contains("rule-reviewer") && refused.contains("haiku"),
            "the refusal named neither the definition nor its model: {refused}"
        );
        assert!(session.standing_definition().is_none());
        assert_eq!(
            stored.agent(),
            Some("rule-reviewer"),
            "the name was dropped"
        );
        let _ = std::fs::remove_dir_all(&home);
    }

