    /// A command that changes something waits behind a line typed before it that could change what
    /// it acts on, so it lands where it was typed: `/rename` ahead of a waiting `/clear` would name
    /// the session `/clear` leaves, `/forget-trust` ahead of a waiting `/cd` would forget the
    /// directory `/cd` leaves, and `/effort` ahead of a waiting prompt would change the level that
    /// prompt was typed under. It says which line it waits behind, so the person can find that line
    /// under the box.
    #[test]
    fn a_command_that_changes_something_waits_behind_what_was_typed_first() {
        let prompt = t!(queued_a_prompt);
        for (first, then, behind) in [
            (CLEAR_COMMAND, "/rename deploy watch", CLEAR_COMMAND),
            (CLEAR_COMMAND, "/note the wrong file", CLEAR_COMMAND),
            ("/cd crates/tui", FORGET_TRUST_COMMAND, "/cd crates/tui"),
            ("second", "/effort high", prompt),
            ("second", "/advisor some-model", prompt),
            ("second", EFFORT_COMMAND, prompt),
            ("second", MODEL_COMMAND, prompt),
            (COMPACT_COMMAND, "/rename deploy watch", COMPACT_COMMAND),
        ] {
            let mut session = a_turn_running_on("first");
            type_while_working(&mut session, first);
            let before = said_under_the_turn(&session).len();

            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, then, key(KeyCode::Enter), beside)
            });

            let said = said_under_the_turn(&session);
            assert!(
                said.len() == before + 1 && said[before].ends_with(&format!("behind {behind}.")),
                "{then} was carried out ahead of a waiting {first}: {said:?}"
            );
            assert_eq!(session.effort(), None, "{then} set a level");
            assert!(
                session.picking().is_none(),
                "{then} opened a picker ahead of a waiting {first}"
            );
            assert_eq!(waiting_prompts(&session), vec![first, then]);
        }
    }

    /// The line named is the first one waiting that could change what the command acts on. A waiting
    /// `/sandbox off` ahead of it is not that line, and a later one is not the first.
    #[test]
    fn a_command_names_the_first_waiting_line_that_holds_it_back() {
        let mut session = a_turn_running_on("first");
        for line in ["/sandbox off", CLEAR_COMMAND, "/cd crates/tui"] {
            wait_as(&mut session, line);
        }
        let before = said_under_the_turn(&session).len();

        nothing_beside(|beside| {
            typed_during_a_turn(&mut session, "/note a thought", key(KeyCode::Enter), beside)
        });

        let said = said_under_the_turn(&session);
        assert!(
            said.len() == before + 1 && said[before].ends_with("behind /clear."),
            "{said:?}"
        );
    }

    /// A line waiting for the turn to end, as `line` would have become had the turn been running
    /// when it was typed behind others: a command line when it starts with `!`, a command that
    /// waits whatever it is when it starts with a slash, and a prompt otherwise.
    fn wait_as(session: &mut Session, line: &str) {
        if let Some(command_line) = line.strip_prefix('!') {
            session.shell = true;
            type_while_working(session, command_line);
            return;
        }
        if !line.starts_with('/') {
            type_while_working(session, line);
            return;
        }
        for c in line.chars() {
            handle_key_while_working(session, key(KeyCode::Char(c)));
        }
        assert!(session.queue_command(), "{line} was not queued");
    }

    /// A record for a command carried out mid-turn to write to.
    fn a_record_to_write_a_link_to() -> bravebot_session::sessions::Handle {
        bravebot_session::sessions::Handle::begin(
            std::path::Path::new("/work"),
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        )
    }

    /// `line` typed and sent during a turn, carried out on `stored`.
    fn typed_on_a_record(
        session: &mut Session,
        stored: &mut bravebot_session::sessions::Handle,
        line: &str,
    ) {
        typed_during_a_turn(
            session,
            line,
            key(KeyCode::Enter),
            &mut Beside {
                managed: &bravebot_config::Managed::default(),
                stored,
                root: std::path::Path::new("/work"),
                home: None,
                workspace: &a_workspace(),
                scratch: None,
                config: &mut a_config_needing_no_sign_in(),
            },
        );
    }

    /// `/issue` and `/pr` act on the link the record holds, and a line waiting ahead changes which
    /// record that is only by starting another, switching to one or leaving this one. Behind any
    /// other line the link is set when it is typed, the line stays where it was, and the link is
    /// said under the turn. The regression it rejects is every line holding a link back, which leaves
    /// one typed behind a prompt, a command line or a command that keeps the record unset until the
    /// turn ends.
    #[test]
    fn a_link_typed_behind_a_line_that_keeps_the_record_is_set_when_typed() {
        use bravebot_session::sessions::Link;
        const ISSUE: &str = "https://github.com/brave/bravebot/issues/2688";
        const PULL: &str = "https://github.com/brave/bravebot/pull/2884";
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "second",
            "!make",
            "/add-dir ../other",
            "/cd crates/tui",
            "/compact",
            "/btw what is this",
            "/recap",
            "/reach",
            "/loop 5m check the deploy",
            "/goal the tests pass",
            "/checkouts",
            "/plan the task",
            "/manifest the task",
            "/agent reviewer the task",
            "/memory",
            "/init",
            "/review",
            "/undo",
            "/rewind",
            "/hunks",
            "/mcp",
            "/rename deploy watch",
            "/note a thought",
            "/style off",
            "/forget-trust",
            "/sandbox off",
            "/model",
            "/effort high",
            "/advisor off",
        ] {
            let mut session = a_turn_running_on("first");
            wait_as(&mut session, waiting);
            let mut stored = a_record_to_write_a_link_to();

            typed_on_a_record(&mut session, &mut stored, &format!("/issue {ISSUE}"));
            typed_on_a_record(&mut session, &mut stored, &format!("/pr {PULL}"));

            assert_eq!(
                stored.link(Link::Issue),
                Some(ISSUE),
                "/issue waited behind {waiting}"
            );
            assert_eq!(
                stored.link(Link::PullRequest),
                Some(PULL),
                "/pr waited behind {waiting}"
            );
            assert_eq!(
                said_under_the_turn(&session)
                    .into_iter()
                    .rev()
                    .take(2)
                    .collect::<Vec<_>>(),
                vec![
                    t!(session_pull_request_set, url = PULL).as_str(),
                    t!(session_issue_set, url = ISSUE).as_str()
                ],
                "behind {waiting}"
            );
            assert_eq!(
                waiting_prompts(&session),
                vec![waiting.trim_start_matches('!')]
            );
        }
    }

    /// A line that starts another record, switches to one or leaves this one changes which record a
    /// link set before it lands on, so `/issue` and `/pr` wait behind it and name it. The regression
    /// it rejects is a link carried out ahead of one of them: it would land on the record the
    /// command leaves, and the record the person goes on in would hold none.
    #[test]
    fn a_link_typed_behind_a_line_that_replaces_the_record_waits_behind_it() {
        use bravebot_session::sessions::Link;
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            CLEAR_COMMAND,
            "/handoff the next goal",
            "/branch",
            "/resume",
            BACKGROUND_COMMAND,
            EXIT_COMMAND,
        ] {
            for line in [
                "/issue https://github.com/brave/bravebot/issues/2688",
                "/pr https://github.com/brave/bravebot/pull/2884",
            ] {
                let mut session = a_turn_running_on("first");
                wait_as(&mut session, waiting);
                let before = said_under_the_turn(&session).len();
                let mut stored = a_record_to_write_a_link_to();

                typed_on_a_record(&mut session, &mut stored, line);

                let said = said_under_the_turn(&session);
                assert!(
                    said.len() == before + 1
                        && said[before].ends_with(&format!("behind {waiting}.")),
                    "{line} was carried out ahead of a waiting {waiting}: {said:?}"
                );
                assert_eq!(stored.link(Link::Issue), None, "{line} behind {waiting}");
                assert_eq!(
                    stored.link(Link::PullRequest),
                    None,
                    "{line} behind {waiting}"
                );
                assert_eq!(waiting_prompts(&session), vec![waiting, line]);
            }
        }
    }

    /// `/model`, `/effort` and `/advisor` act on the choice a request is built with, which a command
    /// line, a command that rewrites only the conversation, the directories, the record or the
    /// session's other settings, and a command that only lists or reports, leave as it is. Behind
    /// one the choice is made when it is typed. The regression it rejects is every line holding the
    /// choice back, which leaves a level typed behind a `/clear` unset until the turn ends.
    #[test]
    fn a_model_level_or_advisor_typed_behind_a_line_that_builds_no_request_is_set_when_typed() {
        use crate::picking::Picking;
        use bravebot_aichat::protocol::Effort;
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "!make",
            CLEAR_COMMAND,
            "/undo",
            "/rewind",
            "/hunks",
            "/memory",
            "/reach",
            "/branch",
            "/add-dir ../other",
            "/cd crates/tui",
            "/mcp",
            "/rename deploy watch",
            "/note a thought",
            "/style off",
            FORGET_TRUST_COMMAND,
            "/issue https://github.com/brave/bravebot/issues/2688",
            "/pr https://github.com/brave/bravebot/pull/2884",
            "/sandbox off",
        ] {
            let mut session = a_turn_running_on("first");
            wait_as(&mut session, waiting);
            let before = said_under_the_turn(&session).len();

            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, "/effort high", key(KeyCode::Enter), beside)
            });
            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, "/advisor off", key(KeyCode::Enter), beside)
            });
            beside_holding(&mut a_config_offering_three_tiers(), |beside| {
                typed_during_a_turn(&mut session, MODEL_COMMAND, key(KeyCode::Enter), beside)
            });

            assert_eq!(
                session.effort(),
                Some(Effort::High),
                "/effort waited behind {waiting}"
            );
            assert!(
                said_under_the_turn(&session)[before..]
                    .iter()
                    .any(|said| *said == t!(session_advisor_dropped)),
                "/advisor waited behind {waiting}"
            );
            assert!(
                matches!(session.picking(), Some(Picking::Model(_))),
                "/model waited behind {waiting}"
            );
            assert_eq!(
                waiting_prompts(&session),
                vec![waiting.trim_start_matches('!')]
            );
        }
    }

    /// A prompt, a command that sends a request, a command that switches the session or leaves it,
    /// and another of the three read or replace the choice a request is built with, so `/model`,
    /// `/effort` and `/advisor` wait behind them and name them. The regression it rejects is the
    /// choice carried out ahead of a line that was typed under the old one: the compaction, the
    /// aside or the turn would run on a level its person set after asking for it.
    #[test]
    fn a_model_level_or_advisor_typed_behind_a_line_that_builds_a_request_waits_behind_it() {
        for waiting in [
            "second",
            "/compact",
            "/btw what is this",
            "/recap",
            "/handoff the next goal",
            "/init",
            "/review",
            "/plan the task",
            "/manifest the task",
            "/agent reviewer the task",
            "/loop 5m check the deploy",
            "/goal the tests pass",
            "/checkouts",
            "/resume",
            BACKGROUND_COMMAND,
            EXIT_COMMAND,
            MODEL_COMMAND,
            "/effort low",
            "/advisor off",
        ] {
            for then in ["/effort high", "/advisor off", MODEL_COMMAND] {
                let mut session = a_turn_running_on("first");
                wait_as(&mut session, waiting);
                let before = said_under_the_turn(&session).len();

                nothing_beside(|beside| {
                    typed_during_a_turn(&mut session, then, key(KeyCode::Enter), beside)
                });

                let behind = if waiting.starts_with('/') {
                    waiting
                } else {
                    t!(queued_a_prompt)
                };
                let said = said_under_the_turn(&session);
                assert!(
                    said.len() == before + 1
                        && said[before].ends_with(&format!("behind {behind}.")),
                    "{then} was carried out ahead of a waiting {waiting}: {said:?}"
                );
                assert_eq!(session.effort(), None, "{then} behind {waiting}");
                assert!(session.picking().is_none(), "{then} behind {waiting}");
                assert_eq!(waiting_prompts(&session), vec![waiting, then]);
            }
        }
    }

    /// The line a choice waits behind is the first one waiting that could change it. A `/clear` and
    /// a `/cd` ahead of it leave the choice alone and are not the line named.
    #[test]
    fn a_choice_names_the_first_waiting_line_that_could_change_it() {
        let mut session = a_turn_running_on("first");
        for line in [
            CLEAR_COMMAND,
            "/cd crates/tui",
            COMPACT_COMMAND,
            "/btw what is this",
        ] {
            wait_as(&mut session, line);
        }
        let before = said_under_the_turn(&session).len();

        nothing_beside(|beside| {
            typed_during_a_turn(&mut session, "/effort high", key(KeyCode::Enter), beside)
        });

        let said = said_under_the_turn(&session);
        assert!(
            said.len() == before + 1 && said[before].ends_with("behind /compact."),
            "{said:?}"
        );
    }

    /// `/style` typed during a turn with `waiting` queued ahead of it. Returns the session and what
    /// was said under the turn since `waiting` was queued.
    fn a_style_typed_behind(waiting: &str, line: &str) -> (Session, Vec<String>) {
        let mut session = a_turn_running_on("first");
        wait_as(&mut session, waiting);
        let before = said_under_the_turn(&session).len();
        nothing_beside(|beside| {
            typed_during_a_turn(&mut session, line, key(KeyCode::Enter), beside)
        });
        let said = said_under_the_turn(&session)[before..]
            .iter()
            .map(|said| said.to_string())
            .collect();
        (session, said)
    }

    /// A turn reads the style when it is built, and nothing a command line, a request that is not a
    /// turn, a write to the record, a rewind or a hunk put back, a server started or a prompt armed
    /// for later does changes which style a name is, so behind any of those `/style` is carried out
    /// when it is typed and the line stays where it was. The regression it rejects is every line
    /// holding it back, which leaves a style picked behind a `!make` or an `/undo` unset until the
    /// turn ends.
    #[test]
    fn a_style_typed_behind_a_line_that_cannot_change_it_is_carried_out_when_typed() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "!make",
            "/compact",
            "/btw what is this",
            "/recap",
            "/memory",
            "/undo",
            "/rewind",
            "/hunks",
            "/mcp",
            "/after 5m check the deploy",
            "/rename deploy watch",
            "/note a thought",
            FORGET_TRUST_COMMAND,
            "/issue https://github.com/brave/bravebot/issues/2688",
            "/pr https://github.com/brave/bravebot/pull/2884",
            "/sandbox off",
            "/model",
            "/effort high",
            "/advisor off",
        ] {
            let (session, said) = a_style_typed_behind(waiting, "/style concise");
            assert_eq!(
                session.style().map(|style| style.name.to_string()),
                Some("concise".to_string()),
                "/style waited behind {waiting}"
            );
            assert_eq!(said, [t!(session_style_set, style = "concise")]);
            assert_eq!(
                waiting_prompts(&session),
                vec![waiting.trim_start_matches('!')]
            );
        }
    }

    /// A prompt begins a turn that reads the style, a line that begins a turn does the same, one that
    /// leaves for another session starts the next from the style settings name, and one that moves
    /// or ends the reach decides whether a file under `~/.bravebot` is one a name is looked up among,
    /// so `/style` waits behind each and names it. The regression it rejects is
    /// the list of lines that leave the style alone extended to a prompt: a style picked behind a
    /// waiting prompt would open the turn that prompt began, which the person typed under the old one.
    #[test]
    fn a_style_typed_behind_a_line_that_could_change_it_waits_behind_it() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "second",
            CLEAR_COMMAND,
            "/cd crates/tui",
            "/add-dir ../other",
            "/reach",
            "/branch",
            "/handoff the next goal",
            "/resume",
            BACKGROUND_COMMAND,
            EXIT_COMMAND,
            "/plan the task",
            "/init",
            "/review",
            "/loop 5m check the deploy",
        ] {
            // A prompt is named by what it is and a command by the line typed.
            let named = match waiting {
                "second" => t!(queued_a_prompt).to_string(),
                command => command.to_string(),
            };
            let (session, said) = a_style_typed_behind(waiting, "/style concise");
            assert!(
                said.len() == 1 && said[0].ends_with(&format!("behind {named}.")),
                "/style was carried out ahead of a waiting {waiting}: {said:?}"
            );
            assert!(session.style().is_none(), "/style behind {waiting}");
            assert_eq!(waiting_prompts(&session), vec![waiting, "/style concise"]);
        }
    }

    /// `/forget-trust` typed during a turn with `waiting` queued ahead of it, with an answer kept
    /// about the directory. Returns whether the answer is still kept, what was said under the turn
    /// since `waiting` was queued, the lines waiting and the directory. `None` where the filesystem
    /// keeps no birth time, which a sibling test covers.
    fn trust_forgotten_behind(
        waiting: &str,
    ) -> Option<(bool, Vec<String>, Vec<String>, std::path::PathBuf)> {
        use bravebot_agent::trusted::{Identity, Store};
        let slug: String = waiting
            .chars()
            .filter(char::is_ascii_alphanumeric)
            .collect();
        let scratch = crate::testutil::scratch_dir(&format!("bravebot-app-forget-trust-{slug}"));
        let _ = std::fs::remove_dir_all(&scratch);
        let home = scratch.join("home");
        let root = scratch.join("work");
        std::fs::create_dir_all(&root).expect("create");
        let identity = Identity::of(&root)?;
        let store = Store::new(&home, &root);
        assert!(store.keep(&identity, "1-2", 7, false));
        let mut session = a_turn_running_on("first");
        wait_as(&mut session, waiting);
        let before = said_under_the_turn(&session).len();
        let mut stored = bravebot_session::sessions::Handle::begin(
            &root,
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        );
        typed_during_a_turn(
            &mut session,
            FORGET_TRUST_COMMAND,
            key(KeyCode::Enter),
            &mut Beside {
                managed: &bravebot_config::Managed::default(),
                stored: &mut stored,
                root: &root,
                home: Some(&home),
                workspace: &a_workspace(),
                scratch: None,
                config: &mut a_config_needing_no_sign_in(),
            },
        );
        let said = said_under_the_turn(&session)[before..]
            .iter()
            .map(|said| said.to_string())
            .collect();
        let waiting = waiting_prompts(&session)
            .into_iter()
            .map(str::to_string)
            .collect();
        let kept = store.kept(&identity).is_some();
        let _ = std::fs::remove_dir_all(&scratch);
        Some((kept, said, waiting, root))
    }

    /// The answer kept about the directory is read by a line that starts a session there and
    /// changed by one that moves the directory or leaves the session, and a prompt or a command line
    /// can run a program that makes the `.git` entry that moves the root around the directory. A
    /// request that is not a turn, a write to the record or the session's own choices, a directory
    /// opened or closed, a reach granted and a copy of the record do none of those, so behind them
    /// `/forget-trust` is carried out when it is typed. The regression it rejects is every line
    /// holding it back, which leaves an answer a person withdrew in place until the turn ends.
    #[test]
    fn a_forgotten_answer_typed_behind_a_line_that_cannot_change_it_is_carried_out_when_typed() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "/compact",
            "/btw what is this",
            "/recap",
            "/memory",
            "/add-dir ../other",
            "/add-dir close ../other",
            "/reach",
            "/reach docker -- docker build .",
            "/branch",
            "/branch try the other parser",
            "/after 5m check the deploy",
            "/rename deploy watch",
            "/note a thought",
            "/style off",
            "/issue https://github.com/brave/bravebot/issues/2688",
            "/pr https://github.com/brave/bravebot/pull/2884",
            "/sandbox off",
            "/model",
            "/effort high",
            "/advisor off",
        ] {
            let Some((kept, said, waiting_lines, root)) = trust_forgotten_behind(waiting) else {
                return;
            };
            assert!(!kept, "/forget-trust waited behind {waiting}");
            assert_eq!(
                said,
                [t!(session_trust_forgotten, directory = root.display())],
                "behind {waiting}"
            );
            assert_eq!(waiting_lines, vec![waiting]);
        }
    }

    /// A prompt and a command line can run a program that makes a `.git` entry, which changes which
    /// answers `/forget-trust` withdraws. A line that starts a session here reads the answer, one
    /// that moves the directory or leaves the session changes what is withdrawn, one that starts a
    /// server or puts files back has not been shown unable to make or remove the `.git` entry, and a
    /// command not read against the file the answer is kept in is held back like them, so the answer
    /// is kept and the command waits, naming the line. The regression it rejects is a command line,
    /// a prompt, or one of those commands added to the lines that leave the answer alone.
    #[test]
    fn a_forgotten_answer_typed_behind_a_line_that_could_change_it_waits_behind_it() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "second",
            "!make",
            CLEAR_COMMAND,
            "/handoff the next goal",
            "/resume",
            BACKGROUND_COMMAND,
            EXIT_COMMAND,
            "/cd crates/tui",
            "/mcp",
            "/undo",
            "/rewind",
            "/hunks",
            "/plan the task",
            "/init",
            "/review",
            "/loop 5m check the deploy",
        ] {
            let Some((kept, said, waiting_lines, _)) = trust_forgotten_behind(waiting) else {
                return;
            };
            // A prompt is named by what it is, a command line by that, and a command by the line.
            let named = match waiting {
                "second" => t!(queued_a_prompt).to_string(),
                "!make" => t!(queued_a_shell_line).to_string(),
                command => command.to_string(),
            };
            assert!(kept, "/forget-trust was carried out ahead of {waiting}");
            assert!(
                said.len() == 1 && said[0].ends_with(&format!("behind {named}.")),
                "behind {waiting}: {said:?}"
            );
            assert_eq!(
                waiting_lines,
                vec![waiting.trim_start_matches('!'), FORGET_TRUST_COMMAND]
            );
        }
    }

    /// `line` typed during a turn with `waiting` queued ahead of it, on a fresh record. Returns the
    /// session, the record, and what was said under the turn since `waiting` was queued.
    fn typed_behind(
        waiting: &str,
        line: &str,
    ) -> (Session, bravebot_session::sessions::Handle, Vec<String>) {
        let mut session = a_turn_running_on("first");
        wait_as(&mut session, waiting);
        let before = said_under_the_turn(&session).len();
        let mut stored = a_record_to_write_a_link_to();
        typed_on_a_record(&mut session, &mut stored, line);
        let said = said_under_the_turn(&session)[before..]
            .iter()
            .map(|said| said.to_string())
            .collect();
        (session, stored, said)
    }

    /// `/note` and `/rename` act on the notes and the name a record holds. A line waiting ahead of
    /// them changes those only by beginning a turn, changing the turn count, putting a rewind point
    /// back, or moving or replacing the record, so behind a command line, or a command that leaves
    /// the record alone, each is carried out when it is typed and the line stays where it was. The
    /// regression it rejects is every line holding them back, which leaves a note typed behind a
    /// `!make` unwritten, and a name unset, until the turn ends.
    #[test]
    fn a_note_or_a_name_typed_behind_a_line_that_leaves_the_record_alone_is_carried_out_when_typed()
    {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "!make",
            "/add-dir ../other",
            "/reach",
            "/memory",
            "/mcp",
            "/style off",
            FORGET_TRUST_COMMAND,
            "/issue https://github.com/brave/bravebot/issues/2688",
            "/pr https://github.com/brave/bravebot/pull/2884",
            "/sandbox off",
            "/model",
            "/effort high",
            "/advisor off",
        ] {
            let (session, stored, said) = typed_behind(waiting, "/note remember the deploy");
            assert_eq!(stored.notes().len(), 1, "/note waited behind {waiting}");
            assert_eq!(stored.notes()[0].text, "remember the deploy");
            assert_eq!(stored.notes()[0].turn, 1, "behind {waiting}");
            assert_eq!(said, [t!(session_note_added, turn = 1)], "behind {waiting}");
            assert_eq!(
                waiting_prompts(&session),
                vec![waiting.trim_start_matches('!')]
            );

            let (session, stored, said) = typed_behind(waiting, "/rename deploy watch");
            assert_eq!(
                stored.title(),
                "deploy watch",
                "/rename waited behind {waiting}"
            );
            assert_eq!(
                said,
                [t!(session_renamed, title = "deploy watch")],
                "behind {waiting}"
            );
            assert_eq!(
                waiting_prompts(&session),
                vec![waiting.trim_start_matches('!')]
            );
        }
        // Each leaves the other alone: the first writes the notes, the second the name.
        let (_, stored, _) = typed_behind("/rename deploy watch", "/note a thought");
        assert_eq!(stored.notes().len(), 1, "/note waited behind /rename");
        let (_, stored, _) = typed_behind("/note a thought", "/rename deploy watch");
        assert_eq!(
            stored.title(),
            "deploy watch",
            "/rename waited behind /note"
        );
    }

    /// A prompt begins a turn and so changes the turn count a note is stamped with, and a command
    /// that begins one, changes the count, puts a point back, or moves or replaces the record changes
    /// the notes and the name the record holds, so `/note` and `/rename` wait behind each and name
    /// it. The regression it rejects is the record's lines left out of the rule: a note typed behind
    /// a prompt would be stamped with the turn the prompt is about to replace, and a name typed
    /// behind `/undo` would be put back by it.
    #[test]
    fn a_note_or_a_name_typed_behind_a_line_that_could_change_the_record_waits_behind_it() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for waiting in [
            "second",
            CLEAR_COMMAND,
            "/compact",
            "/btw what is this",
            "/recap",
            "/cd crates/tui",
            "/handoff the next goal",
            "/branch",
            "/resume",
            BACKGROUND_COMMAND,
            EXIT_COMMAND,
            "/undo",
            "/rewind",
            "/hunks",
            "/plan the task",
            "/init",
            "/review",
            "/loop 5m check the deploy",
        ] {
            // A prompt is named by what it is and a command by the line typed.
            let named = match waiting {
                "second" => t!(queued_a_prompt).to_string(),
                command => command.to_string(),
            };
            for line in ["/note a thought", "/rename deploy watch"] {
                let (session, stored, said) = typed_behind(waiting, line);
                assert!(
                    said.len() == 1 && said[0].ends_with(&format!("behind {named}.")),
                    "{line} was carried out ahead of a waiting {waiting}: {said:?}"
                );
                assert!(stored.notes().is_empty(), "{line} behind {waiting}");
                assert_eq!(stored.title(), "", "{line} behind {waiting}");
                assert_eq!(waiting_prompts(&session), vec![waiting, line]);
            }
        }
    }

    /// A waiting `/sandbox off` moves the mode the next turn is built with and writes nothing else,
    /// so a command that changes something else gives the same result before it as after it, and is
    /// carried out as it is typed. The regression it rejects is every command waiting behind it,
    /// which leaves a note typed behind `/sandbox off` unwritten for as long as the turn runs.
    #[test]
    fn a_note_typed_behind_a_waiting_sandbox_off_is_carried_out_when_typed() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let mut session = a_turn_running_on("first");
        wait_as(&mut session, "/sandbox off");
        let before = said_under_the_turn(&session).len();
        let root = std::path::Path::new("/work");
        let mut stored = bravebot_session::sessions::Handle::begin(
            root,
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        );

        typed_during_a_turn(
            &mut session,
            "/note remember the deploy",
            key(KeyCode::Enter),
            &mut Beside {
                managed: &bravebot_config::Managed::default(),
                stored: &mut stored,
                root,
                home: None,
                workspace: &a_workspace(),
                scratch: None,
                config: &mut a_config_needing_no_sign_in(),
            },
        );

        let notes = stored.notes();
        assert_eq!(notes.len(), 1, "the note waited behind /sandbox off");
        assert_eq!(notes[0].text, "remember the deploy");
        assert_eq!(waiting_prompts(&session), vec!["/sandbox off"]);
        assert_eq!(
            said_under_the_turn(&session)[before..],
            [t!(session_note_added, turn = 1)]
        );
        assert_eq!(
            session.sandbox_mode(),
            bravebot_sandbox::SandboxMode::WorkspaceWrite
        );
    }

    /// Every command that changes something but `/sandbox` leaves a waiting `/sandbox off` alone, so
    /// none of them waits behind it. The fixture gives each a result that tells carrying it out from
    /// waiting: a level set, a name given, a link set, a refusal said.
    #[test]
    fn every_settings_command_but_sandbox_is_carried_out_behind_a_waiting_sandbox_off() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for line in [
            "/effort high",
            "/rename deploy watch",
            "/advisor off",
            "/style off",
            "/issue https://github.com/brave/bravebot/issues/1",
            "/pr https://github.com/brave/bravebot/pull/2",
            FORGET_TRUST_COMMAND,
        ] {
            let mut session = a_turn_running_on("first");
            wait_as(&mut session, "/sandbox off");
            let before = said_under_the_turn(&session).len();

            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, line, key(KeyCode::Enter), beside)
            });

            let said = said_under_the_turn(&session);
            assert_eq!(said.len(), before + 1, "{line} said nothing: {said:?}");
            assert!(
                !said[before].contains("waits for the turn to end"),
                "{line} waited behind /sandbox off: {said:?}"
            );
            assert_eq!(waiting_prompts(&session), vec!["/sandbox off"], "{line}");
        }
    }

    /// `/sandbox` is the one command a waiting `/sandbox off` holds back: the mode typed after it is
    /// the one the person means to end up in, so it lands after `off` and names it. Carried out
    /// first, `off` would be the mode the next turn is built with.
    #[test]
    fn a_sandbox_mode_typed_behind_a_waiting_sandbox_off_waits_behind_it() {
        let mut session = a_turn_running_on("first");
        wait_as(&mut session, "/sandbox off");

        nothing_beside(|beside| {
            typed_during_a_turn(&mut session, "/sandbox strict", key(KeyCode::Enter), beside)
        });

        assert_eq!(
            waiting_prompts(&session),
            vec!["/sandbox off", "/sandbox strict"]
        );
        assert_eq!(
            session.sandbox_mode(),
            bravebot_sandbox::SandboxMode::WorkspaceWrite
        );
        let said = said_under_the_turn(&session);
        assert!(
            said.last()
                .is_some_and(|said| said.ends_with("behind /sandbox off.")),
            "{said:?}"
        );
    }

    /// `/theme` and `/config` change only how the screen is drawn and what the box edits in, which
    /// no waiting line reads or changes, so neither waits behind any of them. The regression it
    /// rejects is either waiting for a turn to end behind a line it has nothing to do with, with the
    /// picker a bare word opens not drawn until then.
    #[test]
    fn a_theme_or_config_typed_behind_a_waiting_line_is_carried_out_when_typed() {
        use crate::picking::Picking;
        let _held = crate::theme::exclusive();
        crate::theme::apply_brave();
        for first in [CLEAR_COMMAND, "second", "/sandbox off", "/cd crates/tui"] {
            let mut session = a_turn_running_on("first");
            wait_as(&mut session, first);

            nothing_beside(|beside| {
                typed_during_a_turn(
                    &mut session,
                    "/theme no-such-theme",
                    key(KeyCode::Enter),
                    beside,
                )
            });

            assert_eq!(
                said_under_the_turn(&session).last().copied(),
                Some(t!(session_no_such_theme, theme = "no-such-theme").as_str()),
                "/theme waited behind {first}"
            );
            assert_eq!(waiting_prompts(&session), vec![first]);

            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, CONFIG_COMMAND, key(KeyCode::Enter), beside)
            });

            assert!(
                session
                    .picking()
                    .is_some_and(|picking| matches!(picking, Picking::Editing(_))),
                "/config waited behind {first}"
            );
            assert_eq!(waiting_prompts(&session), vec![first]);
        }
    }

    /// `/language` saves a choice the next start reads, which no waiting line reads or changes, so
    /// it does not wait behind any of them. The regression it rejects is the word taking the place
    /// of `/rename` in the queue, behind a `/clear` or a prompt it has nothing to do with.
    #[test]
    fn a_language_typed_behind_a_waiting_line_is_carried_out_when_typed() {
        for first in [CLEAR_COMMAND, "second", "/sandbox off", "/cd crates/tui"] {
            let mut session = a_turn_running_on("first");
            wait_as(&mut session, first);

            nothing_beside(|beside| {
                typed_during_a_turn(
                    &mut session,
                    "/language no-such-language",
                    key(KeyCode::Enter),
                    beside,
                )
            });

            assert_eq!(
                said_under_the_turn(&session).last().copied(),
                Some(
                    t!(
                        session_no_such_language,
                        language = "no-such-language",
                        available = bravebot_i18n::tags().join(", ")
                    )
                    .as_str()
                ),
                "/language waited behind {first}"
            );
            assert_eq!(waiting_prompts(&session), vec![first]);
        }
    }

    /// Every command carried out mid-turn says what it did in the transcript. One that came back as an
    /// action [`turn_key`] has no arm for would be taken off the box and dropped without a word.
    #[test]
    fn every_command_carried_out_mid_turn_answers_in_the_transcript() {
        for command in commands() {
            let line = match command.mid_turn {
                MidTurn::Waits => continue,
                // The bare word opens a picker or the Sessions screen, which are modes of the session and
                // say nothing.
                _ if [CONFIG_COMMAND, MODEL_COMMAND, SESSIONS_COMMAND].contains(&command.name) => {
                    continue;
                }
                _ if [THEME_COMMAND, EFFORT_COMMAND].contains(&command.name) => {
                    format!("{} no-such-name", command.name)
                }
                // Refused before anything is written, so no directory the fixture names is touched.
                _ if command.name == EXPORT_COMMAND => format!("{} ../refused", command.name),
                MidTurn::Runs | MidTurn::Changes | MidTurn::RunsUnlessItStarts => {
                    command.name.to_string()
                }
            };
            let mut session = a_turn_running_on("first");

            nothing_beside(|beside| {
                typed_during_a_turn(&mut session, &line, key(KeyCode::Enter), beside)
            });

            assert!(
                !said_under_the_turn(&session).is_empty(),
                "{line} typed mid-turn said nothing"
            );
            assert!(session.queued.is_empty(), "{line} waited");
        }
    }

    /// The fallback in [`dispatch_command`] is unreachable, and this is what says so: a word the table
    /// names that no arm answers would be recognised, taken off the box and then quietly dropped, which
    /// is worse than a word nobody recognises. The bare word is enough for every one of them, since a
    /// command that takes an argument takes an empty one.
    #[test]
    fn every_command_in_the_table_dispatches() {
        for command in commands() {
            let mut session = Session::new("none");
            assert_ne!(
                dispatch_command(&mut session, commanded(command.name)),
                Action::None,
                "{} is in the table and does nothing",
                command.name
            );
        }
    }

    /// The point of queueing, and what it used to fail at: a prompt typed mid-turn is put where the
    /// running turn can reach it, not left for a turn that may be minutes away. A person who says
    /// "no, not that file" while an agent works is trying to redirect the work in front of them,
    /// and an instruction that waits for the answer arrives after the thing it was meant to change.
    #[test]
    fn a_prompt_queued_mid_turn_is_within_the_running_turns_reach() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));

        // What the worker holds. Taken before the prompt is queued, exactly as a turn takes it.
        let reaching = session.interjections();
        assert!(reaching.take().is_none(), "something was waiting already");

        for c in "actually stop".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        assert_eq!(
            reaching.take().as_deref(),
            Some("actually stop"),
            "the turn could not reach a prompt typed while it ran"
        );
    }

    /// Until the turn takes it, a queued prompt has not been said: it is drawn above the box as
    /// waiting, and the transcript is for what has happened. It joins the transcript at the moment
    /// the planner is given it, which is what keeps the two reading in the same order.
    #[test]
    fn a_queued_prompt_joins_the_transcript_when_the_planner_is_given_it() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        let said = session
            .transcript
            .iter()
            .filter(|entry| entry.speaker == crate::state::Speaker::User)
            .count();
        assert_eq!(said, 1, "a prompt that had not gone anywhere was recorded");

        session.interjected();
        let said: Vec<&str> = session
            .transcript
            .iter()
            .filter(|entry| entry.speaker == crate::state::Speaker::User)
            .map(|entry| entry.text.as_str())
            .collect();
        assert_eq!(said, vec!["first", "second"]);
        assert!(session.queued.is_empty(), "it is still drawn as waiting");
    }

    /// A prompt still waiting when the turn ends is a turn of its own, as every queued prompt used
    /// to be. What must not happen is both: the copy left for the turn that has finished has to go,
    /// or the same words reach the planner twice, the second time as an interjection into the very
    /// turn they started.
    #[test]
    fn a_prompt_that_outlived_the_turn_is_sent_once() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        let reaching = session.interjections();
        session.complete("done", Vec::new(), 0);
        assert_eq!(session.send_queued().as_deref(), Some("second"));
        assert!(
            reaching.take().is_none(),
            "the prompt was sent as a turn and left waiting to be interjected as well"
        );
    }

    fn ctrl_enter() -> KeyEvent {
        KeyEvent::new(KeyCode::Enter, KeyModifiers::CONTROL)
    }

    /// Ctrl-Enter does to the line what Enter does and then asks for the turn to stop. Enter must
    /// never ask that: somebody queueing a follow-up is not asking to lose the answer being written.
    #[test]
    fn ctrl_enter_queues_the_line_and_stops_the_turn_where_enter_only_queues() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));

        for c in "a".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(
            handle_key_while_working(&mut session, key(KeyCode::Enter)),
            Action::Redraw,
            "Enter stopped the turn"
        );
        for c in "b".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(
            handle_key_while_working(&mut session, ctrl_enter()),
            Action::SendNow
        );
        assert_eq!(session.input(), "", "the line was left in the box");
        assert_eq!(
            session
                .queued
                .iter()
                .map(|line| line.prompt.as_str())
                .collect::<Vec<_>>(),
            ["a", "b"]
        );
    }

    /// The turn loop's half of it: the press that asks for the turn to stop stops it, and Enter
    /// beside it leaves the turn running.
    #[test]
    fn ctrl_enter_stops_the_turn_in_flight_and_enter_does_not() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        let cancel = Cancel::new();

        for c in "a".chars() {
            pressed_during_a_turn(&mut session, key(KeyCode::Char(c)), &cancel);
        }
        pressed_during_a_turn(&mut session, key(KeyCode::Enter), &cancel);
        assert!(!cancel.is_cancelled(), "Enter stopped the turn");

        pressed_during_a_turn(&mut session, ctrl_enter(), &cancel);
        assert!(cancel.is_cancelled(), "Ctrl-Enter left the turn running");
    }

    /// A turn asked to stop takes nothing more, and the interface hears that it has stopped only
    /// when it gets there. A prompt sent in between is drawn as going into the turn unless the stop
    /// is recorded at the press that asked for it.
    #[test]
    fn a_stop_is_recorded_at_the_press_that_asks_for_it() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        let cancel = Cancel::new();
        for c in "second".chars() {
            pressed_during_a_turn(&mut session, key(KeyCode::Char(c)), &cancel);
        }
        pressed_during_a_turn(&mut session, key(KeyCode::Enter), &cancel);
        assert_eq!(session.where_it_goes(0), crate::state::Bound::IntoThisTurn);

        stop_what_is_running(&mut session, &cancel);

        assert_eq!(
            session.where_it_goes(0),
            crate::state::Bound::ItsOwnTurn,
            "still drawn as going into the turn being stopped"
        );
    }

    /// Over an empty box there is nothing to queue, and what is already waiting can go all the same.
    /// A press that did nothing there would leave somebody who queued with Enter no way to hurry it.
    #[test]
    fn ctrl_enter_over_an_empty_box_sends_what_is_already_waiting() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "a".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        assert_eq!(
            handle_key_while_working(&mut session, ctrl_enter()),
            Action::SendNow
        );
    }

    /// With nothing waiting and nothing typed there is nothing to send, so stopping the turn would
    /// be Escape under another name, and a person reaching for Enter who caught Ctrl too would lose
    /// the answer for nothing.
    #[test]
    fn ctrl_enter_with_nothing_to_send_leaves_the_turn_running() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));

        assert_ne!(
            handle_key_while_working(&mut session, ctrl_enter()),
            Action::SendNow
        );
        assert_eq!(session.status, Status::Working);
    }

    /// A compaction, a goal check or a manifest is not a turn, and nothing waiting can go before one
    /// has ended anyway. Ctrl-Enter there queues the line as Enter does and stops nothing: a
    /// compaction stopped half way is work thrown away for no prompt sent any sooner.
    #[test]
    fn ctrl_enter_during_a_single_request_only_queues() {
        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        for c in "a".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }

        assert_eq!(
            handle_key_while_working(&mut session, ctrl_enter()),
            Action::Redraw
        );
        assert_eq!(session.queued.len(), 1, "the line was not queued");
        assert_eq!(session.status, Status::Working);
    }

    /// The whole of what the chord promises, through the stop arm the event loop reaches: the turn
    /// ends, and the prompts that were waiting go as one turn rather than one after another. Nothing
    /// may reach the planner twice on the way, neither as an interjection left behind in the buffer
    /// nor as a second turn.
    #[test]
    fn what_ctrl_enter_hurried_goes_as_one_turn_once_the_turn_stops() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        let reaching = session.interjections();
        for c in "a".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        for c in "b".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(
            handle_key_while_working(&mut session, ctrl_enter()),
            Action::SendNow
        );

        finish_cancelled_turn(&mut session, "first", Some(0));

        assert_eq!(
            queued_next(&mut session),
            Some(Action::Submit("a\nb".to_string()))
        );
        assert!(
            session.queued.is_empty(),
            "a hurried prompt was left waiting"
        );
        assert!(
            reaching.take().is_none(),
            "a prompt sent in the turn was left to be interjected into it as well"
        );
        assert_eq!(
            session
                .transcript
                .iter()
                .filter(|entry| entry.speaker == crate::state::Speaker::User)
                .map(|entry| entry.text.as_str())
                .collect::<Vec<_>>(),
            ["first", "a\nb"]
        );
    }

    /// Three prompts queued during one turn, and the rule that governs them afterwards: the running
    /// turn takes what it can, one becomes the next turn, and the rest go on waiting under the same
    /// rule. What must hold throughout is that the queue on the screen and the buffer the turn takes
    /// from never disagree about how many prompts are waiting.
    #[test]
    fn what_is_still_waiting_stays_in_step_with_what_is_drawn() {
        let mut session = Session::new("none");
        session.type_char('a');
        session.submit();
        let reaching = session.interjections();

        for line in ["one", "two", "three"] {
            for c in line.chars() {
                session.type_char(c);
            }
            assert!(session.queue(), "nothing was queued");
        }

        // The turn takes the first, as it would at a round boundary.
        assert_eq!(reaching.take().as_deref(), Some("one"));
        session.interjected();
        assert_eq!(session.queued.len(), 2);

        // Then it ends with two still waiting. The oldest becomes a turn of its own.
        session.complete("an answer", Vec::new(), 0);
        assert_eq!(session.send_queued().as_deref(), Some("two"));
        assert_eq!(session.queued.len(), 1);

        // And the last is waiting for the turn that just began, not for a second copy of itself.
        assert_eq!(reaching.take().as_deref(), Some("three"));
        assert!(reaching.take().is_none(), "a prompt was waiting twice over");
    }

    /// Up reaches for the last thing the person said, and while prompts are waiting that is the
    /// queue. It walked the history instead, which holds a copy of every queued line: the copy
    /// came back, the person rewrote it, and the prompt they meant to take back went anyway.
    ///
    /// One press for the whole queue, not one press each. A key that gave them back a line at a
    /// time would leave the person pressing it until they guessed there were none left, with the
    /// ones they had already taken back sitting in the box in front of them.
    #[test]
    fn up_takes_back_everything_waiting_rather_than_a_copy_of_it() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        for line in ["second", "third"] {
            for c in line.chars() {
                handle_key_while_working(&mut session, key(KeyCode::Char(c)));
            }
            handle_key_while_working(&mut session, key(KeyCode::Enter));
        }
        assert_eq!(session.queued.len(), 2);

        assert_eq!(
            handle_key_while_working(&mut session, key(KeyCode::Up)),
            Action::Redraw
        );
        assert_eq!(session.input(), "second\nthird");
        assert!(session.queued.is_empty(), "a prompt was left waiting");
    }

    /// Taking a prompt back has to take it out of the turn's reach too, or the key reads as having
    /// done nothing: the line comes back to the box, the person rewrites it, and the copy the turn
    /// was still holding arrives at the planner anyway. Which is the bug the old queue could not
    /// have, because nothing could reach a queued prompt until the turn was over.
    #[test]
    fn taking_the_queue_back_takes_it_out_of_the_turns_reach() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        let reaching = session.interjections();
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        handle_key_while_working(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "second");
        assert!(
            reaching.take().is_none(),
            "a prompt taken back was still on its way to the planner"
        );
    }

    /// The other side of it: a prompt the turn has already been given cannot be taken back, because
    /// the planner has it. Offering it to the box would leave the person editing a line that had
    /// gone, and pressing Enter would say it twice.
    #[test]
    fn a_prompt_the_turn_has_taken_cannot_be_taken_back() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        let reaching = session.interjections();
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));

        // The turn takes it, as it would at its next round boundary.
        assert_eq!(reaching.take().as_deref(), Some("second"));

        handle_key_while_working(&mut session, key(KeyCode::Up));
        assert!(
            !session.input().contains("second"),
            "a prompt the planner already had came back to the box: {}",
            session.input()
        );
    }

    /// With nothing waiting the key means what it has always meant. Taking the queue back is the
    /// exception, and it lasts exactly as long as there is a queue.
    #[test]
    fn up_walks_the_history_again_once_nothing_is_waiting() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        handle_key_while_working(&mut session, key(KeyCode::Up));
        for _ in 0.."second".len() {
            handle_key_while_working(&mut session, key(KeyCode::Backspace));
        }
        assert_eq!(session.input(), "");

        handle_key_while_working(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "second", "the history was out of reach");
    }

    /// A paragraph in the box has rows of its own, and Up moves between them first. Taking the
    /// queue back from the bottom row would pull the waiting prompts in whenever the person only
    /// reached for the row above, and from the top row there is nowhere left to go but the queue.
    #[test]
    fn up_reaches_the_queue_only_from_the_top_row_of_a_paragraph() {
        let mut session = Session::new("none");
        for c in "first".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "waiting".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        for c in "top".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(
            &mut session,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::SHIFT),
        );
        for c in "bottom".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(session.input(), "top\nbottom");
        assert_eq!(session.queued.len(), 1);

        handle_key_while_working(&mut session, key(KeyCode::Up));
        assert_eq!(
            session.queued.len(),
            1,
            "Up took the queue back from the bottom row of a paragraph"
        );
        assert_eq!(session.input(), "top\nbottom");

        handle_key_while_working(&mut session, key(KeyCode::Up));
        assert!(
            session.queued.is_empty(),
            "Up did not reach the queue from the top row"
        );
        assert_eq!(session.input(), "waiting\ntop\nbottom");
    }

    /// Shift-Enter writes a paragraph mid-turn as it does at rest, so it must not be caught by
    /// the arm that queues. A queued half-sentence is worse than one that waits to be finished.
    #[test]
    fn starting_a_line_mid_turn_does_not_queue_it() {
        let mut session = Session::new("none");
        session.type_char('a');
        session.submit();

        for c in "half".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(
            &mut session,
            KeyEvent::new(KeyCode::Enter, KeyModifiers::SHIFT),
        );

        assert!(
            session.queued.is_empty(),
            "a paragraph was sent half-written"
        );
        assert!(session.input().contains('\n'), "no line was started");
    }

    /// Why a key is allowed to mean something different while a turn runs, or `None` where it is
    /// not.
    ///
    /// The whole of the difference between the two paths, in one place. Every one of them is about
    /// sending or about leaving, which are the two things the box does not decide.
    fn allowed_to_differ(key: KeyEvent) -> Option<&'static str> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            // Shift-Enter and Ctrl-J start a line and are not this key.
            KeyCode::Enter if !key.modifiers.contains(KeyModifiers::SHIFT) => Some("sends"),
            KeyCode::Esc => Some("stops the turn in flight"),
            KeyCode::Char('c') if ctrl => Some("stops the turn in flight, and then leaves"),
            KeyCode::Char('d') if ctrl => Some("leaves, which is not something the box does"),
            KeyCode::Char('g') if ctrl => {
                Some("hands the screen the turn is drawing on to an editor")
            }
            KeyCode::Char('p') if ctrl => {
                Some("rewrites the line over the exchange, which a turn in flight holds")
            }
            KeyCode::Char('!') => Some("arms a mode that changes what Enter does"),
            _ => None,
        }
    }

    /// Every key the two paths could see, so a binding added to one and not the other is caught
    /// here rather than by somebody pressing it.
    fn every_key() -> Vec<KeyEvent> {
        let codes = (0x20u8..=0x7e)
            .map(|byte| KeyCode::Char(char::from(byte)))
            .chain([
                KeyCode::Enter,
                KeyCode::Tab,
                KeyCode::BackTab,
                KeyCode::Backspace,
                KeyCode::Delete,
                KeyCode::Insert,
                KeyCode::Home,
                KeyCode::End,
                KeyCode::PageUp,
                KeyCode::PageDown,
                KeyCode::Up,
                KeyCode::Down,
                KeyCode::Left,
                KeyCode::Right,
                KeyCode::Esc,
                KeyCode::F(1),
            ]);
        let modifiers = [
            KeyModifiers::NONE,
            KeyModifiers::CONTROL,
            KeyModifiers::SHIFT,
            KeyModifiers::ALT,
        ];
        codes
            .flat_map(|code| modifiers.iter().map(move |held| KeyEvent::new(code, *held)))
            .collect()
    }

    /// The two paths answer the same set of keys, and the ones they are allowed to disagree about
    /// are named rather than discovered.
    ///
    /// Asserted as a set because a list was the bug. This walked six key codes, and three keys that
    /// send nothing were answered by the idle path alone: none of the three was in the list, so the
    /// test that was supposed to pin the agreement said nothing whatever about any of them.
    #[test]
    fn the_two_paths_answer_the_same_set_of_keys() {
        /// Everything a key press can reach that is not about sending, so a difference in any of it
        /// is a difference the clause forbids.
        fn answered(session: &Session, action: Action) -> String {
            format!(
                "{action:?} input={:?} caret={} scroll={} shell={} shortcuts={} trail={} \
                 stashed={:?} scrolling={} queued={} browsing={} searching={} vi={:?} \
                 interrupted={}",
                session.input(),
                session.caret(),
                session.scroll,
                session.shell,
                session.shortcuts,
                session.show_trail,
                session.stashed(),
                session.scrolling(),
                session.queued.len(),
                session.history.is_browsing(),
                session.searching_history(),
                session.vi_mode(),
                session.cleared_by_interrupt,
            )
        }

        let sent = |finished: bool, editing: crate::vim::Editing, typed: &str| {
            let mut session = Session::new("none");
            session.choose_editing(editing);
            type_line(&mut session, "first question");
            handle_key(&mut session, key(KeyCode::Enter));
            // The same transcript either way, so only the running turn differs.
            if finished {
                session.complete("an answer", Vec::new(), 0);
            } else {
                session.narrate("an answer");
            }
            // Several arms are read against whether there is a line, so both cases are swept.
            for c in typed.chars() {
                if finished {
                    handle_key(&mut session, key(KeyCode::Char(c)));
                } else {
                    handle_key_while_working(&mut session, key(KeyCode::Char(c)));
                }
            }
            // The offer to leave, standing over both sessions as it stands over a turn a tick
            // began: put up by a Ctrl-C that took a line while nothing was running, and carried
            // into the turn by a submission no key press made. It lives for one press, so the
            // press under test takes it down whichever path answers that press.
            session.cleared_by_interrupt = true;
            session
        };

        // Both styles of editing, and in the vi one every mode it has. A key wired into one path and
        // not the other is the bug this catches, and vi editing multiplies the places to wire one:
        // each mode gives every printable character a meaning of its own, so a letter answered by the
        // idle path alone would be a letter that silently did nothing during a turn.
        let modes = [
            None,
            Some(crate::vim::Mode::Normal),
            Some(crate::vim::Mode::Visual { lines: false }),
            Some(crate::vim::Mode::Visual { lines: true }),
            Some(crate::vim::Mode::Replace),
        ];
        for editing in crate::vim::Editing::ALL {
            for mode in modes {
                if mode.is_some() != (editing == crate::vim::Editing::Vi) {
                    continue;
                }
                for line in ["", "half a thought"] {
                    for pressed in every_key() {
                        if allowed_to_differ(pressed).is_some() {
                            continue;
                        }
                        let mut idle = sent(true, editing, line);
                        let mut working = sent(false, editing, line);
                        for session in [&mut idle, &mut working] {
                            match mode {
                                None => {}
                                Some(crate::vim::Mode::Visual { lines }) => {
                                    session.enter_vi_normal();
                                    session.type_char(if lines { 'V' } else { 'v' });
                                }
                                Some(crate::vim::Mode::Replace) => {
                                    session.enter_vi_normal();
                                    session.type_char('R');
                                }
                                Some(_) => {
                                    session.enter_vi_normal();
                                }
                            }
                        }
                        assert_eq!(working.status, Status::Working);
                        assert_eq!(
                            answered(&idle, Action::None),
                            answered(&working, Action::None),
                            "the two sessions differed before {pressed:?} was pressed"
                        );

                        let at_rest = handle_key(&mut idle, pressed);
                        let mid_turn = handle_key_while_working(&mut working, pressed);

                        assert_eq!(
                            answered(&idle, at_rest),
                            answered(&working, mid_turn),
                            "{pressed:?} was answered differently while a turn was running, \
                             over a line of {line:?}, editing {editing:?} in {mode:?}"
                        );
                    }
                }
            }
        }
    }

    /// Down walks back out of history, restoring the line that was being typed.
    #[test]
    fn down_returns_from_history_to_the_typed_line() {
        let mut session = Session::new("none");
        for c in "sent".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);

        for c in "being typed".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "sent");

        handle_key(&mut session, key(KeyCode::Down));
        assert_eq!(
            session.input(),
            "being typed",
            "the half-typed line was not restored"
        );
    }

    /// Typing over a recalled prompt makes it the working line, so the position label goes away.
    #[test]
    fn typing_leaves_history_browsing() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);

        handle_key(&mut session, key(KeyCode::Up));
        assert!(session.history.is_browsing());
        handle_key(&mut session, key(KeyCode::Char('b')));
        assert!(!session.history.is_browsing());
    }

    /// Escape leaves history along with clearing, so it cannot be left labelled with an empty box.
    #[test]
    fn escape_leaves_history_browsing() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);

        handle_key(&mut session, key(KeyCode::Up));
        assert!(session.history.is_browsing());
        handle_key(&mut session, key(KeyCode::Esc));
        assert!(!session.history.is_browsing());
        assert!(session.input().is_empty());
    }

    /// A session that has sent `prompts`, with nothing running.
    fn having_sent(prompts: &[&str]) -> Session {
        let mut session = Session::new("none");
        for prompt in prompts {
            type_line(&mut session, prompt);
            handle_key(&mut session, key(KeyCode::Enter));
            session.complete("ok", Vec::new(), 0);
        }
        session
    }

    /// Escape clears in one press, so a slip loses the paragraph unless Up can bring it back. Nothing
    /// has been sent, so the person has not been asked to send anything to get it.
    #[test]
    fn escape_keeps_the_cleared_line_for_up() {
        let mut session = Session::new("none");
        type_line(&mut session, "half a thought");
        handle_key(&mut session, key(KeyCode::Esc));
        assert_eq!(session.input(), "");

        assert_eq!(handle_key(&mut session, key(KeyCode::Up)), Action::Redraw);
        assert_eq!(session.input(), "half a thought");
        assert_eq!(session.status, Status::Idle, "recalling the draft sent it");
        assert!(session.history.is_empty(), "the draft became a sent prompt");

        handle_key(&mut session, key(KeyCode::Down));
        assert_eq!(session.input(), "", "Down did not leave the draft");
    }

    /// The first rung of Ctrl-C takes the line, and takes it by the same route as Escape.
    #[test]
    fn ctrl_c_keeps_the_cleared_line_for_up() {
        let mut session = Session::new("none");
        type_line(&mut session, "half a thought");
        handle_key(&mut session, ctrl('c'));
        assert_eq!(session.input(), "");

        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "half a thought");
    }

    /// One place to keep a cleared line, so the latest is what Up brings back first and the
    /// earlier one is gone rather than stacked behind it.
    #[test]
    fn a_second_clear_replaces_the_kept_draft() {
        let mut session = having_sent(&["sent before"]);
        type_line(&mut session, "first draft");
        handle_key(&mut session, key(KeyCode::Esc));
        type_line(&mut session, "second draft");
        handle_key(&mut session, ctrl('c'));

        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "second draft");
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(
            session.input(),
            "sent before",
            "the first draft was kept behind the second"
        );
    }

    /// A draft belongs to the line that was being written when it was cleared. Once a prompt goes,
    /// Up walks the sent prompts alone.
    #[test]
    fn sending_a_prompt_drops_the_kept_draft() {
        let mut session = having_sent(&["sent before"]);
        type_line(&mut session, "abandoned");
        handle_key(&mut session, key(KeyCode::Esc));
        type_line(&mut session, "sent after");
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);

        let mut seen = Vec::new();
        for _ in 0..4 {
            handle_key(&mut session, key(KeyCode::Up));
            seen.push(session.input().to_string());
        }
        assert_eq!(
            seen,
            ["sent after", "sent before", "sent before", "sent before"],
            "the draft survived a send"
        );
    }

    /// Clearing a prompt that was only walked back to loses nothing, since the history has it, and
    /// must not push out a draft that was lost.
    #[test]
    fn clearing_a_recalled_prompt_does_not_replace_the_draft() {
        let mut session = having_sent(&["sent before"]);
        type_line(&mut session, "abandoned");
        handle_key(&mut session, key(KeyCode::Esc));
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "sent before");

        handle_key(&mut session, key(KeyCode::Esc));
        assert_eq!(session.input(), "");
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "abandoned");
    }

    /// Clearing a box with nothing to lose keeps nothing, so Up does not bring back blanks.
    #[test]
    fn clearing_an_empty_or_blank_line_keeps_no_draft() {
        let mut session = Session::new("none");
        type_line(&mut session, "a real draft");
        handle_key(&mut session, key(KeyCode::Esc));
        type_line(&mut session, "   ");
        handle_key(&mut session, key(KeyCode::Esc));
        handle_key(&mut session, key(KeyCode::Esc));

        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "a real draft");
    }

    /// The draft is not a sent prompt, so the search over what was sent does not offer it.
    #[test]
    fn the_kept_draft_is_not_a_candidate_for_the_search() {
        let mut session = having_sent(&["sent before"]);
        type_line(&mut session, "abandoned");
        handle_key(&mut session, key(KeyCode::Esc));

        handle_key(&mut session, ctrl('r'));
        let offered: Vec<_> = session
            .history_matches()
            .iter()
            .map(|entry| entry.prompt.clone())
            .collect();
        assert_eq!(offered, ["sent before"]);
    }

    /// The draft in the box is the person's own typing, so Ctrl-S puts it away like any other line
    /// and does not open a search the way it does on a stored prompt.
    #[test]
    fn ctrl_s_on_the_recalled_draft_puts_it_away() {
        let mut session = having_sent(&["sent before"]);
        type_line(&mut session, "abandoned");
        handle_key(&mut session, key(KeyCode::Esc));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "abandoned");

        handle_key(&mut session, ctrl('s'));
        assert!(!session.searching_history());
        assert_eq!(session.input(), "");
        assert_eq!(session.stashed(), Some("abandoned"));
    }

    /// Up walks a prompt at a time, which is no way to reach the hundredth. Ctrl-R is the chord
    /// every shell answers with this question, so it is the one to answer it with here.
    #[test]
    fn ctrl_r_searches_the_prompts_already_sent() {
        let mut session = having_sent(&["first question", "second question"]);
        handle_key(&mut session, ctrl('r'));
        assert!(session.searching_history());
        assert_eq!(
            session.history_match().expect("a prompt").prompt,
            "second question"
        );
    }

    /// Mid-turn is when the prompt somebody wants back is most likely to be one they can no longer
    /// see, and nothing about searching sends anything, which is the whole of what a turn refuses.
    #[test]
    fn the_prompts_can_be_searched_while_a_turn_is_running() {
        let mut session = having_sent(&["first question"]);
        type_line(&mut session, "second question");
        handle_key(&mut session, key(KeyCode::Enter));
        assert_eq!(session.status, Status::Working);

        handle_key_while_working(&mut session, ctrl('r'));
        assert!(session.searching_history());
    }

    /// The loops answer the stop keys before any ladder does, so the guard that lets the search
    /// have them first is the whole of what keeps the keys that close it from ending the turn a
    /// person opened it during. Searching sends nothing, so there was never anything in it for the
    /// turn to refuse.
    #[test]
    fn the_search_answers_the_stop_keys_before_the_turn_does() {
        let mut session = having_sent(&["first question"]);
        type_line(&mut session, "second question");
        handle_key(&mut session, key(KeyCode::Enter));

        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            assert!(
                stops_the_turn(&session, stopping),
                "{stopping:?} did not reach the turn with nothing in the way"
            );
        }

        handle_key_while_working(&mut session, ctrl('r'));
        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            assert!(
                !stops_the_turn(&session, stopping),
                "{stopping:?} stopped the turn from inside the search"
            );
        }

        handle_key_while_working(&mut session, key(KeyCode::Esc));
        assert!(!session.searching_history(), "the search did not close");
        assert_eq!(session.status, Status::Working, "the turn was stopped");
    }

    /// A summary and an aside answer the stop keys themselves, so the search opened while one of
    /// them was out has to be asked before the request is: answered by the request instead, either
    /// key stopped it and the search a person was trying to leave was still open behind.
    #[test]
    fn the_search_answers_the_stop_keys_before_a_single_request_does() {
        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            let mut session = having_sent(&["first question"]);
            session.begin_aside();
            let cancel = Cancel::new();

            one_request_key(&mut session, ctrl('r'), &cancel);
            assert!(session.searching_history(), "the search did not open");

            one_request_key(&mut session, stopping, &cancel);

            assert!(
                !session.searching_history(),
                "{stopping:?} left the search open"
            );
            assert!(!session.is_quitting(), "{stopping:?} ended the session");
            assert!(
                !cancel.is_cancelled(),
                "{stopping:?} stopped the request from inside the search"
            );
        }
    }

    /// The goal check is one request too, and the goal behind it is what its stop keys are for.
    /// Neither key is about the goal or the check while the search is open.
    #[test]
    fn the_search_answers_the_stop_keys_before_the_goal_check_does() {
        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            let mut session = having_sent(&["first question"]);
            session.begin_aside();
            session.start_goal("cargo test exits 0".to_string());
            let cancel = Cancel::new();

            goal_check_key(&mut session, ctrl('r'), &cancel);
            assert!(session.searching_history(), "the search did not open");
            let said = session.transcript.len();

            goal_check_key(&mut session, stopping, &cancel);

            assert!(
                !session.searching_history(),
                "{stopping:?} left the search open"
            );
            assert!(
                session.goal().is_some(),
                "{stopping:?} cleared the goal from inside the search"
            );
            assert!(
                !cancel.is_cancelled(),
                "{stopping:?} stopped the check from inside the search"
            );
            assert!(!session.is_quitting(), "{stopping:?} ended the session");
            assert_eq!(
                session.transcript.len(),
                said,
                "{stopping:?} reported the goal from inside the search"
            );
        }
    }

    /// What the stop keys mean with nothing standing over the request: either one stops it, as it
    /// stops a turn, and no press leaves however many are made. Leaving is the press made with
    /// nothing running, and a person asking for the request to stop twice is not asking for the
    /// session to end.
    #[test]
    fn a_stop_key_stops_a_summary_or_an_aside_and_never_leaves() {
        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            let mut session = having_sent(&["first question"]);
            session.begin_aside();
            let cancel = Cancel::new();
            let said = session.transcript.len();

            one_request_key(&mut session, stopping, &cancel);

            assert!(cancel.is_cancelled(), "{stopping:?} did not stop it");
            assert!(!session.is_quitting(), "{stopping:?} ended the session");
            assert_eq!(
                session.transcript.len(),
                said,
                "{stopping:?} wrote into the transcript before the request had ended"
            );

            one_request_key(&mut session, stopping, &cancel);
            one_request_key(&mut session, stopping, &cancel);
            assert!(
                !session.is_quitting(),
                "{stopping:?} pressed again ended the session"
            );
        }
    }

    /// A request the person stopped says it was stopped. Reported as a failure it would read as the
    /// model or the network having let them down, and silence would read as a press nobody heard.
    /// The session is idle again either way, so the next prompt is not refused.
    #[test]
    fn a_stopped_summary_question_or_brief_says_so_and_is_not_reported_as_a_failure() {
        let mut session = having_sent(&["first question"]);

        session.begin_aside();
        compact_ended(&mut session, 100_000, &Err("offline".to_string()), true);
        assert_eq!(last_note(&session), t!(compact_stopped));
        assert_eq!(session.status, Status::Idle);

        session.begin_aside();
        compact_ended(&mut session, 100_000, &Err("offline".to_string()), false);
        assert_eq!(last_note(&session), t!(compact_failed, problem = "offline"));

        session.begin_aside();
        aside_unanswered(&mut session, Unanswered::Stopped);
        assert_eq!(last_note(&session), t!(btw_stopped));
        assert_eq!(session.status, Status::Idle);

        session.begin_aside();
        aside_unanswered(&mut session, Unanswered::Failed("offline".to_string()));
        assert_eq!(last_note(&session), t!(btw_failed, problem = "offline"));

        session.begin_aside();
        handoff_answered(&mut session, "port the parser", Err(Unanswered::Stopped));
        assert_eq!(last_note(&session), t!(handoff_stopped));
        assert_eq!(session.status, Status::Idle);
        assert!(!session.handoff_pending(), "a stopped brief was offered");
        assert!(session.input().is_empty());
    }

    /// A loopback model answering every request with `words`, streamed the way the real one is.
    #[cfg(unix)]
    fn a_model_answering_every_request(words: &'static str) -> String {
        use std::io::{BufRead, BufReader, Read, Write};

        let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("a port");
        let address = format!("http://{}", listener.local_addr().expect("an address"));
        std::thread::spawn(move || {
            for stream in listener.incoming().flatten() {
                let _ = stream.set_read_timeout(Some(Duration::from_secs(10)));
                let mut reader = BufReader::new(stream);
                let mut line = String::new();
                let mut length = 0usize;
                while matches!(reader.read_line(&mut line), Ok(read) if read > 2) {
                    if let Some((name, value)) = line.split_once(':')
                        && name.eq_ignore_ascii_case("content-length")
                    {
                        length = value.trim().parse().unwrap_or(0);
                    }
                    line.clear();
                }
                let mut body = vec![0u8; length];
                let _ = reader.read_exact(&mut body);
                let frames = format!(
                    "data: {{\"choices\":[{{\"delta\":{{\"content\":\"{words}\"}}}}]}}\n\n\
                     data: {{\"choices\":[{{\"finish_reason\":\"stop\"}}],\"usage\":{{\"prompt_tokens\":400,\"completion_tokens\":20}}}}\n\n"
                );
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{frames}",
                    frames.len()
                );
                let _ = reader.into_inner().write_all(response.as_bytes());
            }
        });
        address
    }

    /// HOOK-2, HOOK-9: the thread `/compact` starts runs the person's `compacted` hook once the
    /// summary is adopted, in the session's directory, and tells the screen which hook is running.
    /// A terminal that handed the agent no hooks would shorten the conversation and fire nothing.
    #[cfg(unix)]
    #[test]
    fn the_thread_that_summarises_fires_the_hooks_in_the_sessions_directory() {
        use std::os::unix::fs::PermissionsExt;

        let directory = crate::testutil::scratch_dir("bravebot-app-compact-hook");
        let _ = std::fs::remove_dir_all(&directory);
        let home = directory.join("state");
        std::fs::create_dir_all(&home).expect("a state directory");
        let note = directory.join("note");
        std::fs::write(&note, "#!/bin/sh\ncat >> fired.txt\n").expect("a script");
        std::fs::set_permissions(&note, std::fs::Permissions::from_mode(0o755)).expect("exec");
        std::fs::write(
            home.join("hooks.json"),
            format!(
                r#"{{"hooks": [{{"on": "compacted", "run": [{:?}]}}]}}"#,
                note.canonicalize().expect("canonical")
            ),
        )
        .expect("a hooks file");
        let workspace = Workspace::new(&directory).expect("workspace");
        let endpoint = a_model_answering_every_request("they were porting the parser");
        let config = Config::from_lookup(|key| match key {
            "SERVICES_KEY_AICHAT" => Some("test-key".into()),
            "BRAVE_SERVICES_KEY_ID" => Some("test-id".into()),
            "BRAVE_AI_CHAT_ENDPOINT" => Some(endpoint.clone()),
            _ => None,
        })
        .expect("config");
        let mut conversation = Conversation::new();
        for (prompt, answer) in [
            ("port the parser to the new lexer", "started on it"),
            ("what about the error type", "widened it"),
            ("now the tests", "updated them"),
            ("carry on", "carrying on"),
        ] {
            conversation.push(bravebot_aichat::protocol::Message::user(prompt));
            conversation.push(bravebot_aichat::protocol::Message::assistant(answer));
        }
        let (to_main, from_worker) = mpsc::channel();

        let (done, shortened, _trail) = summarise_on_a_worker(
            &config,
            &bravebot_agent::chatgpt::AccountSession::begin(),
            conversation,
            None,
            TrustStore::new("/work"),
            None,
            &Cancel::new(),
            &workspace,
            Some(&home),
            to_main,
        );

        let fired = std::fs::read_to_string(directory.join("fired.txt"));
        let said: Vec<String> = from_worker
            .try_iter()
            .filter_map(|message| match message {
                crate::remote_confirm::ToMain::HookStarted(moment, _) => {
                    Some(format!("started {moment}"))
                }
                crate::remote_confirm::ToMain::HookFinished => Some("finished".to_string()),
                _ => None,
            })
            .collect();
        std::fs::remove_dir_all(&directory).ok();

        assert!(matches!(done, Ok(Some(_))), "no summary was adopted");
        assert!(shortened.len() < 8, "the conversation was not shortened");
        assert_eq!(
            fired.expect("the hook did not run in the session's directory"),
            "{\"event\":\"compacted\"}\n"
        );
        assert_eq!(said, ["started compacted", "finished"]);
    }

    /// HOOK-9, HOOK-7: a `compacted` hook runs on the thread that summarised, so the screen is told
    /// which one holds it while it runs and what went wrong when it ended badly. A loop that
    /// dropped those messages would show a frozen `/compact` for as long as the hook took, and say
    /// nothing of a hook that failed.
    #[test]
    fn a_hook_running_after_a_summary_is_named_and_its_trouble_said() {
        let mut session = having_sent(&["first question"]);
        session.begin_aside();

        compact_reported(
            &mut session,
            crate::remote_confirm::ToMain::HookStarted("compacted", "notify".to_string()),
        );
        assert_eq!(
            session.indicator().expect("working").verb,
            t!(indicator_hook, moment = "compacted", program = "notify")
        );

        compact_reported(&mut session, crate::remote_confirm::ToMain::HookFinished);
        assert_ne!(
            session.indicator().expect("working").verb,
            t!(indicator_hook, moment = "compacted", program = "notify"),
            "the hook was still named after it was over"
        );

        let said = t!(
            hook_failed,
            moment = "compacted",
            program = "notify",
            status = "exit status: 3"
        );
        compact_reported(
            &mut session,
            crate::remote_confirm::ToMain::Notice(said.to_string()),
        );
        assert_eq!(last_note(&session), said);
    }

    /// A summary that came back is kept however late the stop landed: the worker has already
    /// shortened the conversation, so reporting the request as stopped would leave a conversation
    /// that is shorter than the screen says.
    #[test]
    fn a_summary_that_came_back_is_kept_though_a_stop_landed_with_it() {
        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        let summary = bravebot_agent::compact::Compacted {
            summarised: 4,
            kept: 2,
            model: "a-model".to_string(),
            usage: Default::default(),
        };

        compact_ended(&mut session, 100_000, &Ok(Some(summary)), true);

        assert_eq!(
            last_note(&session),
            t!(compact_done, summarised = 4, kept = 2)
        );
    }

    /// Each request made beside the work reports what it read and wrote, and the session's split
    /// has to hold both, whichever command made it: a caller that charged the total alone would
    /// leave those tokens in neither column of `stats`.
    #[test]
    fn every_request_beside_the_work_is_charged_with_what_it_read_and_wrote() {
        let usage = bravebot_aichat::protocol::Usage {
            prompt_tokens: 70,
            completion_tokens: 30,
            ..Default::default()
        };
        let charged = |session: &Session| (session.tokens, session.split());
        let expected = (
            100,
            bravebot_session::sessions::Split {
                read: 70,
                written: 30,
            },
        );

        let mut compacted = having_sent(&["first question"]);
        compacted.begin_aside();
        let summary = bravebot_agent::compact::Compacted {
            summarised: 4,
            kept: 2,
            model: "a-model".to_string(),
            usage,
        };
        compact_ended(&mut compacted, 100_000, &Ok(Some(summary)), false);
        assert_eq!(charged(&compacted), expected, "/compact");

        let mut drafting = Session::new("none");
        drafting.begin_aside();
        let mut done = drafted("Fix it");
        done.usage = usage;
        commit_message_answered(&mut drafting, Ok(done));
        assert_eq!(charged(&drafting), expected, "/commit-message");

        let answered = |kept: Option<&str>| bravebot_agent::aside::Answered {
            shown: "a brief".to_string(),
            kept: kept.map(str::to_string),
            usage,
        };
        let mut handed = Session::new("none");
        handed.begin_aside();
        handoff_answered(&mut handed, "port it", Ok(answered(Some("a brief"))));
        assert_eq!(charged(&handed), expected, "/handoff");

        let mut untrusted = Session::new("none");
        untrusted.begin_aside();
        handoff_answered(&mut untrusted, "port it", Ok(answered(None)));
        assert_eq!(charged(&untrusted), expected, "/handoff, nothing kept");

        let mut asked = Session::new("none");
        asked.begin_aside();
        aside_answered(&mut asked, "why?".to_string(), answered(Some("a brief")));
        assert_eq!(charged(&asked), expected, "/btw");

        let mut judged = having_sent(&["first question"]);
        judged.begin_aside();
        judged.start_goal("cargo test exits 0".to_string());
        goal_checked(
            &mut judged,
            Ok(bravebot_agent::goal::Assessed {
                verdict: bravebot_agent::goal::Verdict::NotMet {
                    reason: "nothing above runs the tests".to_string(),
                },
                usage,
            }),
            false,
        );
        assert_eq!(charged(&judged), expected, "a goal check");

        let mut suggesting = Session::new("none");
        suggesting.charge_suggestion(usage);
        assert_eq!(charged(&suggesting), expected, "a suggestion");
    }

    /// Turns that finish are where most of a session's tokens are charged, and the worker's own
    /// count of what it wrote is the only figure that divides them. A fold that charged the total
    /// alone, or divided it the wrong way round, leaves those tokens out of the Read and Written
    /// columns of `stats` or puts them in the wrong one.
    #[test]
    fn a_finished_turn_is_charged_with_what_it_read_and_wrote() {
        let mut session = Session::new("none");

        for (prompt, tokens, written) in [("first", 100, 30), ("second", 250, 40)] {
            type_line(&mut session, prompt);
            handle_key(&mut session, key(KeyCode::Enter));
            complete_turn(
                &mut session,
                "ok".to_string(),
                Vec::new(),
                tokens,
                written,
                None,
            );
        }

        assert_eq!(session.tokens, 350);
        assert_eq!(
            session.split(),
            bravebot_session::sessions::Split {
                read: 280,
                written: 70
            },
            "a finished turn was not charged with how its tokens divide"
        );
    }

    /// The record is written from the session in several places, and all of them build it here, so
    /// the split the session has counted is what reaches the record. A builder that left it out
    /// would write every session with a total and no split.
    #[test]
    fn a_record_built_from_the_session_holds_the_split_it_has_counted() {
        let mut session = Session::new("none");
        session.begin_aside();
        session.end_aside_of(bravebot_aichat::protocol::Usage {
            prompt_tokens: 70,
            completion_tokens: 30,
            ..Default::default()
        });

        let standing = with_standing(
            &session,
            &Conversation::new(),
            &TrustStore::new("/work"),
            &TrustedPrograms::new(),
            &workspace_for_test(),
            |standing| (standing.tokens, standing.split),
        );

        assert_eq!(
            standing,
            (
                100,
                bravebot_session::sessions::Split {
                    read: 70,
                    written: 30
                }
            )
        );
    }

    /// The goal check is one request as well, and there is something behind it worth stopping: the
    /// goal that keeps putting turns out. Both keys take it off, say so, and stop the check with
    /// it, since a person pressing either at the ninth round is asking for the tenth not to go. No
    /// press leaves, however many are made.
    #[test]
    fn a_stop_key_takes_the_goal_off_and_stops_the_check() {
        for stopping in [ctrl('c'), key(KeyCode::Esc)] {
            let mut session = having_sent(&["first question"]);
            session.begin_aside();
            session.start_goal("cargo test exits 0".to_string());
            let cancel = Cancel::new();
            let said = session.transcript.len();

            goal_check_key(&mut session, stopping, &cancel);

            assert!(session.goal().is_none(), "{stopping:?} left the goal armed");
            assert!(cancel.is_cancelled(), "{stopping:?} did not stop the check");
            let after = session.transcript[said..]
                .iter()
                .map(|entry| entry.text.as_str())
                .collect::<Vec<_>>()
                .join("\n");
            assert!(
                after.contains(t!(goal_cleared)),
                "{stopping:?} took the goal off without saying so: {after}"
            );
            assert!(!session.is_quitting(), "{stopping:?} ended the session");

            goal_check_key(&mut session, stopping, &cancel);
            goal_check_key(&mut session, stopping, &cancel);
            assert!(
                !session.is_quitting(),
                "{stopping:?} pressed again ended the session"
            );
        }

        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        let cancel = Cancel::new();
        let said = session.transcript.len();

        goal_check_key(&mut session, key(KeyCode::Esc), &cancel);

        assert!(
            cancel.is_cancelled(),
            "escape did not stop a check with no goal"
        );
        assert_eq!(
            session.transcript.len(),
            said,
            "escape reported something with no goal to take off"
        );

        for _ in 0..3 {
            goal_check_key(&mut session, ctrl('c'), &cancel);
        }
        assert!(
            !session.is_quitting(),
            "ctrl-c left with the goal already off"
        );
    }

    /// A check the person stopped is the request being walked away from, and the key already took
    /// the goal off, so reporting it as a check that failed would tell them the goal could not be
    /// checked a moment after they cleared it. One that failed with no stop pressed is the goal's
    /// own failure, and a verdict that crosses a stop on its way back is dropped.
    #[test]
    fn a_stopped_goal_check_is_not_reported_as_a_failure() {
        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        session.start_goal("cargo test exits 0".to_string());
        session.clear_goal();
        let said = session.transcript.len();

        let carried_on = goal_checked(&mut session, Err("offline".to_string()), true);

        assert!(carried_on.is_none());
        assert_eq!(session.status, Status::Idle);
        assert_eq!(
            session.transcript.len(),
            said,
            "the stopped check was reported: {}",
            last_note(&session)
        );

        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        session.start_goal("cargo test exits 0".to_string());

        let carried_on = goal_checked(&mut session, Err("offline".to_string()), false);

        assert!(carried_on.is_none());
        assert_eq!(
            last_note(&session),
            t!(goal_failed, problem = "offline"),
            "a check that failed with no stop pressed was not reported"
        );

        let mut session = having_sent(&["first question"]);
        session.begin_aside();
        session.start_goal("cargo test exits 0".to_string());
        session.clear_goal();
        let turns = session.turns;
        let said = session.transcript.len();

        let carried_on = goal_checked(
            &mut session,
            Ok(bravebot_agent::goal::Assessed {
                verdict: bravebot_agent::goal::Verdict::NotMet {
                    reason: "nothing above runs the tests".to_string(),
                },
                usage: Default::default(),
            }),
            true,
        );

        assert!(
            carried_on.is_none(),
            "a verdict after the stop sent work back"
        );
        assert_eq!(session.turns, turns);
        assert_eq!(session.transcript.len(), said);
    }

    /// With nothing sent there is nothing to search, and a panel saying so is a mode a person then
    /// has to get out of.
    #[test]
    fn ctrl_r_with_nothing_sent_yet_opens_nothing() {
        let mut session = Session::new("none");
        handle_key(&mut session, ctrl('r'));
        assert!(!session.searching_history());
    }

    /// Walking back at all says the wanted prompt is an old one, and the workspace somebody is in
    /// is the narrower question about it. The list it opens on is the whole point: seeded with the
    /// prompt in the box it would answer with that prompt alone, and narrowed to somewhere else it
    /// would answer with nothing. A line put away earlier is not touched, since the slot holds one
    /// line and this press is not putting anything into it.
    #[test]
    fn ctrl_s_searches_this_workspace_while_an_older_prompt_is_shown() {
        let mut session = Session::new("none");
        for (workspace, prompt) in [
            ("/work/elsewhere", "why is the picker slow"),
            ("/work/here", "commit that"),
            ("/work/here", "run the tests"),
        ] {
            session.now_in_workspace(workspace);
            type_line(&mut session, prompt);
            handle_key(&mut session, key(KeyCode::Enter));
            session.complete("ok", Vec::new(), 0);
        }

        type_line(&mut session, "half a thought");
        handle_key(&mut session, ctrl('s'));
        assert_eq!(
            session.stashed(),
            Some("half a thought"),
            "the line was not put away"
        );

        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(
            session.input(),
            "run the tests",
            "the history was not walked"
        );

        assert_eq!(handle_key(&mut session, ctrl('s')), Action::Redraw);
        let search = session.history_search().expect("the search did not open");
        assert_eq!(
            search.scope(),
            crate::history::Scope::Project,
            "the search opened over every workspace"
        );
        assert_eq!(
            search.needle(),
            "",
            "the search opened looking for the prompt in the box"
        );
        assert_eq!(
            session
                .history_matches()
                .iter()
                .map(|entry| entry.prompt.as_str())
                .collect::<Vec<_>>(),
            ["commit that", "run the tests"],
            "not this workspace's prompts"
        );
        assert_eq!(
            session.stashed(),
            Some("half a thought"),
            "the line put away earlier is gone"
        );
    }

    /// Somebody who typed half a prompt and then reached for the history has already said what
    /// they are looking for.
    #[test]
    fn the_search_starts_from_what_was_already_typed() {
        let mut session = having_sent(&["run the tests", "commit that"]);
        type_line(&mut session, "tests");
        handle_key(&mut session, ctrl('r'));

        assert_eq!(
            session.history_match().expect("a prompt").prompt,
            "run the tests"
        );
    }

    /// A prompt walked back to is not something anybody typed to look for it. Seeded with it, the
    /// search answers with the one prompt already in the box, which is the walk it exists to take
    /// somebody off: the hint offering the search is drawn in that very state.
    #[test]
    fn the_search_does_not_start_from_a_prompt_walked_back_to() {
        let mut session = having_sent(&["run the tests", "commit that"]);
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "commit that", "the history was not walked");

        handle_key(&mut session, ctrl('r'));
        assert_eq!(
            session.history_search().expect("a search").needle(),
            "",
            "the search opened looking for the prompt in the box"
        );
        assert_eq!(
            session.history_matches().len(),
            2,
            "prompts are missing from the list"
        );
    }

    /// While the search is open a letter narrows the list. Typed into the box instead it would go
    /// somewhere nobody can see, and the list would never narrow.
    #[test]
    fn a_letter_narrows_the_search_rather_than_reaching_the_box() {
        let mut session = having_sent(&["run the tests", "commit that"]);
        handle_key(&mut session, ctrl('r'));
        type_line(&mut session, "run");

        assert!(session.input().is_empty(), "the box took the letters");
        assert_eq!(
            session.history_match().expect("a prompt").prompt,
            "run the tests"
        );
    }

    /// Into the box rather than into a request: a history file can be edited, on a shared machine
    /// by somebody else, so the keystroke that sends a stored line has to be the person's own.
    #[test]
    fn enter_puts_the_chosen_prompt_in_the_box_without_sending_it() {
        let mut session = having_sent(&["run the tests", "commit that"]);
        handle_key(&mut session, ctrl('r'));
        type_line(&mut session, "run");
        let action = handle_key(&mut session, key(KeyCode::Enter));

        assert_eq!(action, Action::Redraw, "the prompt was sent");
        assert!(!session.searching_history());
        assert_eq!(session.input(), "run the tests");
        assert_eq!(
            session.status,
            Status::Idle,
            "a turn was started from the list"
        );
    }

    /// Escape means "stop what is happening", and what is happening is the search. The line in the
    /// box was never taken away, so there is nothing to put back.
    #[test]
    fn escape_closes_the_search_and_leaves_the_box_as_it_was() {
        let mut session = having_sent(&["run the tests"]);
        type_line(&mut session, "half a thought");
        handle_key(&mut session, ctrl('r'));
        handle_key(&mut session, key(KeyCode::Esc));

        assert!(!session.searching_history());
        assert_eq!(session.input(), "half a thought");
    }

    /// A paste and a drop reach this process as events of their own rather than as keys, so the
    /// guard that holds the box still for a letter does not see them. The panel is drawn in place
    /// of the box, so whatever lands in the box is invisible until the search closes, and the
    /// person comes back to a different prompt with a file staged that nobody asked for. An empty
    /// paste is how a picture on the clipboard arrives, and answering it reads the clipboard into
    /// that same box. The regressions it rejects are each of those, and spending the hint an empty
    /// paste says once a session, on the two paths a paste takes: at rest and mid-turn.
    #[test]
    fn a_paste_and_a_drop_do_not_reach_the_line_while_the_search_is_open() {
        let directory = crate::testutil::scratch_dir("bravebot-app-drop-while-searching");
        let _ = std::fs::remove_dir_all(&directory);
        std::fs::create_dir_all(&directory).expect("scratch");
        let file = directory.join("shot.png");
        std::fs::write(&file, [0x89u8, 0x50]).expect("write");
        let dropped = file.to_string_lossy().into_owned();

        for mid_turn in [false, true] {
            let place = if mid_turn { "mid-turn" } else { "at rest" };
            let press = |session: &mut Session, pressed: KeyEvent| match mid_turn {
                true => handle_key_while_working(session, pressed),
                false => handle_key(session, pressed),
            };
            let paste = |session: &mut Session, text: &str| match mid_turn {
                true => handle_paste_while_working(session, text),
                false => handle_paste(session, text),
            };

            let mut session = having_sent(&["half a thought sent before"]).in_workspace(&directory);
            if mid_turn {
                type_line(&mut session, "second question");
                handle_key(&mut session, key(KeyCode::Enter));
                assert!(session.a_turn_is_running(), "{place}: no turn was running");
            }
            for c in "half a thought".chars() {
                press(&mut session, key(KeyCode::Char(c)));
            }
            press(&mut session, key(KeyCode::Left));
            press(&mut session, ctrl('r'));
            assert!(
                session.searching_history(),
                "{place}: the search did not open"
            );

            let said = session.transcript.len();
            for pasted in ["pasted", "", dropped.as_str()] {
                assert_eq!(
                    paste(&mut session, pasted),
                    Action::None,
                    "{place}: a paste of {pasted:?} was answered from inside the search"
                );
            }
            assert_eq!(
                session.transcript.len(),
                said,
                "{place}: the empty paste spent the hint from inside the search"
            );
            assert_eq!(
                session.history_search().expect("a search").needle(),
                "half a thought",
                "{place}: a paste changed what was searched for"
            );
            press(&mut session, key(KeyCode::Esc));
            assert!(
                !session.searching_history(),
                "{place}: the search stayed open"
            );
            assert_eq!(
                session.input(),
                "half a thought",
                "{place}: a paste reached the box under the search"
            );
            assert!(
                session.attached().is_empty(),
                "{place}: a drop staged an attachment from inside the search"
            );

            // The caret is where it was left, which is the half of the line's state that is not
            // in the text.
            press(&mut session, key(KeyCode::Char('!')));
            assert_eq!(
                session.input(),
                "half a though!t",
                "{place}: the caret moved"
            );
        }

        let _ = std::fs::remove_dir_all(&directory);
    }

    /// Backspacing past the start leaves, which is what the key means once there is nothing left of
    /// the thing it deletes. The same ladder the scroller's search walks.
    #[test]
    fn backspacing_past_the_start_of_the_search_closes_it() {
        let mut session = having_sent(&["run the tests"]);
        handle_key(&mut session, ctrl('r'));
        type_line(&mut session, "ru");

        handle_key(&mut session, key(KeyCode::Backspace));
        assert!(session.searching_history());
        handle_key(&mut session, key(KeyCode::Backspace));
        assert!(session.searching_history());
        handle_key(&mut session, key(KeyCode::Backspace));
        assert!(!session.searching_history(), "the search would not close");
    }

    /// The arrows walk the matches while the search is open, rather than the history behind it or
    /// the transcript behind that.
    #[test]
    fn the_arrows_walk_the_matches_while_the_search_is_open() {
        let mut session = having_sent(&["first question", "second question"]);
        handle_key(&mut session, ctrl('r'));
        handle_key(&mut session, key(KeyCode::Up));

        assert_eq!(
            session.history_match().expect("a prompt").prompt,
            "first question"
        );
        assert_eq!(session.scroll, 0, "the transcript scrolled instead");
        assert!(!session.history.is_browsing(), "the box walked the history");
    }

    /// With nothing typed the prompt has nowhere to go, so the keys are the transcript's, which is
    /// what they were before there was a caret to move.
    #[test]
    fn page_keys_scroll_further() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.scroll, 10);
        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.scroll, 0);
    }

    /// The first press takes the start of the line and the second the line before it, so someone
    /// who wanted this line's start gets it without losing their place in the paragraph.
    #[test]
    fn page_up_takes_the_start_of_the_line_then_the_line_before() {
        let mut session = Session::new("none");
        handle_paste(&mut session, "first line\nsecond line\nthird line");

        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.caret(), "first line\nsecond line\n".len());
        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.caret(), "first line\n".len());
        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.caret(), 0);
    }

    /// And the same downwards, by line ends.
    #[test]
    fn page_down_takes_the_end_of_the_line_then_the_line_after() {
        let mut session = Session::new("none");
        handle_paste(&mut session, "first line\nsecond line\nthird line");
        // Up to the very start, which is where paging down has somewhere to go from.
        for _ in 0..3 {
            handle_key(&mut session, key(KeyCode::PageUp));
        }
        assert_eq!(session.caret(), 0);

        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.caret(), "first line".len());
        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.caret(), "first line\nsecond line".len());
    }

    /// Off the ends of the prompt the keys go back to the transcript, so a paragraph does not trap
    /// them and scrolling stays reachable.
    #[test]
    fn the_page_keys_reach_the_transcript_from_the_ends_of_the_prompt() {
        let mut session = Session::new("none");
        handle_paste(&mut session, "one\ntwo");

        // The caret starts at the end, so the start of "two" and then the start of "one".
        handle_key(&mut session, key(KeyCode::PageUp));
        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.caret(), 0);

        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.scroll, 10, "the transcript was unreachable");

        // And back down: the end of "one", then the end of "two".
        handle_key(&mut session, key(KeyCode::PageDown));
        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.caret(), session.input().len());

        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.scroll, 0);
    }

    /// A single-line prompt has ends too, so the keys reach them before the transcript.
    #[test]
    fn the_page_keys_work_on_one_line() {
        let mut session = typed_into("a sentence");
        handle_key(&mut session, key(KeyCode::PageUp));
        assert_eq!(session.caret(), 0);
        assert_eq!(session.scroll, 0, "the transcript scrolled instead");
        handle_key(&mut session, key(KeyCode::PageDown));
        assert_eq!(session.caret(), "a sentence".len());
    }

    /// Under Ctrl, because the bare keys belong to the line being typed.
    #[test]
    fn home_and_end_jump_to_the_extremes() {
        let mut session = Session::new("none");
        handle_key(&mut session, ctrl_key(KeyCode::Home));
        assert_eq!(session.scroll, u16::MAX);
        handle_key(&mut session, ctrl_key(KeyCode::End));
        assert_eq!(session.scroll, 0);
    }

    /// The keys that move around a line of text, which is what makes the box editable rather than
    /// only appendable.
    #[test]
    fn the_arrows_move_the_caret_through_the_line() {
        let mut session = typed_into("abc");
        assert_eq!(session.caret(), 3);

        assert_eq!(handle_key(&mut session, key(KeyCode::Left)), Action::Redraw);
        assert_eq!(session.caret(), 2);
        handle_key(&mut session, key(KeyCode::Right));
        assert_eq!(session.caret(), 3);

        // And they stop at the ends rather than wrapping or panicking.
        handle_key(&mut session, key(KeyCode::Right));
        assert_eq!(session.caret(), 3);
        for _ in 0..5 {
            handle_key(&mut session, key(KeyCode::Left));
        }
        assert_eq!(session.caret(), 0);
    }

    /// The bug this exists for: typing used to only ever append, so a correction meant deleting
    /// back to it and retyping the rest.
    #[test]
    fn typing_lands_where_the_caret_is() {
        let mut session = typed_into("ac");
        handle_key(&mut session, key(KeyCode::Left));
        handle_key(&mut session, key(KeyCode::Char('b')));
        assert_eq!(session.input(), "abc");
        assert_eq!(
            session.caret(),
            2,
            "the caret did not follow what was typed"
        );
    }

    /// Home and End reach the ends of the line, which is what they do in every other text field.
    #[test]
    fn home_and_end_reach_the_ends_of_the_line() {
        let mut session = typed_into("a sentence");
        handle_key(&mut session, key(KeyCode::Home));
        assert_eq!(session.caret(), 0);
        assert_eq!(session.scroll, 0, "the transcript scrolled instead");
        handle_key(&mut session, key(KeyCode::End));
        assert_eq!(session.caret(), "a sentence".len());
    }

    /// Backspace deletes before the caret rather than at the end of the line.
    #[test]
    fn backspace_deletes_at_the_caret() {
        let mut session = typed_into("abc");
        handle_key(&mut session, key(KeyCode::Left));
        handle_key(&mut session, key(KeyCode::Backspace));
        assert_eq!(session.input(), "ac");
        assert_eq!(session.caret(), 1);
    }

    /// Delete takes the character after the caret, which is the half Backspace cannot reach.
    #[test]
    fn delete_takes_the_character_after_the_caret() {
        let mut session = typed_into("abc");
        handle_key(&mut session, key(KeyCode::Home));
        handle_key(&mut session, key(KeyCode::Delete));
        assert_eq!(session.input(), "bc");
        assert_eq!(session.caret(), 0);
    }

    /// A word at a time, since a path or a flag is one thing to cross rather than a dozen.
    #[test]
    fn the_word_keys_cross_a_word_at_a_time() {
        let mut session = typed_into("read src/main.rs now");
        handle_key(&mut session, ctrl_key(KeyCode::Left));
        assert_eq!(session.caret(), "read src/main.rs ".len());
        handle_key(&mut session, ctrl_key(KeyCode::Left));
        assert_eq!(session.caret(), "read ".len());
        handle_key(&mut session, ctrl_key(KeyCode::Right));
        assert_eq!(session.caret(), "read src/main.rs".len());
    }

    /// A session with two prompts stored by earlier sessions and one of its own.
    fn with_earlier_sessions() -> Session {
        let mut session = Session::new("none");
        session.history = crate::history::History::from_entries(vec![
            bravebot_session::store::Entry::sent("old one", None),
            bravebot_session::store::Entry::sent("old two", None),
        ]);
        type_line(&mut session, "mine");
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);
        session
    }

    /// Up walks every stored prompt; the scope chord narrows to this session's from the prompt on
    /// screen, and pressed again goes back to every stored one.
    #[test]
    fn the_scope_chord_narrows_the_walk_to_this_sessions_prompts_and_widens_it_again() {
        let mut session = with_earlier_sessions();
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "mine");
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "old two");
        assert_eq!(session.history.scope(), crate::history::Scope::All);

        // Not this session's, so the nearest of this session's before it, and failing that the
        // oldest.
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        assert_eq!(session.input(), "mine");
        assert_eq!(session.history.position(), Some((1, 1)));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(
            session.input(),
            "mine",
            "Up walked past this session's prompts"
        );

        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(
            session.input(),
            "mine",
            "widening moved off the prompt on screen"
        );
        assert_eq!(session.history.position(), Some((3, 3)));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "old two");
    }

    /// Once a scope is chosen it holds: ending the walk, or sending, does not put it back.
    #[test]
    fn the_scope_chosen_holds_after_the_walk_ends_and_after_sending() {
        let mut session = with_earlier_sessions();
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        handle_key(&mut session, key(KeyCode::Down));
        assert!(!session.history.is_browsing());
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "mine", "Up left this session's prompts");

        handle_key(&mut session, key(KeyCode::Down));
        type_line(&mut session, "mine again");
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "mine");
    }

    /// The terminal sees Ctrl-Right as a window-manager key on some systems (macOS gives it to
    /// Mission Control), so the switch is a chord of its own and the arrows are only the word
    /// motion, on a recalled prompt as everywhere else.
    #[test]
    fn ctrl_and_alt_arrows_on_a_recalled_prompt_move_the_caret_and_leave_the_scope() {
        for modifiers in [KeyModifiers::CONTROL, KeyModifiers::ALT] {
            let mut session = with_earlier_sessions();
            handle_key(&mut session, key(KeyCode::Up));
            assert_eq!(session.input(), "mine");
            let end = session.caret();
            handle_key(&mut session, KeyEvent::new(KeyCode::Left, modifiers));
            assert!(
                session.caret() < end,
                "{modifiers:?}-Left did not move the caret"
            );
            handle_key(&mut session, KeyEvent::new(KeyCode::Right, modifiers));
            assert_eq!(
                session.caret(),
                end,
                "{modifiers:?}-Right did not move it back"
            );
            assert_eq!(session.history.scope(), crate::history::Scope::All);
            assert_eq!(session.input(), "mine");
        }
    }

    /// A settings file can move the switch. The chord it left goes dead, and the one it moved to
    /// works in the same two places the default does.
    #[test]
    fn a_moved_scope_chord_switches_and_the_old_one_does_not() {
        let mut moved = std::collections::BTreeMap::new();
        moved.insert("scope".to_string(), "alt-n".to_string());

        let mut session = with_earlier_sessions();
        session.adopt_keybindings(&moved);
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, ctrl('n'));
        assert_eq!(
            session.history.scope(),
            crate::history::Scope::All,
            "the chord the switch was moved off still switched"
        );
        handle_key(&mut session, alt('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        handle_key(&mut session, alt('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
    }

    /// With nothing on screen from the history there is nothing to switch, so the chord does not
    /// type, move or narrow anything in a line being written.
    #[test]
    fn the_scope_chord_does_nothing_in_a_line_being_typed() {
        let mut session = with_earlier_sessions();
        type_line(&mut session, "read src now");
        let caret = session.caret();
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.input(), "read src now");
        assert_eq!(session.caret(), caret);
        assert_eq!(session.history.scope(), crate::history::Scope::All);
    }

    /// A moved chord is dead in a typed line like the default is, and where it lands on a readline
    /// key the key still edits there, since the switch only takes it on a recalled prompt.
    #[test]
    fn a_moved_scope_chord_is_not_typed_and_keeps_the_edit_it_landed_on() {
        let mut moved = std::collections::BTreeMap::new();
        moved.insert("scope".to_string(), "alt-n".to_string());
        let mut session = with_earlier_sessions();
        session.adopt_keybindings(&moved);
        type_line(&mut session, "read src now");
        handle_key(&mut session, alt('n'));
        assert_eq!(session.input(), "read src now", "the chord was typed");

        let mut onto_edit = std::collections::BTreeMap::new();
        onto_edit.insert("scope".to_string(), "ctrl-a".to_string());
        let mut session = with_earlier_sessions();
        session.adopt_keybindings(&onto_edit);
        type_line(&mut session, "read src now");
        handle_key(&mut session, ctrl('a'));
        assert_eq!(
            session.caret(),
            0,
            "the edit key it was moved onto went dead"
        );
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, ctrl('a'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
    }

    /// A prompt that is in both lists stays on screen across the switch, at its place in each.
    #[test]
    fn switching_scope_keeps_a_prompt_that_is_in_both() {
        let mut session = with_earlier_sessions();
        type_line(&mut session, "mine too");
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "mine");
        assert_eq!(session.history.position(), Some((3, 4)));
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.input(), "mine");
        assert_eq!(session.history.position(), Some((1, 2)));
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.input(), "mine");
        assert_eq!(session.history.position(), Some((3, 4)));
    }

    /// Alt is the word motion on a recalled prompt, and Ctrl is in a line that is being typed.
    #[test]
    fn the_word_keys_still_move_the_caret_outside_a_recalled_prompt() {
        let mut session = with_earlier_sessions();
        type_line(&mut session, "read src now");
        handle_key(&mut session, ctrl_key(KeyCode::Left));
        assert_eq!(session.caret(), "read src ".len());
        assert_eq!(session.history.scope(), crate::history::Scope::All);

        let mut session = with_earlier_sessions();
        handle_key(&mut session, key(KeyCode::Up));
        let on_screen = session.input().to_string();
        let before = session.caret();
        handle_key(
            &mut session,
            KeyEvent::new(KeyCode::Left, KeyModifiers::ALT),
        );
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(session.input(), on_screen);
        assert!(session.caret() < before, "Alt-Left did not move the caret");
    }

    /// A turn can begin while a stored prompt is on screen, and the chord means the same there as
    /// at rest: it narrows and stays on the prompt, and pressed again comes back.
    #[test]
    fn the_scope_chord_works_while_a_turn_runs() {
        let mut session = with_earlier_sessions();
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "mine");
        session.status = Status::Working;

        handle_key_while_working(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        assert_eq!(session.input(), "mine");
        assert_eq!(session.history.position(), Some((1, 1)));

        handle_key_while_working(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(session.history.position(), Some((3, 3)));
    }

    /// A prompt queued behind a running turn is one the person has sent, so it is in this
    /// session's scope from the moment it is queued.
    #[test]
    fn a_prompt_queued_during_a_turn_is_one_this_session_sent() {
        let mut session = Session::new("none");
        session.history =
            crate::history::History::from_entries(vec![bravebot_session::store::Entry::sent(
                "old one", None,
            )]);
        session.status = Status::Working;
        type_line(&mut session, "queued one");
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        assert_eq!(session.queued.len(), 1);

        session.queued.clear();
        session.status = Status::Idle;
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "queued one");
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        assert_eq!(session.history.position(), Some((1, 1)));
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(
            session.input(),
            "queued one",
            "Up walked past this session's prompt"
        );
    }

    /// `/clear` starts a new conversation, whose own prompts are none yet, so the walk is over
    /// every stored prompt and the chord has no session's prompts to narrow to.
    #[test]
    fn clearing_the_session_empties_the_scope_the_chord_narrows_to() {
        let mut session = with_earlier_sessions();
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::Session);
        handle_key(&mut session, key(KeyCode::Down));
        session.clear();
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(session.input(), "mine");
        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(session.input(), "mine");
    }

    /// A new session has sent nothing, so Up walks the stored prompts and the chord is not on
    /// offer: it stays in the wide scope.
    #[test]
    fn up_in_a_new_session_walks_the_stored_prompts_and_offers_no_switch() {
        let mut session = Session::new("none");
        session.history =
            crate::history::History::from_entries(vec![bravebot_session::store::Entry::sent(
                "old one", None,
            )]);
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.input(), "old one");
        assert_eq!(session.history.position(), Some((1, 1)));

        handle_key(&mut session, ctrl('n'));
        assert_eq!(session.history.scope(), crate::history::Scope::All);
        assert_eq!(session.input(), "old one");
    }

    /// The readline bindings, because a terminal may send nothing at all for the named keys and
    /// then the middle of a line would be unreachable.
    #[test]
    fn the_readline_bindings_move_and_delete_too() {
        let mut session = typed_into("some words here");
        handle_key(&mut session, ctrl('a'));
        assert_eq!(session.caret(), 0);
        handle_key(&mut session, ctrl('e'));
        assert_eq!(session.caret(), "some words here".len());

        handle_key(&mut session, ctrl('w'));
        assert_eq!(session.input(), "some words ");
        handle_key(&mut session, ctrl('u'));
        assert_eq!(session.input(), "");
    }

    /// Ctrl-K takes the rest of the line, which is the other half of Ctrl-U.
    #[test]
    fn ctrl_k_takes_the_rest_of_the_line() {
        let mut session = typed_into("keep this drop that");
        for _ in 0..2 {
            handle_key(&mut session, ctrl_key(KeyCode::Left));
        }
        handle_key(&mut session, ctrl('k'));
        assert_eq!(session.input(), "keep this ");
    }

    fn alt(c: char) -> KeyEvent {
        KeyEvent::new(KeyCode::Char(c), KeyModifiers::ALT)
    }

    /// Ctrl-K then Ctrl-Y at another place moves the text.
    #[test]
    fn ctrl_y_puts_back_what_ctrl_k_took_somewhere_else() {
        let mut session = typed_into("keep this drop that");
        for _ in 0..2 {
            handle_key(&mut session, ctrl_key(KeyCode::Left));
        }
        handle_key(&mut session, ctrl('k'));
        assert_eq!(session.input(), "keep this ");
        handle_key(&mut session, ctrl('a'));
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "drop thatkeep this ");
        assert_eq!(session.caret(), "drop that".len());
    }

    /// Ctrl-U and Ctrl-W keep what they took as well, and Alt-D takes the word after the caret.
    #[test]
    fn every_delete_key_keeps_what_it_took() {
        for (take, line, left, kept) in [
            (ctrl('u'), "one two", 0, "one two"),
            (ctrl('w'), "one two", 0, "two"),
            (alt('d'), "one two", 7, "one"),
        ] {
            let mut session = typed_into(line);
            for _ in 0..left {
                handle_key(&mut session, ctrl_key(KeyCode::Left));
            }
            if left > 0 {
                handle_key(&mut session, ctrl('a'));
            }
            handle_key(&mut session, take);
            handle_key(&mut session, ctrl('y'));
            assert!(
                session.input().contains(kept),
                "{take:?} kept nothing: {:?}",
                session.input()
            );
        }
    }

    /// The undo chord puts back what a delete took, pressed through the key handler rather than
    /// called on the session directly, so the wiring from the chord to the step is covered too.
    #[test]
    fn the_undo_chord_puts_back_what_a_delete_took() {
        let mut session = typed_into("one two three");
        handle_key(&mut session, ctrl('w'));
        assert_eq!(session.input(), "one two ");
        handle_key(&mut session, ctrl('_'));
        assert_eq!(session.input(), "one two three");
    }

    /// A run of typing is one step back, not one for every character, the same way vi folds a
    /// whole INSERT session into the one `u` after it reaches.
    #[test]
    fn the_undo_chord_takes_back_a_whole_typing_run() {
        let mut session = typed_into("hello");
        assert_eq!(session.input(), "hello");
        handle_key(&mut session, ctrl('_'));
        assert_eq!(session.input(), "");
    }

    /// A second run after an undo opens a step of its own, pressed through the key handler. The
    /// flag that marks a run open must be closed by the undo that just put the first run's step
    /// back, or the second run's keys would find it still open, share no step at all, and the
    /// second press of the chord would have nothing to undo.
    #[test]
    fn the_undo_chord_leaves_the_next_run_able_to_open_its_own_step() {
        let mut session = typed_into("hello");
        handle_key(&mut session, ctrl('_'));
        assert_eq!(session.input(), "");

        for c in "abc".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(session.input(), "abc");
        handle_key(&mut session, ctrl('_'));
        assert_eq!(
            session.input(),
            "",
            "the second run opened no step of its own"
        );
    }

    /// The chord reaches vi's own undo stack as well as the ordinary box's, so a change already on
    /// it comes back without first pressing Escape to reach `u` from NORMAL mode, and the session
    /// stays in INSERT mode exactly where it found it. What the open INSERT session has typed since
    /// is not itself on the stack until Escape closes it (INPUT-28), so this reaches past the
    /// session rather than into it.
    #[test]
    fn the_undo_chord_works_in_vi_insert_mode_without_leaving_it() {
        let mut session = editing_vis_way();
        for c in "one".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Esc));
        assert_eq!(session.vi_mode(), Some(crate::vim::Mode::Normal));

        // `x` deletes the character under the caret, which Escape left on the last one typed, as
        // its own completed change, pushed to the stack at the press rather than deferred to an
        // Escape that never comes for it.
        handle_key(&mut session, key(KeyCode::Char('x')));
        assert_eq!(session.input(), "on");

        handle_key(&mut session, key(KeyCode::Char('i')));
        assert_eq!(session.vi_mode(), Some(crate::vim::Mode::Insert));

        handle_key(&mut session, ctrl('_'));
        assert_eq!(session.input(), "one");
        assert_eq!(
            session.vi_mode(),
            Some(crate::vim::Mode::Insert),
            "the chord left insert mode"
        );
    }

    /// Editing a line is one of the things a running turn still allows, undoing an edit among
    /// them, so the chord reaches the same step through the mid-turn handler as it does at rest.
    #[test]
    fn the_undo_chord_works_while_a_turn_is_running() {
        let mut session = Session::new("kernel-enforced");
        for c in "one two".chars() {
            session.type_char(c);
        }
        session.status = Status::Working;

        assert_eq!(
            handle_key_while_working(&mut session, ctrl('w')),
            Action::Redraw
        );
        assert_eq!(session.input(), "one ");

        assert_eq!(
            handle_key_while_working(&mut session, ctrl('_')),
            Action::Redraw
        );
        assert_eq!(session.input(), "one two");
    }

    /// The turn's own key reader hands the stop back to the pump that holds the terminal, with the
    /// turn still running and the box as it was, for a key that is not one of the two that stop it
    /// (INPUT-47). The other working loops are read through [`act_while_working`], which the
    /// tests of the suspension cover.
    #[cfg(unix)]
    #[test]
    fn the_turns_key_reader_hands_ctrl_z_back_and_leaves_the_turn_running() {
        let mut session = Session::new("kernel-enforced");
        for c in "one two".chars() {
            session.type_char(c);
        }
        session.status = Status::Working;
        let cancel = Cancel::new();

        assert!(!stops_the_turn(&session, ctrl('z')));
        let answer = nothing_beside(|beside| turn_key(&mut session, ctrl('z'), &cancel, beside));

        assert_eq!(answer, Action::Suspend);
        assert_eq!(session.status, Status::Working);
        assert!(!cancel.is_cancelled(), "the key stopped the turn");
        assert_eq!(session.input(), "one two");
    }

    /// Kills in one direction join, and a change of direction starts a new buffer.
    #[test]
    fn consecutive_kills_join_in_the_direction_they_went() {
        let mut session = typed_into("one two three");
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, ctrl('w'));
        assert_eq!(session.input(), "one ");
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "one two three");

        let mut session = typed_into("one two three");
        handle_key(&mut session, ctrl('a'));
        handle_key(&mut session, alt('d'));
        handle_key(&mut session, alt('d'));
        assert_eq!(session.input(), " three");
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "one two three");

        // A kill the other way starts a new buffer.
        let mut session = typed_into("ab cd ef");
        handle_key(&mut session, ctrl('a'));
        handle_key(&mut session, ctrl_key(KeyCode::Right));
        handle_key(&mut session, KeyEvent::from(KeyCode::Right));
        handle_key(&mut session, alt('d'));
        assert_eq!(session.input(), "ab  ef");
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "ab  ef");

        // A kill after typing replaces the buffer, and the ones after it join.
        let mut session = typed_into("one two three");
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, KeyEvent::from(KeyCode::Char('x')));
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "one two x");
    }

    /// Ctrl-Y with nothing killed does nothing, and the line is not a change to undo.
    #[test]
    fn ctrl_y_with_nothing_killed_does_nothing() {
        let mut session = typed_into("abc");
        assert_eq!(handle_key(&mut session, ctrl('y')), Action::Redraw);
        assert_eq!(session.input(), "abc");
        assert_eq!(session.caret(), 3);
    }

    /// Alt-D at the end of the line deletes nothing and keeps nothing.
    #[test]
    fn alt_d_at_the_end_of_the_line_keeps_nothing() {
        let mut session = typed_into("abc");
        handle_key(&mut session, ctrl('w'));
        handle_key(&mut session, ctrl('y'));
        handle_key(&mut session, alt('d'));
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "abcabc");
    }

    /// A chord moved onto ctrl-y still wins over the yank.
    #[test]
    fn a_chord_on_ctrl_y_takes_precedence_over_the_yank() {
        let mut session = Session::new("none");
        let mut custom = std::collections::BTreeMap::new();
        custom.insert("stash".to_string(), "ctrl-y".to_string());
        session.adopt_keybindings(&custom);
        type_line(&mut session, "line to stash");
        handle_key(&mut session, ctrl('y'));
        assert_eq!(session.input(), "");
        assert_eq!(session.stashed(), Some("line to stash"));
    }

    /// The keys that used to be typed as characters, and now must not be: Ctrl-A on an empty line
    /// once inserted a literal 'a'.
    #[test]
    fn the_editing_keys_are_not_typed_as_characters() {
        let mut session = Session::new("none");
        for binding in ['a', 'e', 'b', 'f', 'w', 'u', 'k'] {
            handle_key(&mut session, ctrl(binding));
        }
        assert!(
            session.input().is_empty(),
            "a binding was typed: {}",
            session.input()
        );
    }

    /// A pasted paragraph has rows, and Up and Down move between them before they reach for the
    /// history: a line the user can see is the one they meant to edit.
    #[test]
    fn up_and_down_move_within_a_pasted_paragraph() {
        let mut session = Session::new("none");
        handle_paste(&mut session, "first line\nsecond row");
        assert_eq!(handle_key(&mut session, key(KeyCode::Up)), Action::Redraw);
        assert_eq!(session.caret(), "first line".len());
        handle_key(&mut session, key(KeyCode::Down));
        assert_eq!(session.caret(), "first line\nsecond row".len());
    }

    /// The caret keeps its place along the line, and clamps to the end of a shorter one rather
    /// than off it.
    #[test]
    fn moving_between_lines_keeps_the_place_along_them() {
        let mut session = Session::new("none");
        handle_paste(&mut session, "a longer first line\nshort\nlast");
        handle_key(&mut session, key(KeyCode::Home));
        for _ in 0..3 {
            handle_key(&mut session, key(KeyCode::Right));
        }
        handle_key(&mut session, key(KeyCode::Up));
        assert_eq!(session.caret(), "a longer first line\nsho".len());

        // "last" is shorter than where the caret is, so it clamps to the end of it.
        handle_key(&mut session, key(KeyCode::End));
        handle_key(&mut session, key(KeyCode::Down));
        handle_key(&mut session, key(KeyCode::Down));
        assert_eq!(session.caret(), session.input().len());
    }

    /// Off the top of the line, Up is the history's again, so a one-line prompt is unaffected and
    /// a paragraph does not trap the keys.
    #[test]
    fn up_reaches_history_from_the_top_of_the_line() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Enter));
        session.complete("ok", Vec::new(), 0);

        handle_paste(&mut session, "one\ntwo");
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Up));
        assert!(session.history.is_browsing(), "history was unreachable");
    }

    /// The line can be typed mid-turn, so it has to be editable mid-turn: a box that takes words
    /// and will not let them be fixed is worse than one that takes none.
    #[test]
    fn the_caret_moves_while_a_turn_runs() {
        let mut session = typed_into("ac");
        handle_key(&mut session, key(KeyCode::Enter));
        for c in "ac".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }

        handle_key_while_working(&mut session, key(KeyCode::Left));
        handle_key_while_working(&mut session, key(KeyCode::Char('b')));
        assert_eq!(session.input(), "abc");
    }

    /// The wheel is what most people reach for, so it scrolls with no modifier.
    #[test]
    fn the_mouse_wheel_scrolls() {
        let mut session = Session::new("none");
        let wheel = |kind| MouseEvent {
            kind,
            column: 0,
            row: 0,
            modifiers: KeyModifiers::NONE,
        };

        assert_eq!(
            handle_mouse(&mut session, wheel(MouseEventKind::ScrollUp)),
            Action::Redraw
        );
        assert_eq!(session.scroll, 3);
        handle_mouse(&mut session, wheel(MouseEventKind::ScrollDown));
        assert_eq!(session.scroll, 0);
    }

    /// Clicks and drags are not bound to anything, so they must be ignored rather than
    /// misinterpreted as scrolling.
    #[test]
    fn other_mouse_events_are_ignored() {
        let mut session = Session::new("none");
        let moved = MouseEvent {
            kind: MouseEventKind::Moved,
            column: 5,
            row: 5,
            modifiers: KeyModifiers::NONE,
        };
        assert_eq!(handle_mouse(&mut session, moved), Action::None);
        assert_eq!(session.scroll, 0);
    }

    /// Typing must not be captured by the scroll bindings.
    #[test]
    fn scroll_keys_do_not_disturb_the_input() {
        let mut session = Session::new("none");
        for c in "hello".chars() {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        handle_key(&mut session, key(KeyCode::Up));
        handle_key(&mut session, key(KeyCode::Down));
        assert_eq!(session.input(), "hello", "scrolling altered the input");
    }

    #[test]
    fn backspace_deletes() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Backspace));
        assert!(session.input().is_empty());
    }

    /// The ladder the key walks, from the box. Three rungs where the flag was not given, and back to
    /// asking: a key that stopped cycling would leave somebody in a mode they could not press their
    /// way out of.
    #[test]
    fn shift_tab_cycles_the_permission_mode() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        assert_eq!(session.permission_mode(), PermissionMode::Ask);

        for expected in [
            PermissionMode::AcceptEdits,
            PermissionMode::Plan,
            PermissionMode::Bypass,
            PermissionMode::Ask,
        ] {
            handle_key(&mut session, shift(KeyCode::Tab));
            assert_eq!(session.permission_mode(), expected);
        }
    }

    /// Which spelling arrives is the terminal's choice: one that has been asked to disambiguate sends
    /// Tab with a modifier, one that has not sends `BackTab`. A binding that worked on one machine
    /// and not the next would read as broken.
    #[test]
    fn either_spelling_of_shift_tab_cycles_the_mode() {
        use bravebot_agent::PermissionMode;
        for press in [shift(KeyCode::Tab), key(KeyCode::BackTab)] {
            let mut session = Session::new("none");
            handle_key(&mut session, press);
            assert_eq!(
                session.permission_mode(),
                PermissionMode::AcceptEdits,
                "{press:?} did not cycle the mode"
            );
        }
    }

    /// The mode key must not type anything, and must not be taken for the completion Tab: a press
    /// that changed the mode *and* accepted a half-typed command would do two things at once.
    #[test]
    fn the_mode_key_leaves_the_line_alone() {
        let mut session = typed_into("/mod");
        handle_key(&mut session, shift(KeyCode::Tab));
        assert_eq!(
            session.input(),
            "/mod",
            "the mode key completed the line or typed into it"
        );
    }

    /// Bypass is on the ladder of a session that did not start in it, and reaching it that way does
    /// not make the line under the box name asking once the key leaves it: that is said only of a
    /// session the flag opened in bypass.
    #[test]
    fn the_key_reaches_bypass_without_the_flag() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        assert!(!session.began_in_bypass());
        let mut reached = false;
        for _ in 0..4 {
            handle_key(&mut session, shift(KeyCode::Tab));
            reached |= session.permission_mode() == PermissionMode::Bypass;
        }
        assert!(reached, "four presses never reached bypass");
        assert_eq!(session.permission_mode(), PermissionMode::Ask);
        assert!(!session.began_in_bypass());
    }

    /// PERM-17: where a layer wrote `permissions.bypassUnreachable` the rung is off the ladder, and
    /// the key cannot reach it however many times it is pressed.
    #[test]
    fn the_key_cannot_reach_bypass_where_a_layer_made_it_unreachable() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        session.make_bypass_unreachable();
        for _ in 0..12 {
            handle_key(&mut session, shift(KeyCode::Tab));
            assert_ne!(session.permission_mode(), PermissionMode::Bypass);
        }
    }

    /// A session already in bypass when a layer takes it away goes back to asking, is told so, and
    /// does not get the rung back.
    #[test]
    fn a_session_in_bypass_is_put_back_to_asking_when_a_layer_takes_bypass_away() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none").starting_in_bypass();
        let notes = session.transcript.len();
        session.make_bypass_unreachable();
        assert_eq!(session.permission_mode(), PermissionMode::Ask);
        assert!(session.transcript.len() > notes, "the person was not told");
        for _ in 0..12 {
            handle_key(&mut session, shift(KeyCode::Tab));
            assert_ne!(session.permission_mode(), PermissionMode::Bypass);
        }
    }

    /// `/cd` reads the destination's layers, and a checkout that forbids bypassing holds in a session
    /// that was in bypass when it moved there, whatever the person answers about its rules.
    #[test]
    fn reading_the_rules_of_a_checkout_that_forbids_bypassing_takes_bypass_away() {
        use bravebot_agent::PermissionMode;
        let root = crate::testutil::scratch_dir("bravebot-bypass-unreachable-test");
        let _ = std::fs::remove_dir_all(&root);
        let a = root.join("a");
        let b = root.join("b");
        checkout_with_settings(&a, r#"{"permissions": {}}"#);
        checkout_with_settings(&b, r#"{"permissions": {"bypassUnreachable": true}}"#);

        let workspace = Workspace::new(&a).expect("workspace");
        let mut session = Session::new("none");
        let mut rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        session.cycle_permission_mode();
        session.cycle_permission_mode();
        session.cycle_permission_mode();
        assert_eq!(session.permission_mode(), PermissionMode::Bypass);

        rules.read_for(
            &mut session,
            &b,
            Whence::Asked,
            "the-next-session",
            never_asked,
        );

        assert_eq!(session.permission_mode(), PermissionMode::Ask);
        session.cycle_permission_mode();
        session.cycle_permission_mode();
        session.cycle_permission_mode();
        assert_eq!(session.permission_mode(), PermissionMode::Ask);

        std::fs::remove_dir_all(&root).ok();
    }

    /// The flag opens the session in bypass, and the key walks out of it and back round.
    #[test]
    fn the_flag_opens_the_session_in_bypass_and_can_be_cycled_out_of() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none").starting_in_bypass();
        assert_eq!(session.permission_mode(), PermissionMode::Bypass);

        // Out of it, round the ladder, and back: the key means the same thing wherever it started.
        for expected in [
            PermissionMode::Ask,
            PermissionMode::AcceptEdits,
            PermissionMode::Plan,
            PermissionMode::Bypass,
        ] {
            handle_key(&mut session, shift(KeyCode::Tab));
            assert_eq!(session.permission_mode(), expected);
        }
    }

    /// Most wanted mid-turn, which is when somebody watching a turn edit the wrong files decides it
    /// should stop and ask. The handle the running turn holds is the session's own, so the turn
    /// reads the mode the key left (MODE-8).
    #[test]
    fn the_mode_can_be_changed_while_a_turn_runs() {
        use bravebot_agent::PermissionMode;
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Enter));
        assert_eq!(session.status, Status::Working);
        let held_by_the_turn = session.live_permission_mode();

        handle_key(&mut session, shift(KeyCode::Tab));
        assert_eq!(session.permission_mode(), PermissionMode::AcceptEdits);
        assert_eq!(held_by_the_turn.get(), PermissionMode::AcceptEdits);
    }

    /// Keys that mean nothing here must be ignored rather than mishandled.
    #[test]
    fn unknown_keys_are_ignored() {
        let mut session = Session::new("none");
        assert_eq!(handle_key(&mut session, key(KeyCode::F(5))), Action::None);
        assert_eq!(handle_key(&mut session, key(KeyCode::Insert)), Action::None);
    }

    /// A second submission cannot start while a turn is in flight.
    #[test]
    fn enter_is_inert_while_working() {
        let mut session = Session::new("none");
        handle_key(&mut session, key(KeyCode::Char('a')));
        handle_key(&mut session, key(KeyCode::Enter));
        assert_eq!(session.status, Status::Working);

        handle_key(&mut session, key(KeyCode::Char('b')));
        assert_eq!(handle_key(&mut session, key(KeyCode::Enter)), Action::None);
    }

    /// A directory the person accepted is opened and vouched for by the same route `/add-dir`
    /// takes, so neither has a way in that the other lacks. A relative name means a path under the
    /// workspace, which is what `../shared` in a file about a project says.
    #[test]
    fn an_accepted_directory_is_opened_and_trusted_like_one_typed() {
        let root = crate::testutil::scratch_dir("bravebot-settings-dir-test");
        let outside = root.join("shared");
        let project = root.join("project");
        std::fs::create_dir_all(&outside).expect("scratch");
        std::fs::create_dir_all(&project).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let mut trust = TrustStore::new("/work");

        // Named the way a settings file names it, relative to the project.
        let asked = named_to_open(&mut session, &workspace, &["../shared".to_string()]);
        open_named(&mut session, &mut workspace, &mut trust, &asked);

        // Both halves, since either alone is useless: reach without trust asks about every write
        // there, and trust without reach is a rule about files nothing can open.
        let canonical = outside.canonicalize().expect("canonical");
        assert!(
            workspace.added_directories().contains(&canonical),
            "a directory the person accepted was not opened"
        );
        assert!(
            trust.is_trusted(&canonical.display().to_string()),
            "a directory the person accepted was not vouched for"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// The other half of the answer, asserted where a refusal bites rather than in the list that
    /// was asked about: a name nobody accepted leaves its path unreachable and out of the map, so
    /// reading or writing there is refused as it is anywhere else outside the workspace.
    #[test]
    fn a_declined_directory_is_left_unreachable_and_unvouched_for() {
        let root = crate::testutil::scratch_dir("bravebot-declined-dir-test");
        let accepted = root.join("accepted");
        let declined = root.join("declined");
        let project = root.join("project");
        for directory in [&accepted, &declined, &project] {
            std::fs::create_dir_all(directory).expect("scratch");
        }

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let mut trust = TrustStore::new("/work");

        let asked = named_to_open(
            &mut session,
            &workspace,
            &["../accepted".to_string(), "../declined".to_string()],
        );
        assert_eq!(asked.len(), 2, "both names were asked about");
        // One question answered yes, the other no.
        open_named(&mut session, &mut workspace, &mut trust, &asked[..1]);

        let yes = accepted.canonicalize().expect("canonical");
        let no = declined.canonicalize().expect("canonical");
        assert!(workspace.confines(&yes.join("notes.md")).is_ok());
        assert!(
            workspace.confines(&no.join("notes.md")).is_err(),
            "a declined directory is still reachable"
        );
        assert!(
            !trust.is_trusted(&no.display().to_string()),
            "a declined directory is still vouched for"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// What the question shows has to be what accepting it would reach. A name is canonicalized
    /// when it is opened, so a settings file naming a link inside the project would otherwise put
    /// a path beginning with the person's own project root in front of them and grant the tree at
    /// the other end of it.
    #[test]
    #[cfg(unix)]
    fn a_named_directory_is_resolved_before_it_is_asked_about() {
        let root = crate::testutil::scratch_dir("bravebot-named-link-test");
        let outside = root.join("outside");
        let project = root.join("project");
        std::fs::create_dir_all(&outside).expect("scratch");
        std::fs::create_dir_all(&project).expect("scratch");
        std::os::unix::fs::symlink(&outside, project.join("link")).expect("symlink");

        let workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");

        let asked = named_to_open(&mut session, &workspace, &["link".to_string()]);

        assert_eq!(
            asked,
            vec![
                outside
                    .canonicalize()
                    .expect("canonical")
                    .display()
                    .to_string()
            ],
            "the question would have shown the name rather than the directory"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// Two layers of settings both naming a directory is one request. A second box for a path
    /// already answered is a question whose answer is already known, and answering the same
    /// question twice differently is a contradiction nothing could resolve.
    #[test]
    fn a_directory_two_layers_both_named_is_asked_about_once() {
        let root = crate::testutil::scratch_dir("bravebot-named-twice-test");
        let outside = root.join("shared");
        let project = root.join("project");
        std::fs::create_dir_all(&outside).expect("scratch");
        std::fs::create_dir_all(&project).expect("scratch");

        let workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");

        let both = vec!["../shared".to_string(), outside.display().to_string()];
        let asked = named_to_open(&mut session, &workspace, &both);

        assert_eq!(asked.len(), 1, "the same directory was asked about twice");

        std::fs::remove_dir_all(&root).ok();
    }

    /// A name that could not be opened whatever the answer is reported rather than put as a
    /// question: a directory already inside the project is reachable by its relative path, so a
    /// box asking about it collects an answer that changes nothing either way.
    #[test]
    fn a_name_that_cannot_be_opened_is_said_so_rather_than_asked_about() {
        let root = crate::testutil::scratch_dir("bravebot-named-inside-test");
        let project = root.join("project");
        std::fs::create_dir_all(project.join("docs")).expect("scratch");

        let workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");

        let asked = named_to_open(&mut session, &workspace, &["docs".to_string()]);

        assert!(
            asked.is_empty(),
            "a name that cannot be opened was asked about"
        );
        assert!(
            session.transcript[0].text.contains("could not add"),
            "nothing said why the directory was not opened: {}",
            session.transcript[0].text
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// PERM-16: where a layer asked for the file tools to stay inside the workspace, a name in
    /// `additionalDirectories` is refused rather than put to anybody, and the refusal names the key.
    /// That is PERM-13's existing treatment of a name that cannot be opened whatever the answer, and
    /// the whole point of the key is that no answer opens one.
    ///
    /// The failure this rejects is a question asked anyway and refused after it is answered, which is
    /// the box that trains answering without reading: the person is shown a decision they do not
    /// have.
    #[test]
    fn a_named_directory_is_refused_rather_than_asked_about_where_reads_stay_in_the_workspace() {
        let root = crate::testutil::scratch_dir("bravebot-named-confined-test");
        let project = root.join("project");
        let outside = root.join("shared");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&outside).expect("scratch");

        let workspace = Workspace::new(&project)
            .expect("workspace")
            .with_reads_kept_inside(true);
        let mut session = Session::new("none");

        let asked = named_to_open(&mut session, &workspace, &[outside.display().to_string()]);

        assert!(
            asked.is_empty(),
            "a directory the settings keep shut was put to the person"
        );
        assert!(
            session.transcript[0]
                .text
                .contains("permissions.readsStayInWorkspace"),
            "the refusal did not name the key that made it: {}",
            session.transcript[0].text
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// CHECKOUT-7. `/add-dir` on a directory that holds the working directory says, when it is
    /// opened and not when a spawn is refused, that no delegate is given a checkout while it is
    /// open. A directory that holds nothing of the kind says nothing of the sort.
    #[test]
    fn add_dir_of_a_directory_holding_the_project_says_it_ends_checkouts() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-ends-checkouts-test");
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");

        add_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &notes.display().to_string(),
        );
        let said: Vec<&str> = session.transcript.iter().map(|n| n.text.as_str()).collect();
        assert!(
            said.iter().all(|text| !text.contains("no delegate")),
            "{said:?}"
        );

        add_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &root.display().to_string(),
        );
        let said = &session.transcript.last().expect("a note").text;
        assert!(
            said.contains("no delegate is given a checkout while it is open"),
            "{said}"
        );
        assert!(said.contains("/add-dir close"), "{said}");
    }

    /// TRUST-9: `/add-dir close` takes back both halves `/add-dir` gave, the reach and the rule, for
    /// the directory named and no other. A second close of it, and a close with no path, are
    /// refused and say why, so nobody is told a directory closed when nothing did.
    ///
    /// The failures this rejects are a close that leaves the rule, which would go on vouching for
    /// files there that reach a turn some other way and be carried into a resume, a close of
    /// the workspace's list alone that leaves the directory trusted, and a note saying trust was
    /// withdrawn where the rule at the directory was a distrust that stays.
    #[test]
    fn add_dir_close_withdraws_the_reach_and_the_rule_together() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-close-test");
        let project = root.join("project");
        let notes = root.join("notes");
        let shared = root.join("shared");
        for directory in [&project, &notes, &shared] {
            std::fs::create_dir_all(directory).expect("scratch");
        }

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");
        for directory in [&notes, &shared] {
            add_directory(
                &mut session,
                &mut workspace,
                &mut trust,
                &directory.display().to_string(),
            );
        }
        let notes = notes.canonicalize().expect("canonical");
        let shared = shared.canonicalize().expect("canonical");
        let note = notes.join("todo.md");
        assert!(workspace.confines(&note).is_ok());
        assert!(trust.is_trusted(&note.display().to_string()));

        assert!(close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &notes.display().to_string(),
        ));

        assert!(
            workspace.confines(&note).is_err(),
            "the closed directory is still reachable"
        );
        assert!(
            !trust.is_trusted(&note.display().to_string()),
            "the closed directory is still trusted"
        );
        assert!(workspace.confines(&shared.join("todo.md")).is_ok());
        assert!(
            trust.is_trusted(&shared.join("todo.md").display().to_string()),
            "closing one directory withdrew another's rule"
        );
        let said = &session.transcript.last().expect("a note").text;
        assert!(said.contains("no longer trusting it"), "{said}");

        assert!(!close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &notes.display().to_string(),
        ));
        let said = &session.transcript.last().expect("a note").text;
        assert!(said.contains("could not close"), "{said}");
        assert!(!close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            ""
        ));
        let said = &session.transcript.last().expect("a note").text;
        assert!(said.contains("/add-dir close needs a directory"), "{said}");
        assert_eq!(workspace.added_directories(), std::slice::from_ref(&shared));

        let kept = shared.join("todo.md").display().to_string();
        trust.distrust(&bravebot_agent::workspace::key_of(&shared));
        assert!(close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &shared.display().to_string(),
        ));
        let said = &session.transcript.last().expect("a note").text;
        assert!(
            !said.contains("no longer trusting it"),
            "a close that withdrew nothing said it did: {said}"
        );
        assert_eq!(
            trust.integrity_of(&kept),
            Some(bravebot_core::label::Integrity::Untrusted)
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// `/add-dir close` rewrites the record at once where one is on disk, so a session that closed
    /// a directory and then quit does not resume with it open and trusted. A session nobody has
    /// asked anything in has no record, and closing a directory does not make one.
    #[test]
    fn closing_a_directory_rewrites_the_record_on_disk_and_writes_none_where_there_is_not() {
        use bravebot_session::sessions;

        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let base = crate::test_profile::project("bravebot-app-close-directory-record");
        let root = base.join("project");
        let notes = base.join("notes");
        std::fs::create_dir_all(&root).expect("create");
        std::fs::create_dir_all(&notes).expect("create");
        let notes = notes.display().to_string();
        let mut workspace = Workspace::new(&root).expect("a workspace");
        let mut session = Session::new("none");
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(TrustStore::new(&root), TrustedPrograms::new(), rules);
        let mut stored =
            sessions::Handle::begin(&root, sessions::Front::Terminal, bravebot_stamp::BUILD);
        let mut conversation = Conversation::new();
        let mut scratch = None;
        let settings = bravebot_config::Settings::default();
        let run_settings = RunSettings::from_settings(&settings);
        let mut held = Held {
            session: &mut session,
            conversation: &mut conversation,
            stored: &mut stored,
            answers: &mut answers,
            workspace: &mut workspace,
            scratch: &mut scratch,
            settings: &settings,
            run_settings: &run_settings,
        };

        held.add_directory_command(&notes);
        held.close_directory_command(&notes);
        assert_eq!(
            held.stored.resumable(),
            None,
            "closing a directory wrote a record for a session nobody asked anything in"
        );
        assert!(sessions::list(&root).is_empty());

        held.add_directory_command(&notes);
        held.save("tidy the notes");
        let id = held.stored.id().to_string();
        assert_eq!(
            sessions::load(&root, &id)
                .expect("the record just saved")
                .directories
                .len(),
            1,
            "the record did not name the directory that was open"
        );

        held.close_directory_command(&notes);
        assert!(
            sessions::load(&root, &id)
                .expect("the record")
                .directories
                .is_empty(),
            "the record on disk still names the directory that was closed"
        );
    }

    /// MOUSE-42 and MOUSE-43: a click on a path is carried out against the working directory and the
    /// session's rules. A name that climbs out, leads out, names a directory or names nothing is
    /// refused with the one sentence and without the name, by the preview and by the editor alike.
    /// A file a `deny` rule covers is refused by the preview, which reads it, and is opened by the
    /// editor, which is the person's own program.
    #[test]
    fn a_click_on_a_path_is_held_to_the_working_directory_and_only_the_preview_to_the_deny_rules() {
        use crate::text_links::PathRef;
        use bravebot_core::permissions::{Anchors, Permissions};
        use bravebot_session::sessions;

        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let base = crate::test_profile::project("bravebot-app-click-on-a-path");
        let root = base.join("project");
        std::fs::create_dir_all(root.join("src")).expect("create");
        std::fs::write(root.join("src/main.rs"), "fn main() {}\n").expect("a file");
        std::fs::write(root.join(".env"), "TOKEN=1\n").expect("a file");
        std::fs::write(base.join("outside.txt"), "outside\n").expect("a file");
        #[cfg(unix)]
        std::os::unix::fs::symlink(base.join("outside.txt"), root.join("leads-out.txt"))
            .expect("a link");
        let mut workspace = Workspace::new(&root).expect("a workspace");
        let mut session = Session::new("none");
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(TrustStore::new(&root), TrustedPrograms::new(), rules);
        let (denying, rejected) =
            Permissions::parse(&["Read(.env)".to_string()], &[], &[], &Anchors::none());
        assert!(rejected.is_empty());
        answers.rules.permissions = denying;
        let mut stored =
            sessions::Handle::begin(&root, sessions::Front::Terminal, bravebot_stamp::BUILD);
        let mut conversation = Conversation::new();
        let mut scratch = None;
        let settings = bravebot_config::Settings::default();
        let run_settings = RunSettings::from_settings(&settings);
        let mut held = Held {
            session: &mut session,
            conversation: &mut conversation,
            stored: &mut stored,
            answers: &mut answers,
            workspace: &mut workspace,
            scratch: &mut scratch,
            settings: &settings,
            run_settings: &run_settings,
        };
        let path = |name: &str| PathRef {
            path: name.to_string(),
            line: None,
            column: None,
        };
        let outside = base.join("outside.txt").display().to_string();
        let last_note = |held: &Held| held.session.transcript.last().expect("a note").text.clone();

        let refused = t!(session_path_not_a_file).to_string();
        for named in [
            "../outside.txt",
            "src/../../outside.txt",
            outside.as_str(),
            "leads-out.txt",
            "src",
            "missing.rs",
        ] {
            assert_eq!(held.file_to_edit(&path(named)), None, "{named:?}");
            assert_eq!(last_note(&held), refused, "{named:?}");
            held.preview_file(&path(named));
            assert_eq!(last_note(&held), refused, "{named:?}");
            assert!(!last_note(&held).contains(named), "{named:?}");
        }

        let denied = t!(session_preview_denied).to_string();
        held.preview_file(&path(".env"));
        assert_eq!(last_note(&held), denied);
        assert_eq!(
            held.file_to_edit(&path(".env")),
            Some(held.workspace.root().join(".env")),
            "the editor was refused a file a deny rule covers"
        );

        held.preview_file(&path("src/main.rs"));
        let shown = held
            .session
            .transcript
            .last()
            .and_then(|entry| entry.shown.as_ref())
            .expect("the file was shown");
        assert_eq!(shown.preview, ["1  fn main() {}"]);
        assert_eq!(
            held.file_to_edit(&path("src/main.rs")),
            Some(held.workspace.root().join("src/main.rs"))
        );
    }

    /// PERM-16 at the other door onto the same reach: `/add-dir` is refused with the key named, and
    /// nothing is vouched for, where a settings layer asked for the tools to stay inside.
    #[test]
    fn add_dir_is_refused_where_reads_stay_in_the_workspace() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-confined-test");
        let project = root.join("project");
        let outside = root.join("shared");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&outside).expect("scratch");

        let mut workspace = Workspace::new(&project)
            .expect("workspace")
            .with_reads_kept_inside(true);
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");

        add_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &outside.display().to_string(),
        );

        assert!(
            workspace.added_directories().is_empty(),
            "a directory the settings keep shut was opened"
        );
        assert!(
            trust.is_empty(),
            "a directory that was not opened was vouched for"
        );
        assert!(
            session.transcript[0]
                .text
                .contains("permissions.readsStayInWorkspace"),
            "the refusal did not name the key that made it: {}",
            session.transcript[0].text
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// A session whose working directory is `project`, after `/add-dir <named>`.
    fn after_add_dir(project: &Path, named: &str) -> (Workspace, TrustStore, Session) {
        let mut workspace = Workspace::new(project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");
        add_directory(&mut session, &mut workspace, &mut trust, named);
        (workspace, trust, session)
    }

    /// TRUST-9: `/add-dir` takes a path relative to the working directory, and opens, trusts and
    /// names the directory the absolute spelling of it opens, trusts and names.
    ///
    /// The failures this rejects are a name passed on for the workspace to refuse as not absolute,
    /// and one resolved against the directory the program was started in, which is not what a
    /// relative path means anywhere else in the session. The scratch directory is not the one the
    /// tests run in, so the second reaches another directory than the one asked for.
    #[test]
    fn add_dir_opens_a_relative_name_as_it_opens_the_absolute_one() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-relative-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let notes = notes.canonicalize().expect("canonical");
        let todo = notes.join("todo.md").display().to_string();
        let opened = |named: &str| {
            let (workspace, trust, session) = after_add_dir(&project, named);
            (
                workspace.added_directories(),
                trust.is_trusted(&todo),
                last_note(&session).to_string(),
            )
        };

        let by_absolute = opened(&notes.display().to_string());
        assert_eq!(
            by_absolute,
            (
                vec![notes.clone()],
                true,
                t!(
                    session_directory_added,
                    directory = notes.display().to_string()
                )
            ),
            "the absolute spelling no longer opens, trusts and names the directory"
        );
        for named in ["../notes", "./../notes", "../notes/", "../project/../notes"] {
            assert_eq!(
                opened(named),
                by_absolute,
                "{named} did not open what the absolute spelling opens"
            );
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: the rule `/add-dir` records is under the directory a relative name resolves to, and
    /// not under the name typed, and a name that goes through a link inside the project opens and
    /// trusts what the link points to, as the absolute spelling of the link does, with the note
    /// naming the target. `./link` is a name inside the project that leads out of it: a rule keyed
    /// under the link would be a rule about a path in the project, where a person's answer about
    /// the project already decides.
    #[cfg(unix)]
    #[test]
    fn add_dir_records_trust_under_the_directory_a_relative_name_resolves_to() {
        use bravebot_core::label::Integrity;

        let root = crate::testutil::scratch_dir("bravebot-add-dir-relative-key-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("elsewhere/notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        std::os::unix::fs::symlink(&notes, project.join("link")).expect("a link");
        let notes = notes.canonicalize().expect("canonical");
        let project = project.canonicalize().expect("canonical");

        for named in ["./link", &project.join("link").display().to_string()] {
            let (workspace, trust, session) = after_add_dir(&project, named);

            assert_eq!(
                workspace.added_directories(),
                std::slice::from_ref(&notes),
                "{named}"
            );
            assert_eq!(
                trust.keyed().collect::<Vec<_>>(),
                [(
                    bravebot_agent::workspace::key_of(&notes).as_str(),
                    Some(Integrity::Trusted)
                )],
                "the rule for {named} was not recorded under the directory it resolves to"
            );
            assert!(trust.is_trusted(&notes.join("todo.md").display().to_string()));
            assert_eq!(
                last_note(&session),
                t!(
                    session_directory_added,
                    directory = notes.display().to_string()
                ),
                "{named}"
            );
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: `/add-dir ../` opens the directory that holds the project and trusts it, naming that
    /// directory and not the name typed. A directory holding the project is not refused.
    #[test]
    fn add_dir_of_the_parent_opens_and_trusts_the_directory_holding_the_project() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-parent-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let held = root.canonicalize().expect("canonical");

        let (workspace, trust, session) = after_add_dir(&project, "../");

        assert_eq!(workspace.added_directories(), std::slice::from_ref(&held));
        assert_eq!(
            session.transcript[0].text,
            t!(
                session_directory_added,
                directory = held.display().to_string()
            )
        );
        for file in ["notes/todo.md", "project/main.rs"] {
            assert!(
                trust.is_trusted(&held.join(file).display().to_string()),
                "the rule at the parent does not cover {file}"
            );
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: a relative name means the working directory the session is in now. After `/cd` it
    /// is the new one, and the directory beside the old one is not what `../notes` reaches.
    ///
    /// The failure this rejects is a name resolved against the directory the session started in.
    #[test]
    fn a_relative_name_means_the_working_directory_after_a_cd() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-relative-cd-test");
        let _ = std::fs::remove_dir_all(&root);
        for directory in ["one/project", "one/notes", "two/project", "two/notes"] {
            std::fs::create_dir_all(root.join(directory)).expect("scratch");
        }
        let mut workspace = Workspace::new(root.join("one/project")).expect("workspace");
        let mut session = Session::new("none");
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(
            TrustStore::new(workspace.root()),
            TrustedPrograms::new(),
            rules,
        );
        let moved = change_directory(
            &mut session,
            &mut workspace,
            &mut answers,
            "a-session",
            &root.join("two/project").display().to_string(),
            |_, _| Some(true),
        );
        assert_eq!(moved, Changed::Moved);

        add_directory(&mut session, &mut workspace, &mut answers.trust, "../notes");

        assert_eq!(
            workspace.added_directories(),
            [root.join("two/notes").canonicalize().expect("canonical")]
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: `/add-dir` refuses a relative name for the reasons it refuses the absolute spelling
    /// of it, and nothing is opened or vouched for. The refusal begins with the name as it was typed
    /// and then quotes the absolute path the name resolved to, so a person sees which directory was
    /// refused. A name that is not a directory, one that is nowhere, and one inside the project each
    /// keep the reason they have when spelled in full, and the last still says it can be named
    /// relatively. No path at all says it needs one, and is not read as the working directory.
    #[test]
    fn add_dir_refuses_a_relative_name_as_it_refuses_the_absolute_one() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-relative-refused-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        std::fs::create_dir_all(project.join("sub")).expect("scratch");
        std::fs::write(root.join("file.txt"), "text").expect("a file");
        let project = project.canonicalize().expect("canonical");
        let root = root.canonicalize().expect("canonical");

        for (relative, absolute, reason) in [
            ("../nowhere", root.join("nowhere"), None),
            (
                "../file.txt",
                root.join("file.txt"),
                Some("must be a directory"),
            ),
            (
                "./sub",
                project.join("sub"),
                Some("is already inside the workspace, so it can be named relatively"),
            ),
            (
                "../project/sub",
                project.join("sub"),
                Some("is already inside the workspace, so it can be named relatively"),
            ),
            (
                ".",
                project.clone(),
                Some("is already inside the workspace, so it can be named relatively"),
            ),
        ] {
            let (workspace, trust, session) = after_add_dir(&project, relative);
            let said = last_note(&session);
            let absolute = absolute.display().to_string();
            let (_, _, by_absolute) = after_add_dir(&project, &absolute);
            let by_absolute = last_note(&by_absolute);

            let after_the_path = by_absolute
                .strip_prefix(&format!("could not add {absolute}: '{absolute}'"))
                .unwrap_or_else(|| panic!("the absolute spelling was not refused: {by_absolute}"));
            assert_eq!(
                said,
                format!("could not add {relative}: '{absolute}'{after_the_path}"),
                "{relative} was not refused as {absolute} is, under the name typed"
            );
            if let Some(reason) = reason {
                assert!(said.contains(reason), "{said}");
            }
            assert!(workspace.added_directories().is_empty(), "{relative}");
            assert!(trust.is_empty(), "{relative} was vouched for");
        }

        let (workspace, trust, session) = after_add_dir(&project, "");
        assert_eq!(last_note(&session), t!(session_add_dir_needs_a_path));
        assert!(workspace.added_directories().is_empty());
        assert!(trust.is_empty());

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9 and SANDBOX-18: a relative name that lands in a credential location is refused as
    /// the absolute spelling is, and one that lands in the home directory, which holds a location,
    /// is not. The refusal is decided on the directory the name resolves to, so a name that climbs
    /// to a location is not a way past.
    ///
    /// The home directory is a scratch one, so the test runs in a process of its own. Where this
    /// process is not that one, `in_isolated_profile` runs the test there and fails this one if it
    /// failed, so the assertions below are always run before the test passes.
    #[test]
    fn add_dir_refuses_a_relative_name_that_reaches_a_credential_location() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let home = bravebot_agent::home::profile()
            .expect("a profile")
            .canonicalize()
            .expect("canonical");
        let project = home.join("projects/project");
        for directory in [".ssh", "notes"] {
            std::fs::create_dir_all(home.join(directory)).expect("create");
        }
        std::fs::create_dir_all(&project).expect("create");

        let (workspace, trust, session) = after_add_dir(&project, "../../.ssh");
        assert!(
            last_note(&session).contains("credential location"),
            "{}",
            last_note(&session)
        );
        assert!(workspace.added_directories().is_empty());
        assert!(trust.is_empty());

        for (named, opened) in [("../../notes", home.join("notes")), ("../..", home.clone())] {
            let (workspace, ..) = after_add_dir(&project, named);
            assert_eq!(
                workspace.added_directories(),
                [opened],
                "{named} was refused"
            );
        }
    }

    /// TRUST-9: `/add-dir close` takes a relative name as it takes the absolute spelling, so a
    /// directory opened under one spelling closes under the other, and both halves go. A
    /// directory that has gone since closes under a relative name too, and a name that is not open
    /// is refused under the spelling typed.
    ///
    /// The failure this rejects is a close that leaves the name for the workspace to refuse as
    /// not absolute, which would leave a directory a person opened with a short name open.
    #[test]
    fn add_dir_close_takes_a_relative_name_as_it_takes_the_absolute_one() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-close-relative-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes, &root.join("shared")] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let notes = notes.canonicalize().expect("canonical");
        let absolute = notes.display().to_string();
        let todo = notes.join("todo.md");

        for (opened_with, closed_with) in [
            (absolute.as_str(), "../notes"),
            ("../notes", absolute.as_str()),
            ("../notes", "../shared/../notes"),
            ("../notes", "./../notes/"),
        ] {
            let (mut workspace, mut trust, mut session) = after_add_dir(&project, opened_with);
            assert!(workspace.confines(&todo).is_ok(), "{opened_with}");

            assert!(
                close_directory(&mut session, &mut workspace, &mut trust, closed_with),
                "{closed_with} did not close what {opened_with} opened: {}",
                last_note(&session)
            );

            assert!(workspace.added_directories().is_empty());
            assert!(workspace.confines(&todo).is_err(), "{closed_with}");
            assert!(trust.is_empty(), "{closed_with} left the rule");
            assert_eq!(
                last_note(&session),
                t!(session_directory_withdrawn, directory = absolute.as_str()),
                "{closed_with}"
            );
        }

        let (mut workspace, mut trust, mut session) = after_add_dir(&project, "../notes");
        std::fs::remove_dir_all(&notes).expect("the directory goes");
        assert!(
            close_directory(&mut session, &mut workspace, &mut trust, "../notes"),
            "a directory that has gone did not close: {}",
            last_note(&session)
        );
        assert!(workspace.added_directories().is_empty());

        assert!(!close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            "../shared"
        ));
        assert!(
            last_note(&session).starts_with("could not close ../shared: '"),
            "{}",
            last_note(&session)
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: a relative name closes the directory it names even when a link has been put where
    /// that directory was. A relative name with no `..` after a name is made the absolute spelling
    /// the directory was opened under before the workspace is asked, so the close matches it as
    /// spelled, as it does the absolute name, and the link cannot send it to the link's target.
    /// `notes` and `shared` are opened by absolute path and `notes` is then replaced by a link to
    /// `shared`.
    ///
    /// The failure this rejects is a relative name joined as typed, which is never equal to an
    /// opened directory's recorded spelling and so is only ever followed through the link, closing
    /// `shared` and leaving `notes` open.
    #[cfg(unix)]
    #[test]
    fn add_dir_close_by_a_relative_name_is_not_redirected_by_a_link_put_where_the_directory_was() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-close-link-test");
        for by_absolute in [true, false] {
            let _ = std::fs::remove_dir_all(&root);
            let project = root.join("project");
            let notes = root.join("notes");
            let shared = root.join("shared");
            for directory in [&project, &notes, &shared] {
                std::fs::create_dir_all(directory).expect("scratch");
            }
            let notes = notes.canonicalize().expect("canonical");
            let shared = shared.canonicalize().expect("canonical");
            let closed_with = match by_absolute {
                true => notes.display().to_string(),
                false => "../notes".to_string(),
            };
            let (mut workspace, mut trust, mut session) =
                after_add_dir(&project, &notes.display().to_string());
            add_directory(
                &mut session,
                &mut workspace,
                &mut trust,
                &shared.display().to_string(),
            );
            std::fs::remove_dir_all(&notes).expect("the directory goes");
            std::os::unix::fs::symlink(&shared, &notes).expect("a link");

            assert!(
                close_directory(&mut session, &mut workspace, &mut trust, &closed_with),
                "{closed_with} closed nothing: {}",
                last_note(&session)
            );

            assert_eq!(
                workspace.added_directories(),
                std::slice::from_ref(&shared),
                "{closed_with} closed another directory than `notes`"
            );
            assert!(
                trust.is_trusted(&shared.join("todo.md").display().to_string()),
                "{closed_with} took back the rule of `shared`"
            );
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: a name that climbs out of the working directory and back into the directory beside
    /// it opens that directory and closes it, under each spelling of the climb. The three are the
    /// ones a person types: `../notes`, `./../notes` and one that goes back through the project's
    /// own name.
    ///
    /// The failure this rejects is a cleaning of the leading `..` that steps over a different
    /// number of directories than it names, which opens or closes the wrong one.
    #[test]
    fn a_climbing_relative_name_opens_and_closes_the_directory_it_names() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-climb-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let notes = notes.canonicalize().expect("canonical");

        for named in ["../notes", "./../notes", "../project/../notes"] {
            let (mut workspace, mut trust, mut session) = after_add_dir(&project, named);
            assert_eq!(
                workspace.added_directories(),
                std::slice::from_ref(&notes),
                "{named} did not open `notes`"
            );

            assert!(
                close_directory(&mut session, &mut workspace, &mut trust, named),
                "{named} did not close what it opened: {}",
                last_note(&session)
            );

            assert!(workspace.added_directories().is_empty(), "{named}");
            assert!(trust.is_empty(), "{named} left the rule");
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// TRUST-9: a leading `~` is the home directory before it is a name under the working
    /// directory, so `~/notes` opens and closes the home's `notes` and not the directory `notes`
    /// inside a directory called `~` in the project, which is what the other order reads. Both
    /// exist here, and the second is inside the project, which `/add-dir` refuses.
    ///
    /// The home is a scratch one, so the test runs in a process of its own. Where this process is
    /// not that one, `in_isolated_profile` runs the test there and fails this one if it failed, so
    /// the assertions below are always run before the test passes.
    #[test]
    fn add_dir_reads_a_leading_tilde_as_the_home_before_a_name_under_the_project() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let home = bravebot_agent::home::profile()
            .expect("a profile")
            .canonicalize()
            .expect("canonical");
        let project = home.join("projects/project");
        std::fs::create_dir_all(home.join("notes")).expect("create");
        std::fs::create_dir_all(project.join("~/notes")).expect("a directory called ~");

        let (mut workspace, mut trust, mut session) = after_add_dir(&project, "~/notes");

        assert_eq!(
            workspace.added_directories(),
            [home.join("notes")],
            "`~/notes` did not open the home's notes: {}",
            last_note(&session)
        );
        assert!(close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            "~/notes"
        ));
        assert!(
            workspace.added_directories().is_empty(),
            "`~/notes` did not close the home's notes: {}",
            last_note(&session)
        );
    }

    /// TRUST-9 and PERM-16: a relative name is refused where the settings keep the file tools
    /// inside the workspace, with the key named, as the absolute spelling is. The refusal is the
    /// first thing the workspace decides about a directory it is asked to open, before it asks
    /// whether the name is absolute, so this passes without the relative-name handling too. It
    /// holds the claim that a relative name goes through the same refusals, and rejects a handler
    /// that opens a relative name by a route that does not go through them.
    #[test]
    fn add_dir_refuses_a_relative_name_where_reads_stay_in_the_workspace() {
        let root = crate::testutil::scratch_dir("bravebot-add-dir-relative-confined-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(root.join("shared")).expect("scratch");
        let mut workspace = Workspace::new(&project)
            .expect("workspace")
            .with_reads_kept_inside(true);
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");

        add_directory(&mut session, &mut workspace, &mut trust, "../shared");

        assert!(workspace.added_directories().is_empty());
        assert!(trust.is_empty());
        assert!(
            last_note(&session).contains("permissions.readsStayInWorkspace"),
            "{}",
            last_note(&session)
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// VIEW-8: what `/add-dir` did and what it refused are drawn in different inks, so a directory
    /// that was added is not read as one more error beside two refusals. The notes come from the
    /// handler, so a call site left on the plain note fails here.
    ///
    /// The failure this rejects is every note of the command drawn in the one ink of the plain
    /// notes, which drew the success in the colour of the refusals before it.
    #[test]
    fn add_dir_draws_the_directory_it_added_apart_from_the_names_it_refused() {
        use crate::testutil::inks_on_row_containing;

        let _held = crate::theme::exclusive();
        crate::theme::apply_brave();
        let root = crate::testutil::scratch_dir("bravebot-add-dir-inks-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");
        for named in ["../nowhere", "", &notes.display().to_string()] {
            add_directory(&mut session, &mut workspace, &mut trust, named);
        }

        let added = inks_on_row_containing(&session, "added ");
        let refused = inks_on_row_containing(&session, "could not add");
        let needs_a_path = inks_on_row_containing(&session, "/add-dir needs a directory");

        assert!(
            added.iter().all(|ink| *ink == crate::theme::ok()),
            "the directory added is not drawn as finished: {added:?}"
        );
        for refusal in [&refused, &needs_a_path] {
            assert!(
                refusal.iter().all(|ink| *ink == crate::theme::fail()),
                "a refusal is not drawn as failed: {refusal:?}"
            );
        }
        assert!(
            !added.contains(&crate::theme::note()),
            "the success is drawn in the ink every note shares"
        );
        for inks in [&added, &refused, &needs_a_path] {
            assert!(
                !inks.contains(&crate::theme::running()),
                "a note is drawn in the ink that marks untrusted content: {inks:?}"
            );
        }

        std::fs::remove_dir_all(&root).ok();
    }

    /// VIEW-8: `/add-dir close` draws a close that happened, with or without a rule withdrawn, in
    /// the ink for finished, and a name it could not close and a close with no name in the ink for
    /// failed. Each is drawn in a session of its own so that a note is found by the words it begins
    /// with and not by a word the others share.
    #[test]
    fn add_dir_close_draws_what_it_closed_apart_from_what_it_refused() {
        let _held = crate::theme::exclusive();
        crate::theme::apply_brave();
        let root = crate::testutil::scratch_dir("bravebot-add-dir-close-inks-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let notes = notes.canonicalize().expect("canonical");
        let opened = || {
            let mut workspace = Workspace::new(&project).expect("workspace");
            let mut trust = TrustStore::new(workspace.root());
            add_directory(
                &mut Session::new("none"),
                &mut workspace,
                &mut trust,
                &notes.display().to_string(),
            );
            (workspace, trust)
        };

        let closing = |named: &str, distrusted: bool| {
            let (mut workspace, mut trust) = opened();
            if distrusted {
                trust.distrust(&bravebot_agent::workspace::key_of(&notes));
            }
            let mut session = Session::new("none");
            close_directory(&mut session, &mut workspace, &mut trust, named);
            session
        };
        let notes = notes.display().to_string();
        for (session, needle, ink) in [
            (closing(&notes, false), "closed", crate::theme::ok()),
            (closing(&notes, true), "closed", crate::theme::ok()),
            (
                closing("../project", false),
                "could not close",
                crate::theme::fail(),
            ),
            (
                closing("", false),
                "/add-dir close needs a directory",
                crate::theme::fail(),
            ),
        ] {
            let said = session.transcript.last().expect("a note").text.clone();
            let inks = crate::testutil::inks_on_row_containing(&session, needle);
            assert!(
                inks.iter().all(|drawn| *drawn == ink),
                "{said:?} was not drawn in {ink:?}: {inks:?}"
            );
            assert!(
                !inks.contains(&crate::theme::running()),
                "{said:?} is drawn in the ink that marks untrusted content"
            );
        }
        let withdrawn = closing(&notes, false).transcript.remove(0).text;
        let kept = closing(&notes, true).transcript.remove(0).text;
        assert!(withdrawn.contains("no longer trusting it"), "{withdrawn}");
        assert!(!kept.contains("no longer trusting it"), "{kept}");

        std::fs::remove_dir_all(&root).ok();
    }

    /// VIEW-8: where the palette draws every ink as the terminal's own, which is what `NO_COLOR`
    /// asks for, the notes of `/add-dir` are told apart by what they say, and nothing about how
    /// they are drawn depends on a colour.
    ///
    /// The failure this rejects is a tone drawn in a colour of its own and not through the
    /// palette, which would paint a person's terminal after they asked for no colour.
    #[test]
    fn under_a_palette_without_colour_the_wording_tells_what_add_dir_did_from_what_it_refused() {
        use crate::testutil::inks_on_row_containing;
        use ratatui::style::Color;

        /// Puts `brave` back when the test ends, however it ends, so a failed assertion does not
        /// leave the palette without colour in force for the tests that read a colour.
        struct BraveWhenDropped;
        impl Drop for BraveWhenDropped {
            fn drop(&mut self) {
                crate::theme::apply_brave();
            }
        }

        let _held = crate::theme::exclusive();
        let _restored = BraveWhenDropped;
        crate::theme::apply(&crate::theme::Theme {
            name: "no-colour".to_string(),
            palette: crate::theme::plain_palette(),
            adapts: false,
            listed: false,
        });
        let root = crate::testutil::scratch_dir("bravebot-add-dir-no-colour-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");
        add_directory(&mut session, &mut workspace, &mut trust, "../nowhere");
        add_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &notes.display().to_string(),
        );

        let refused = inks_on_row_containing(&session, "could not add");
        let added = inks_on_row_containing(&session, "added ");

        assert!(refused.iter().chain(&added).all(|ink| *ink == Color::Reset));
        let said: Vec<&str> = session.transcript.iter().map(|n| n.text.as_str()).collect();
        assert!(said[0].starts_with("could not add "), "{said:?}");
        assert!(said[1].starts_with("added "), "{said:?}");

        std::fs::remove_dir_all(&root).ok();
    }

    /// VIEW-8: the directories a settings file names are told in the tones `/add-dir` tells them
    /// in. A name that does not open is refused through `named_to_open`, in the message
    /// `/add-dir` refuses with, and a name that does open is opened through `open_named`, which
    /// goes through the `/add-dir` handler, so the one is a refused note and the other a done note.
    ///
    /// The failures this rejects are the refusal left as a plain note, which would draw the same
    /// message in another ink depending on which door the name came in by, and an opening that
    /// does not go through the handler and writes its note some other way.
    #[test]
    fn the_directories_a_settings_file_names_are_told_in_the_tones_of_add_dir() {
        use crate::state::Tone;

        let root = crate::testutil::scratch_dir("bravebot-settings-names-tones-test");
        let _ = std::fs::remove_dir_all(&root);
        let project = root.join("project");
        let notes = root.join("notes");
        for directory in [&project, &notes] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none");

        let accepted = named_to_open(
            &mut session,
            &workspace,
            &["../nowhere".to_string(), "../notes".to_string()],
        );
        open_named(&mut session, &mut workspace, &mut trust, &accepted);

        let said: Vec<(Tone, &str)> = session
            .transcript
            .iter()
            .map(|entry| (entry.tone, entry.text.as_str()))
            .collect();
        assert_eq!(said.len(), 2, "{said:?}");
        assert_eq!(said[0].0, Tone::Refused, "{said:?}");
        assert!(
            said[0].1.starts_with("could not add ../nowhere: "),
            "{said:?}"
        );
        assert_eq!(said[1].0, Tone::Done, "{said:?}");
        assert!(said[1].1.starts_with("added "), "{said:?}");

        std::fs::remove_dir_all(&root).ok();
    }

    /// VIEW-8: a refused command is not the failure of a turn. A note of a refusal written during a
    /// turn that then fails, and another written after it, leave the reason the status area
    /// repeats, the reason the turn is recorded under and the one failure an export holds as they
    /// were.
    ///
    /// The failure this rejects is a refusal recorded as `Entry::failure`, which an export writes
    /// under "Failed", the status area would repeat in place of the turn's reason, and a turn's
    /// record would take as its reason when it came first.
    #[test]
    fn a_refused_command_is_not_taken_for_the_failure_of_the_turn_around_it() {
        use bravebot_aichat::{AccountFailure, ChatError};
        use bravebot_session::sessions::StoredOutcome;

        let mut session = Session::new("none");
        type_line(&mut session, "read a file");
        session.submit().expect("the prompt is sent");
        session.note_refused("could not add ../before: refused during the turn");
        let error = bravebot_agent::backend::BackendError::Attempted {
            usage: None,
            context_tokens: None,
            attempts: 2,
            cause: Box::new(bravebot_agent::backend::BackendError::from(
                ChatError::Account(AccountFailure::NotSignedIn),
            )),
        };
        fold_outcome(
            &mut session,
            Err(turn::TurnError::from(error)),
            Trail::new(),
            Carried {
                asked: Default::default(),
                exposed: Default::default(),
                trust: TrustStore::new("/work"),
                programs: TrustedPrograms::new(),
            },
            Occupied {
                budget: 1000,
                guessed: false,
                last_request_tokens: 0,
            },
            Asked {
                name: "chatgpt/gpt-test".into(),
                comparable: true,
            },
            Line {
                text: "read a file",
                addressed: None,
                offered_a_later_look: false,
            },
            &workspace_for_test(),
        );
        session.record_turn(0, &Conversation::new());
        session.note_refused("could not close ../after: refused after the turn");
        assert!(session.finished.expect("the turn ended").failed());

        let said = session.failure_said().expect("the turn's reason");
        assert!(said.contains("not signed in"), "{said}");
        let recorded = session.turn_history().last().expect("the turn is recorded");
        match &recorded.outcome {
            Some(StoredOutcome::Failed { reason }) => {
                assert!(reason.contains("not signed in"), "{reason}")
            }
            other => panic!("the turn was not recorded as failed: {other:?}"),
        }
        let exported = render::as_markdown(&session, "test");
        assert_eq!(exported.matches("## Failed").count(), 1, "{exported}");
    }

    /// REFER-6: the alias a person is offered after `@` follows what the workspace has open. The
    /// session is told again after `/add-dir close`, `/add-dir` and `/cd`, so an alias disappears
    /// when its directory is closed or left behind and returns when the directory is opened again.
    ///
    /// The regression this rejects is a session that keeps the list it was given at startup, which
    /// offers a name the file tools refuse after a close and misses one after the directory is
    /// opened again.
    #[test]
    fn the_alias_offered_follows_add_dir_close_add_dir_and_cd() {
        fn alias_offered(session: &Session) -> bool {
            match session.offered() {
                crate::state::Offered::Files(entries) => {
                    entries.iter().any(|entry| entry.path == "lib/")
                }
                _ => false,
            }
        }

        let root = crate::testutil::scratch_dir("bravebot-alias-follows-open-test");
        let project = root.join("project");
        let library = root.join("library");
        for directory in [&project, &library] {
            std::fs::create_dir_all(directory).expect("scratch");
        }
        let mut workspace = Workspace::new(&project)
            .expect("workspace")
            .with_references(
                &[bravebot_config::Reference {
                    alias: "lib".to_string(),
                    path: library.display().to_string(),
                    description: None,
                }],
                &[],
            );
        let mut trust = TrustStore::new(workspace.root());
        let mut session = Session::new("none").in_workspace(workspace.root());
        session.set_reference_sources(workspace.reference_sources());
        for c in "@li".chars() {
            session.type_char(c);
        }
        assert!(alias_offered(&session), "an open reference was not offered");

        assert!(close_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &library.display().to_string(),
        ));
        assert!(
            !alias_offered(&session),
            "`/add-dir close` left the alias offered"
        );

        add_directory(
            &mut session,
            &mut workspace,
            &mut trust,
            &library.display().to_string(),
        );
        assert!(
            alias_offered(&session),
            "`/add-dir` of the reference's directory did not offer the alias again"
        );

        // A `/cd` to a directory that holds the reference closes it, which is the other way an
        // open directory goes.
        let rules_state = root.join("state");
        let rules = starting_rules(&mut session, &rules_state, workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        let moved = change_directory(
            &mut session,
            &mut workspace,
            &mut answers,
            "a-session",
            &root.display().to_string(),
            |_, _| Some(true),
        );
        assert_eq!(moved, Changed::Moved);
        assert!(
            workspace.reference_sources().is_empty(),
            "the `/cd` did not close the reference it overlaps"
        );
        assert!(!alias_offered(&session), "`/cd` left the alias offered");

        std::fs::remove_dir_all(&root).ok();
    }

    /// The person who was asked about the working directory is asked about each directory a file
    /// named too, because a name in a file is a request for reach and trust rather than a grant of
    /// either, and the file is the easiest thing in a checkout to write to.
    #[test]
    fn a_person_asked_about_the_workspace_is_asked_about_each_named_directory() {
        let named = vec!["/home/me/notes".to_string(), "/home/me/.ssh".to_string()];

        assert_eq!(
            named_directories(Whence::Asked, &named),
            Named::Asking(named)
        );
    }

    /// The mode that answers every permission question answers these as well. It approves every
    /// write, every run and vouching for every file the planner reads, so stopping at a modal box
    /// about a directory would be the one thing it did not answer.
    #[test]
    fn bypassing_opens_the_directories_a_file_named_without_asking() {
        let named = vec!["/home/me/notes".to_string()];

        assert_eq!(
            named_directories(Whence::Unasked, &named),
            Named::Opening(named)
        );
    }

    /// A session resumed with the map its own user left puts no question, and the directories it
    /// has open are the ones its own record reopened. Taking a name from the file as well would
    /// open a directory on behalf of somebody who was never asked, out of a file that may have
    /// been edited since they answered.
    #[test]
    fn a_resume_that_brought_its_own_map_opens_no_directory_a_file_named() {
        let named = vec!["/home/me/notes".to_string()];

        assert_eq!(
            named_directories(Whence::Resumed, &named),
            Named::Opening(Vec::new())
        );
    }

    /// The rules a checkout proposes in the tests below.
    fn proposed(rules: &[&str]) -> Vec<bravebot_agent::granted::Proposed> {
        rules
            .iter()
            .map(|rule| {
                bravebot_agent::granted::Proposed::new(
                    std::path::Path::new("/work/.bravebot/settings.json"),
                    rule,
                )
            })
            .collect()
    }

    /// PERM-11, PERM-15: the list this interface builds holds the entries that are rules and not
    /// the ones that are not. A line nothing can act on is reported for what is wrong with it, so
    /// offering it in the box would ask somebody to grant a rule that would still decide nothing
    /// once they had, and telling them it was withheld sends them to the wrong fix.
    ///
    /// From files rather than from [`bravebot_config::Settings::parse`], because which layer wrote
    /// an entry is what puts it in this list at all. The tests below start from a list already
    /// built, so this is the one that pins where the interface's own comes from.
    #[test]
    fn a_checkouts_entry_is_proposed_here_only_where_it_is_a_rule() {
        let root = crate::testutil::scratch_dir("bravebot-app-proposed-rules");
        let _ = std::fs::remove_dir_all(&root);
        let home = root.join("home");
        let cwd = root.join("cwd");
        std::fs::create_dir_all(&home).expect("scratch home");
        std::fs::create_dir_all(cwd.join(".bravebot")).expect("scratch project");
        std::fs::write(
            cwd.join(".bravebot").join("settings.json"),
            r#"{"permissions": {"allow": ["Bash(bash scripts/check.sh)", "Nonsense"]}}"#,
        )
        .expect("write the project layer");
        let settings = bravebot_config::Settings::layered(Some(home), Some(&cwd), None);

        let offered: Vec<String> = proposed_rules(&settings)
            .into_iter()
            .map(|rule| rule.rule)
            .collect();
        assert_eq!(
            offered,
            ["Bash(bash scripts/check.sh)"],
            "the entries this session offers are not the ones that are rules"
        );
    }

    /// PERM-15: the person who was asked about the working directory is asked about the `allow` rules
    /// a checkout proposed too, because each answers an approval prompt they would otherwise see and
    /// the file is the easiest thing in a checkout to write to.
    #[test]
    fn a_person_asked_about_the_workspace_is_asked_about_the_rules_a_checkout_proposed() {
        let rules = proposed(&["Bash(bash scripts/check.sh)", "Edit(src/**)"]);

        assert_eq!(
            granting_proposed_rules(Whence::Asked, &rules, &[]),
            Granting::Asking {
                already: Vec::new(),
                asking: rules,
            }
        );
    }

    /// PERM-15: and not twice about the same rule. A rule this workspace's record already holds was
    /// answered in an earlier session here, so it is in force without a box: a question already
    /// answered trains the habit of answering without reading, which is the whole of what asking is
    /// worth.
    #[test]
    fn a_rule_granted_in_an_earlier_session_is_in_force_rather_than_asked_about_again() {
        let rules = proposed(&["Bash(bash scripts/check.sh)", "Edit(src/**)"]);
        let already = proposed(&["Bash(bash scripts/check.sh)"]);

        assert_eq!(
            granting_proposed_rules(Whence::Asked, &rules, &already),
            Granting::Asking {
                already,
                asking: proposed(&["Edit(src/**)"]),
            }
        );
    }

    /// PERM-15: two layers may write one rule, and a grant is for the file that proposed it, so the
    /// one that was granted is in force and the other is still asked about.
    ///
    /// The case that decides how a dropped rule is reported. What is in force and what was proposed
    /// are compared to work out which entries to name, and comparing the two on the rule text alone
    /// would find this rule in both lists and report the ungranted copy as neither granted nor
    /// dropped: an entry that answers no prompt, with nothing said about it.
    #[test]
    fn one_rule_text_in_two_files_is_granted_for_the_file_it_was_granted_in() {
        let project = bravebot_agent::granted::Proposed::new(
            std::path::Path::new("/work/.bravebot/settings.json"),
            "Bash(bash scripts/check.sh)",
        );
        let local = bravebot_agent::granted::Proposed::new(
            std::path::Path::new("/work/.bravebot/settings.local.json"),
            "Bash(bash scripts/check.sh)",
        );
        let proposed = vec![project.clone(), local.clone()];

        assert_eq!(
            granting_proposed_rules(Whence::Asked, &proposed, std::slice::from_ref(&project)),
            Granting::Asking {
                already: vec![project],
                asking: vec![local],
            }
        );
    }

    /// PERM-15: the mode that answers every permission question answers this one too, on the terms it
    /// answers the workspace's. It approves every write, every run and vouching for every file the
    /// planner reads, so stopping at a modal box about a rule that suppresses one of those prompts
    /// would be the one thing it did not answer.
    #[test]
    fn bypassing_grants_the_rules_a_checkout_proposed_without_asking() {
        let rules = proposed(&["Bash(bash scripts/check.sh)"]);

        assert_eq!(
            granting_proposed_rules(Whence::Unasked, &rules, &[]),
            Granting::Granting(rules)
        );
    }

    /// PERM-15: a session resumed with the map its own user left puts no question, and what holds is
    /// what that workspace's record already says. A rule the checkout has added since is one nobody
    /// granted, so granting it here would answer an approval prompt on behalf of somebody who was
    /// never asked, out of a file that may have been edited since they answered.
    #[test]
    fn a_resume_grants_only_the_rules_the_record_already_held() {
        let rules = proposed(&["Bash(bash scripts/check.sh)", "Edit(src/**)"]);
        let already = proposed(&["Bash(bash scripts/check.sh)"]);

        assert_eq!(
            granting_proposed_rules(Whence::Resumed, &rules, &already),
            Granting::Granting(already)
        );
    }

    /// The directory those sessions ran in, which is the one their rules are read under.
    fn here() -> &'static std::path::Path {
        std::path::Path::new("/tmp/x")
    }

    /// A session that ran in this directory and vouched for it, which is what an earlier answer
    /// of yes leaves behind in the directory's list of sessions.
    fn a_record_that_answered_yes_here() -> Box<bravebot_session::sessions::Record> {
        Box::new(
            serde_json::from_value(serde_json::json!({
                "id": "1-2",
                "directory": "/tmp/x",
                "title": "an earlier session here",
                "started": 1,
                "updated": 1,
                "trust": [{"path": ".", "integrity": "trusted"}],
                "conversation": {"messages": [], "context": "trusted"},
            }))
            .expect("a record"),
        )
    }

    /// The opening map comes from how this session was started and from a yes that was kept, and
    /// from nowhere else. A fresh start brings no record, so without a kept yes the question is put:
    /// reading back what an earlier session here was left holding, a no included, would grant
    /// standing permission over the tree on behalf of a user nobody asked. `/clear` begins a
    /// session too, and reaches this with the same `Beginning::New`.
    #[test]
    fn a_fresh_session_is_asked_rather_than_inheriting_a_map() {
        use bravebot_agent::PermissionMode;

        assert!(
            matches!(
                opening_for(
                    beginning_of(&Start::Fresh, here()),
                    PermissionMode::Ask,
                    here(),
                    || None,
                ),
                Opening::Ask
            ),
            "a session started fresh took an answer its own user never gave",
        );
    }

    /// A yes an earlier session kept settles a fresh one, and `/clear` too, and the
    /// map it settles is the one `y` would have given: the tree trusted, nothing more.
    #[test]
    fn a_remembered_answer_settles_a_fresh_session() {
        use bravebot_agent::PermissionMode;

        let kept = bravebot_agent::trusted::Kept {
            session: "1-2".to_string(),
            at: 7,
            root: here().to_path_buf(),
            confined_lines: false,
        };
        for beginning in [Beginning::New, Beginning::Resumed(None)] {
            match opening_for(beginning, PermissionMode::Ask, here(), || {
                Some(kept.clone())
            }) {
                Opening::Remembered(trust, from) => {
                    assert_eq!(from, kept, "the session named another answer");
                    assert!(trust.is_trusted("."));
                    assert!(trust.is_trusted("src/main.rs"), "the rule covers the tree");
                    assert!(
                        !trust.is_trusted("/etc/passwd"),
                        "a remembered answer reached outside the directory",
                    );
                }
                opening => panic!("a remembered answer was not honoured: {opening:?}"),
            }
        }
    }

    /// RUN-5. A session a kept answer settles holds the map that answer's entry describes: held
    /// lines run unasked only where the entry says the question did, and never below another root.
    #[test]
    fn a_remembered_answer_allows_confined_lines_only_where_its_entry_says_so() {
        use bravebot_agent::PermissionMode;

        let kept = |root: &std::path::Path, confined_lines| bravebot_agent::trusted::Kept {
            session: "1-2".to_string(),
            at: 7,
            root: root.to_path_buf(),
            confined_lines,
        };
        for (root, confined_lines, allowed) in [
            (here(), true, true),
            (here(), false, false),
            (std::path::Path::new("/tmp"), true, false),
        ] {
            let entry = kept(root, confined_lines);
            match opening_for(Beginning::New, PermissionMode::Ask, here(), || {
                Some(entry.clone())
            }) {
                Opening::Remembered(trust, _) => assert_eq!(
                    trust.allows_confined_lines(),
                    allowed,
                    "root {root:?}, confined_lines {confined_lines}"
                ),
                opening => panic!("a remembered answer was not honoured: {opening:?}"),
            }
        }
    }

    /// A directory to answer about and the record a yes there is kept in, under a state directory
    /// of its own. `None` on a filesystem that cannot say when a directory was made, which keeps
    /// nothing.
    fn a_record_to_keep_in(
        name: &str,
    ) -> Option<(
        std::path::PathBuf,
        std::path::PathBuf,
        (
            bravebot_agent::trusted::Store,
            bravebot_agent::trusted::Identity,
        ),
    )> {
        let scratch = crate::testutil::scratch_dir(name);
        let _ = std::fs::remove_dir_all(&scratch);
        let home = scratch.join("home");
        let root = scratch.join("work");
        std::fs::create_dir_all(&root).expect("create");
        let identity = bravebot_agent::trusted::Identity::of(&root)?;
        let store = bravebot_agent::trusted::Store::new(&home, &root);
        Some((home, root, (store, identity)))
    }

    /// TRUST-23: a yes is the answer that is kept. The answer goes through the function
    /// `opening_trust` calls once the question is closed, and the next session started in the
    /// directory finds what it wrote, is not asked, and opens with the tree trusted. The regression
    /// it rejects is the call being dropped, or a yes not reaching the record.
    #[test]
    fn a_yes_is_kept_and_the_next_session_there_is_not_asked() {
        use crate::trust_prompt::Answer;
        use bravebot_agent::PermissionMode;

        let Some((home, root, record)) = a_record_to_keep_in("bravebot-app-yes-kept") else {
            return;
        };

        assert_eq!(
            keep_the_answer(Answer::Trust, Some(&record), "1-2", &root),
            Some(t!(session_trust_kept, directory = root.display())),
            "a yes with a record did not say it was kept"
        );

        let kept = bravebot_agent::trusted::honoured(Some(&home), None, &root)
            .expect("the next session here would be asked after a yes")
            .kept;
        match opening_for(Beginning::New, PermissionMode::Ask, &root, || {
            Some(kept.clone())
        }) {
            Opening::Remembered(trust, _) => {
                assert!(
                    trust.is_trusted("src/main.rs"),
                    "the kept yes covers the tree"
                );
            }
            opening => panic!("a kept yes did not settle the next session: {opening:?}"),
        }
        let _ = std::fs::remove_dir_all(root.parent().expect("scratch"));
    }

    /// TRUST-23: a no is never kept. The next session started there asks, since a no grants nothing
    /// and asking again is how a person changes their mind. Each answer the question can give goes
    /// through the function `opening_trust` calls, so the reading of which of them is a yes is the
    /// code's and not the test's: declining and leaving are both a no. The regression it rejects is
    /// either of them reaching the record.
    #[test]
    fn a_no_is_not_kept_and_the_next_session_there_is_asked() {
        use crate::trust_prompt::Answer;
        use bravebot_agent::PermissionMode;

        let Some((home, root, record)) = a_record_to_keep_in("bravebot-app-no-not-kept") else {
            return;
        };

        for answer in [Answer::Decline, Answer::Leave] {
            assert_eq!(
                keep_the_answer(answer, Some(&record), "1-2", &root),
                None,
                "{answer:?} was kept"
            );
        }

        assert!(!record.0.path().exists(), "a record was written for no yes");
        assert!(matches!(
            opening_for(Beginning::New, PermissionMode::Ask, &root, || {
                bravebot_agent::trusted::honoured(Some(&home), None, &root).map(|h| h.kept)
            }),
            Opening::Ask
        ));
        let _ = std::fs::remove_dir_all(root.parent().expect("scratch"));
    }

    /// TRUST-23: a yes whose record cannot be written says it was not kept and names the file, so
    /// the person knows the next session asks; a yes with no record has nothing to say, because the
    /// question already said the answer cannot be kept. The state directory here is a file, which
    /// nothing can be created inside.
    #[test]
    fn a_yes_the_record_refuses_says_so_and_a_yes_with_no_record_says_nothing() {
        use crate::trust_prompt::Answer;

        let Some((_, root, _)) = a_record_to_keep_in("bravebot-app-yes-refused") else {
            return;
        };
        let identity = bravebot_agent::trusted::Identity::of(&root).expect("a directory");
        let blocked = root.parent().expect("scratch").join("not-a-directory");
        std::fs::write(&blocked, b"").expect("a file in the way");
        let record = (
            bravebot_agent::trusted::Store::new(&blocked, &root),
            identity,
        );

        assert_eq!(
            keep_the_answer(Answer::Trust, Some(&record), "1-2", &root),
            Some(t!(
                session_trust_not_kept,
                directory = root.display(),
                path = record.0.path().display()
            ))
        );
        assert_eq!(keep_the_answer(Answer::Trust, None, "1-2", &root), None);
        let _ = std::fs::remove_dir_all(root.parent().expect("scratch"));
    }

    /// Bypassing every permission answers before the kept record is read, so the session says the
    /// flag answered, which is what is in force, and never touches the record (MODE-4).
    #[test]
    fn bypass_answers_before_a_remembered_answer_is_read() {
        use bravebot_agent::PermissionMode;

        match opening_for(
            beginning_of(&Start::Fresh, here()),
            PermissionMode::Bypass,
            here(),
            || panic!("bypass read the kept answer"),
        ) {
            Opening::Settled(_, Whence::Unasked) => {}
            opening => panic!("bypass did not answer: {opening:?}"),
        }
    }

    /// `/forget-trust` takes the kept answer back, so the next session started there asks, and
    /// says so; this session keeps the map it already has.
    #[test]
    fn forgetting_trust_makes_the_next_session_here_ask() {
        use bravebot_agent::trusted::{Identity, Store};

        let scratch = crate::testutil::scratch_dir("bravebot-app-forget-trust");
        let _ = std::fs::remove_dir_all(&scratch);
        let home = scratch.join("home");
        let root = scratch.join("work");
        std::fs::create_dir_all(&root).expect("create");
        let Some(identity) = Identity::of(&root) else {
            // A filesystem with no birth time keeps nothing, which a sibling test covers.
            return;
        };
        let store = Store::new(&home, &root);
        assert!(
            store.keep(&identity, "1-2", 7, false),
            "the answer was not kept"
        );

        let said = forget_trust(Some(&home), &root);

        assert_eq!(
            store.kept(&identity),
            None,
            "the answer outlived /forget-trust"
        );
        assert_eq!(
            said,
            t!(session_trust_forgotten, directory = root.display()),
            "the line did not say the next session will ask",
        );
        let _ = std::fs::remove_dir_all(&scratch);
    }

    /// `/forget-trust` in a directory below a remembered worktree root withdraws the root's answer,
    /// which is the one settling this directory, and names the root, so the next session in either
    /// asks.
    #[test]
    fn forgetting_trust_below_a_remembered_root_takes_the_roots_answer_back() {
        use bravebot_agent::trusted::{Identity, Store};

        let scratch = crate::testutil::scratch_dir("bravebot-app-forget-root-trust");
        let _ = std::fs::remove_dir_all(&scratch);
        let home = scratch.join("home");
        let root = scratch.join("repo");
        let package = root.join("packages/api");
        std::fs::create_dir_all(root.join(".git")).expect("create");
        std::fs::create_dir_all(&package).expect("create");
        let Some(identity) = Identity::of(&root) else {
            return;
        };
        let store = Store::new(&home, &root);
        assert!(
            store.keep(&identity, "1-2", 7, false),
            "the answer was not kept"
        );

        let said = forget_trust(Some(&home), &package);

        assert_eq!(store.kept(&identity), None, "the root's answer survived");
        assert_eq!(
            said,
            t!(
                session_trust_forgotten_root,
                directory = package.display(),
                root = root.canonicalize().expect("resolved").display()
            ),
            "the line did not name the root"
        );
        let _ = std::fs::remove_dir_all(&scratch);
    }

    /// `/forget-trust` withdraws the answers kept about the working directory and about the root of
    /// the git worktree around it. A directory opened or closed, one that holds the working
    /// directory included, writes neither answer and leaves the root where it was, so the line says
    /// the same and withdraws the same whether it is carried out before the directory is opened,
    /// while it is open or after it is closed. That is what lets `/forget-trust` typed behind a
    /// waiting `/add-dir` be carried out as it is typed. The regression it rejects is `/add-dir`
    /// making a `.git` entry nearer the working directory, which names another root and leaves the
    /// answer kept about the first.
    #[test]
    fn opening_or_closing_a_directory_does_not_change_what_forgetting_trust_withdraws() {
        use bravebot_agent::trusted::{Identity, Store};

        for forgotten_before in 0..=2 {
            let scratch = crate::testutil::scratch_dir(&format!(
                "bravebot-app-forget-trust-around-add-dir-{forgotten_before}"
            ));
            let _ = std::fs::remove_dir_all(&scratch);
            let home = scratch.join("home");
            let root = scratch.join("repo");
            let package = root.join("packages/api");
            let notes = scratch.join("notes");
            for directory in [root.join(".git"), package.clone(), notes.clone()] {
                std::fs::create_dir_all(directory).expect("create");
            }
            let Some(identity) = Identity::of(&root) else {
                let _ = std::fs::remove_dir_all(&scratch);
                return;
            };
            let store = Store::new(&home, &root);
            assert!(
                store.keep(&identity, "1-2", 7, false),
                "the answer was not kept"
            );
            let mut workspace = Workspace::new(&package).expect("workspace");
            let working = workspace.root().to_path_buf();
            let mut trust = TrustStore::new(&working);
            let mut session = Session::new("none");
            let named = [&notes, &root].map(|directory| directory.display().to_string());

            let mut said = None;
            for step in 0..=2 {
                if step == forgotten_before {
                    said = Some(forget_trust(Some(&home), workspace.root()));
                }
                for directory in &named {
                    match step {
                        0 => add_directory(&mut session, &mut workspace, &mut trust, directory),
                        1 => assert!(
                            close_directory(&mut session, &mut workspace, &mut trust, directory),
                            "{directory} was not closed"
                        ),
                        _ => {}
                    }
                }
            }

            assert_eq!(
                workspace.root(),
                working,
                "the working directory moved when forgotten before step {forgotten_before}"
            );
            assert_eq!(
                said,
                Some(t!(
                    session_trust_forgotten_root,
                    directory = working.display(),
                    root = root.canonicalize().expect("resolved").display()
                )),
                "forgotten before step {forgotten_before}"
            );
            assert_eq!(
                store.kept(&identity),
                None,
                "the root's answer survived when forgotten before step {forgotten_before}"
            );
            let _ = std::fs::remove_dir_all(&scratch);
        }
    }

    /// `/forget-trust` withdraws the answers kept about the working directory and about the root of
    /// the git worktree around it. `/branch` copies the record and goes on in the copy: it starts no
    /// program, leaves the working directory and the root where they were, and neither reads nor
    /// writes the answer, so the line says the same and withdraws the same whether it is carried out
    /// before the branch or after it. That is what lets `/forget-trust` typed behind a waiting
    /// `/branch` be carried out as it is typed. The regression it rejects is `/branch` taking the
    /// kept answer back itself, or moving the session to another root, which leaves the answer
    /// withdrawn by one order and not the other.
    #[test]
    fn branching_the_session_does_not_change_what_forgetting_trust_withdraws() {
        use bravebot_agent::trusted::{Identity, Store};

        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        for branched_first in [false, true] {
            let repo = crate::test_profile::project(&format!(
                "bravebot-app-forget-trust-around-branch-{branched_first}"
            ));
            let package = repo.join("packages/api");
            for directory in [repo.join(".git"), package.clone()] {
                std::fs::create_dir_all(directory).expect("create");
            }
            let Some(identity) = Identity::of(&repo) else {
                return;
            };
            let home = bravebot_agent::home::directory().expect("a state directory");
            let store = Store::new(&home, &repo);
            assert!(
                store.keep(&identity, "1-2", 7, false),
                "the answer was not kept"
            );
            let (workspace, mut session, mut stored, conversation, mut answers) =
                a_session_to_branch(&package);
            let working = workspace.root().to_path_buf();
            let original = stored.id().to_string();
            let forget = || forget_trust(Some(&home), workspace.root());
            let branch = |session: &mut Session, stored: &mut _, answers: &mut Answers| {
                assert!(
                    branch_session(session, stored, &conversation, answers, &workspace, &[], ""),
                    "the session was not branched"
                );
            };

            let said = if branched_first {
                branch(&mut session, &mut stored, &mut answers);
                assert!(
                    store.kept(&identity).is_some(),
                    "branching took the kept answer back"
                );
                forget()
            } else {
                let said = forget();
                branch(&mut session, &mut stored, &mut answers);
                said
            };

            assert_ne!(stored.id(), original, "the session stayed on the original");
            assert_eq!(
                workspace.root(),
                working,
                "the working directory moved when branched first: {branched_first}"
            );
            assert_eq!(
                said,
                t!(
                    session_trust_forgotten_root,
                    directory = working.display(),
                    root = repo.canonicalize().expect("resolved").display()
                ),
                "branched first: {branched_first}"
            );
            assert_eq!(
                store.kept(&identity),
                None,
                "the root's answer survived when branched first: {branched_first}"
            );
        }
    }

    /// With nothing kept there is nothing to take back, and the line says that rather than
    /// claiming to have forgotten something.
    #[test]
    fn forgetting_trust_where_nothing_is_kept_says_so() {
        let scratch = crate::testutil::scratch_dir("bravebot-app-forget-nothing");
        let _ = std::fs::remove_dir_all(&scratch);
        let root = scratch.join("work");
        std::fs::create_dir_all(&root).expect("create");
        let nothing = t!(session_trust_nothing_to_forget, directory = root.display());

        assert_eq!(forget_trust(Some(&scratch.join("home")), &root), nothing);
        assert_eq!(forget_trust(None, &root), nothing, "no state directory");
        let _ = std::fs::remove_dir_all(&scratch);
    }

    /// A resume is not an exception to that: the answer it honours is the one its own user gave,
    /// and it comes with the rules that session's writes recorded, which is what stops a resumed
    /// turn reading back a file an earlier turn of the same session poisoned.
    #[test]
    fn a_resume_starts_with_the_map_its_own_record_kept() {
        use bravebot_agent::PermissionMode;

        let record = a_record_that_answered_yes_here();
        match opening_for(
            beginning_of(&Start::Resuming(record), here()),
            PermissionMode::Ask,
            here(),
            || panic!("a resume read the kept answer over its own record's map"),
        ) {
            Opening::Settled(trust, Whence::Resumed) => {
                assert!(trust.is_trusted("."));
                assert!(trust.is_trusted("src/main.rs"), "the rule covers the tree");
            }
            settled => panic!("a resume did not take its own record's map: {settled:?}"),
        }
    }

    /// Nothing recorded is not the same as nothing trusted, so a record from before maps were
    /// kept is asked about rather than resumed into a map that vouches for nothing.
    #[test]
    fn a_record_from_before_maps_were_kept_is_asked_about() {
        use bravebot_agent::PermissionMode;

        let mut record = a_record_that_answered_yes_here();
        record.trust = None;

        assert!(
            matches!(
                opening_for(
                    beginning_of(&Start::Resuming(record), here()),
                    PermissionMode::Ask,
                    here(),
                    || None,
                ),
                Opening::Ask
            ),
            "a record that answered nothing was resumed as an answer",
        );
    }

    /// Bypassing answers the question rather than putting it, but a resume is still the more
    /// specific record: the question is not being put in either case, so the mode has nothing to
    /// answer, and a no given inside a trusted tree must survive being picked up again.
    #[test]
    fn a_resume_keeps_its_own_map_even_where_the_mode_would_answer() {
        use bravebot_agent::PermissionMode;

        let mut record = a_record_that_answered_yes_here();
        record.trust = Some(vec![
            bravebot_session::sessions::StoredRule {
                path: ".".to_string(),
                integrity: "trusted".to_string(),
            },
            bravebot_session::sessions::StoredRule {
                path: "vendor".to_string(),
                integrity: "untrusted".to_string(),
            },
        ]);

        match opening_for(
            beginning_of(&Start::Resuming(record), here()),
            PermissionMode::Bypass,
            here(),
            || panic!("a resume read the kept answer over its own record's map"),
        ) {
            Opening::Settled(trust, Whence::Resumed) => assert!(
                !trust.is_trusted("vendor/lib.js"),
                "the mode's own answer replaced the one the record kept",
            ),
            settled => panic!("a resume was answered by the mode instead: {settled:?}"),
        }
    }

    /// MODE-4, TRUST-6. A session that had bypass on at any point writes a record whose map and
    /// opened directories a resume without the flag does not take back, so the startup question
    /// is put; one that never had it keeps its map. The faults it rejects: the record not saying
    /// so, and a resume that reads the map back as the person's answer.
    #[test]
    fn a_resume_without_the_flag_asks_where_bypass_answered_for_the_record() {
        use bravebot_agent::PermissionMode;
        use bravebot_session::sessions;

        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let root = crate::test_profile::project("bravebot-app-bypass-record");
        std::fs::create_dir_all(&root).expect("create");
        let workspace = Workspace::new(&root).expect("a workspace");
        let written = |mode_during_the_sitting: &[PermissionMode]| {
            let session = Session::new("none");
            for mode in mode_during_the_sitting {
                session.live_permission_mode().set(*mode);
            }
            let trust = crate::trust_prompt::answered_by(PermissionMode::Bypass, &root)
                .expect("bypass answers the question");
            let mut stored =
                sessions::Handle::begin(&root, sessions::Front::Terminal, bravebot_stamp::BUILD);
            with_standing(
                &session,
                &Conversation::new(),
                &trust,
                &TrustedPrograms::new(),
                &workspace,
                |standing| stored.save("a session", standing),
            );
            sessions::load(&root, stored.id()).expect("the record")
        };

        // Left again before the record is written: the answers it holds were still the mode's.
        for during in [
            &[PermissionMode::Bypass][..],
            &[PermissionMode::Bypass, PermissionMode::Ask],
        ] {
            let record = written(during);
            assert!(record.trust_answered_by_mode, "{during:?}");
            assert!(
                matches!(
                    opening_for(
                        beginning_of(&Start::Resuming(Box::new(record.clone())), &root),
                        PermissionMode::Ask,
                        &root,
                        || None,
                    ),
                    Opening::Ask
                ),
                "a resume without the flag took the map bypass wrote, {during:?}",
            );
            assert!(
                matches!(
                    opening_for(
                        beginning_of(&Start::Resuming(Box::new(record)), &root),
                        PermissionMode::Bypass,
                        &root,
                        || None,
                    ),
                    Opening::Settled(_, Whence::Unasked)
                ),
                "a resume given the flag again was asked",
            );
        }

        let record = written(&[PermissionMode::AcceptEdits]);
        assert!(!record.trust_answered_by_mode);
        assert!(
            matches!(
                opening_for(
                    beginning_of(&Start::Resuming(Box::new(record)), &root),
                    PermissionMode::Ask,
                    &root,
                    || None,
                ),
                Opening::Settled(_, Whence::Resumed)
            ),
            "a map a person answered was not taken back on a resume",
        );
    }

    /// A rewind point read off the live session lands inside the turn it undoes: by the time the
    /// loop has a prompt in hand it is on the transcript and counted as a turn, so rewinding to
    /// such a point would leave the prompt in the scrollback and number the next turn one too high.
    #[test]
    fn a_rewind_point_excludes_the_turn_it_undoes() {
        let root = crate::testutil::scratch_dir("bravebot-app-rewind-point");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).expect("create");

        let mut session = Session::new("none");
        let conversation = Conversation::new();
        let trust = TrustStore::new("/work");
        let programs = TrustedPrograms::new();
        let stored = bravebot_session::sessions::Handle::begin(
            &root,
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        );

        type_line(&mut session, "delete the tests");
        session.submit().expect("the prompt is sent");

        let first = rewind_point(&session, &conversation, &trust, &programs, &stored);
        assert_eq!(
            first.turns, 0,
            "the first turn rewinds to a session with no turns in it"
        );
        assert_eq!(
            first.transcript_len, 0,
            "the prompt is the turn's, and goes back with it"
        );
        assert!(
            !first.was_wrote,
            "nothing was written before the first turn"
        );

        session.complete("nothing was deleted", Vec::new(), 10);
        type_line(&mut session, "delete the docs");
        session.submit().expect("the prompt is sent");

        let second = rewind_point(&session, &conversation, &trust, &programs, &stored);
        assert_eq!(second.turns, 1, "the turn that finished stays");
        assert_eq!(
            second.transcript_len, 2,
            "the finished turn's prompt and reply stay"
        );

        let _ = std::fs::remove_dir_all(&root);
    }

    /// A cache figure measures one request a process sent, so a session resumed in another
    /// reports none until a turn has run in it: a figure a rewind point carried across the resume
    /// would arrive on the panel at the first `/undo`, beside a cost this session has not paid.
    /// A rewind inside the process that measured the figure still puts it back, which is the half
    /// of BACKEND-31 that keeping none in the record must not cost.
    #[test]
    fn a_resumed_rewind_reports_no_cache_figure_while_a_live_one_puts_it_back() {
        use bravebot_aichat::protocol::{Cached, Message};
        use bravebot_session::sessions::{self, Standing};

        fn save(
            stored: &mut sessions::Handle,
            session: &Session,
            conversation: &Conversation,
            root: &std::path::Path,
        ) {
            stored.save(
                "cache",
                Standing {
                    conversation: &conversation.snapshot(),
                    history: Some(session.turn_history()),
                    turns: session.turns,
                    tokens: session.tokens,
                    split: Default::default(),
                    spend: session.spend_by_turn(),
                    timing: session.timing_by_turn(),
                    model: None,
                    todos: &session.todos_by_turn(),
                    asides: &[],
                    trust: &TrustStore::new(root),
                    programs: &TrustedPrograms::new(),
                    directories: &[],
                    manifest: None,
                    rewind: session.rewind.points(),
                    checkouts: &[],
                    touched: None,
                    answered_by_mode: false,
                },
            );
        }

        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let root = crate::test_profile::project("bravebot-app-rewind-cache");
        std::fs::create_dir_all(&root).expect("create");
        let workspace = Workspace::new(&root).expect("a workspace");
        let mut trust = TrustStore::new(&root);
        let mut programs = TrustedPrograms::new();
        let mut stored =
            sessions::Handle::begin(&root, sessions::Front::Terminal, bravebot_stamp::BUILD);
        let mut session = Session::new("none");
        let mut conversation = Conversation::new();

        // Two turns whose cache figures differ, so a figure put back can be told from the one it
        // replaced as well as from nothing at all.
        let figures = [
            Cached {
                read_tokens: 400,
                written_tokens: 50,
            },
            Cached {
                read_tokens: 900,
                written_tokens: 100,
            },
        ];
        for (index, cached) in figures.into_iter().enumerate() {
            let prompt = format!("say {index}");
            let start = conversation.recounted().len();
            type_line(&mut session, &prompt);
            session.submit().expect("the prompt is sent");
            let point = rewind_point(&session, &conversation, &trust, &programs, &stored);
            session.rewind.open(point, prompt.clone());
            session.prompt_recorded(conversation.recounted().len());
            conversation.push(Message::user(&prompt));
            conversation.push(Message::assistant("said"));
            session.complete("said", vec![], 10);
            // What [`fold_outcome`] does on the path a finished turn takes.
            session.served_from_cache(cached, 1_000);
            session.record_turn(start, &conversation);
            save(&mut stored, &session, &conversation, &root);
        }

        assert_eq!(
            session.cached(),
            Some(figures[1]),
            "the panel is not reporting the last turn's figure"
        );
        assert_eq!(
            session
                .rewind
                .points()
                .last()
                .map(|point| point.snapshot.cached),
            Some(Some(figures[0])),
            "a live point does not hold what the turn before its own read, so a rewind in this \
             process has nothing to put back"
        );
        assert_eq!(
            session
                .rewind
                .points()
                .last()
                .and_then(|point| point.snapshot.cached_prompt_tokens),
            Some(1_000),
            "a live point does not hold the prompt total behind its cache figure"
        );

        // Read before the live rewind, which rewrites it: the resumed half below wants the record
        // as the two turns left it.
        let record = sessions::load(&root, stored.id()).expect("the record");

        // A rewind to a point this process made puts the figure back, the panel reporting what the
        // turn that is now the last one read.
        rewind(
            &mut session,
            &mut conversation,
            &mut trust,
            &mut programs,
            &mut stored,
            &workspace,
            &mut None,
            1,
        );
        assert_eq!(
            session.turns, 1,
            "the live rewind did not go back, so the figure it reports says nothing"
        );
        assert_eq!(
            session.cached(),
            Some(figures[0]),
            "a rewind in the process that measured the figures left the rewound turn's on the panel"
        );
        assert_eq!(
            session.cached_prompt_tokens(),
            Some(1_000),
            "a rewind in the process did not restore the preceding prompt total"
        );

        // A resume brings the points back without the figures, since the record keeps none.
        let conversation = Conversation::restored(record.conversation.clone());
        let mut resumed = Session::new("none");
        resumed.replay(
            &conversation,
            &record.title,
            &sessions::recall(&root, &record),
        );
        resumed.restore_spend(record.tokens, record.spend.clone());
        resumed.restore_rewind_points(record.rewind_points(&root), &conversation);
        let mut conversation = conversation;
        assert_eq!(
            resumed.cached(),
            None,
            "the resumed session reported a cache before any turn had run in it"
        );
        assert_eq!(
            resumed.cached_prompt_tokens(),
            None,
            "the resumed session reported a cache rate denominator"
        );

        rewind(
            &mut resumed,
            &mut conversation,
            &mut trust,
            &mut programs,
            &mut stored,
            &workspace,
            &mut None,
            1,
        );

        assert_eq!(
            resumed.turns, 1,
            "the rewind did not go back, so the figure it reports says nothing"
        );
        assert_eq!(
            resumed.cached(),
            None,
            "a rewind in a resumed session put back a cache figure the previous process measured"
        );
    }

    /// CMD-2: `/branch` is a command only as the whole line or with a name after it, so a question
