    /// PROMPT-1: the lines said about an allow rule a checkout proposed name the rule and the file
    /// as they are spelled, both when it is not granted and when it was granted before, so a rule
    /// that holds a zero-width character, and a file under a directory that ends in a space, are not
    /// read as the ones without them. The record a granted-before line names is spelled too.
    #[test]
    fn the_notes_about_a_checkouts_allow_rule_spell_the_rule_and_the_files() {
        let root = crate::testutil::scratch_dir("bravebot-allow-notes-spelled");
        let _ = std::fs::remove_dir_all(&root);
        let checkout = root.join("proj ");
        checkout_with_settings(
            &checkout,
            r#"{"permissions": {"allow": ["Bash(echo\u200bhi)"]}}"#,
        );
        let state = root.join("state ");
        let sources = RuleSources {
            state: Some(state.clone()),
            named: None,
            started: checkout.clone(),
            managed: bravebot_config::Managed::default(),
        };
        let settings = sources.settings(&checkout);
        let rules_with =
            |ask: fn(&[bravebot_agent::granted::Proposed], &mut String) -> Option<bool>| {
                let mut session = Session::new("none");
                rules_from(
                    &mut session,
                    &settings,
                    &checkout,
                    sources.grants(&checkout).as_ref(),
                    Whence::Asked,
                    "a-session",
                    ask,
                )
                .expect("nobody left");
                session
            };
        let spelled_rule = "\"Bash(echo\\u{200b}hi)\"";
        let spelled_file = format!(
            "\"{}/proj\u{2423}/.bravebot/settings.json\"",
            root.display()
        );

        let ignored = rules_with(|_, _| Some(false));
        let note = notes_of(&ignored).join("\n");
        assert!(
            note.contains(&format!(
                "not granting the allow rule {spelled_rule} from {spelled_file}"
            )),
            "{note}"
        );
        assert!(!note.contains('\u{200b}'), "{note}");

        rules_with(|_, _| Some(true));
        let before = rules_with(never_asked);
        let note = notes_of(&before).join("\n");
        let spelled_record = format!("\"{}/state\u{2423}/", root.display());
        assert!(
            note.contains(&format!("granting the allow rule {spelled_rule} from {spelled_file}, which you allowed this project before")),
            "{note}"
        );
        assert!(note.contains(&spelled_record), "{note}");
        assert!(
            !note.contains('\u{200b}') && !note.contains("proj /"),
            "{note}"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// Both halves of what `/cd` does, together: the working directory moves, and the directory
    /// moved to is vouched for, which is what a relative path means and what decides a write there.
    #[test]
    fn changing_directory_moves_the_workspace_and_vouches_for_where_it_moved() {
        let root = crate::testutil::scratch_dir("bravebot-cd-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new("/work");
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );

        let canonical = other.canonicalize().expect("canonical");
        assert_eq!(workspace.root(), canonical);
        assert!(
            answers.trust.is_trusted("."),
            "the directory moved to was not vouched for"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// A watch is armed on a workspace-relative path, so moving the working directory closes the
    /// directory the answer that allowed it was about. The watch has to end with the move and say
    /// so, for the reason the servers are dropped and the directories closed: nothing here is
    /// still the thing anybody agreed to. With the move rather than at the next look, which is up
    /// to five seconds away and long enough for a fire to go out in.
    ///
    /// The directory moved to holds a `notes.md` of its own, of another size, which is what the
    /// watch reported movement on while a look was resolved against whatever the working
    /// directory happened to be. So a wrong answer here is a fire, on a file nothing in the
    /// session wrote and nobody armed a watch on.
    #[test]
    fn changing_directory_ends_a_watch_armed_in_the_one_left_behind() {
        let root = crate::testutil::scratch_dir("bravebot-cd-watch-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");
        std::fs::write(project.join("notes.md"), "the watched one").expect("scratch");
        std::fs::write(other.join("notes.md"), "a different file, of another size")
            .expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        let under = workspace.root();
        session.arm_watch("notes.md", under, workspace.look("notes.md", under));
        assert_eq!(session.watches().len(), 1, "the watch was not armed");

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );

        assert!(
            session.watches().is_empty(),
            "the watch outlived the directory it was armed in"
        );
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(watch_out_of_reach, number = 1)),
            "the watch ended without saying so"
        );

        // And nothing is left to fire on the next pass, which is where the fire about the other
        // directory's file went out from.
        let later = Instant::now() + Duration::from_secs(6);
        assert!(
            session
                .watch_fired(later, |path, under| workspace.look(path, under))
                .is_none(),
            "a fire went out about the file in the directory the session moved to"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// LSP-5 and LSP-8: a server is approved for one tree and indexes that tree, so the working
    /// directory moving leaves it behind.
    ///
    /// Kept across the move it would answer questions about the new directory out of the old one's
    /// index, and the paths it opens would be resolved against a root the session has left. Nobody
    /// approved a server reading that directory from here.
    #[test]
    fn changing_directory_stops_the_servers_started_in_the_old_one() {
        let root = crate::testutil::scratch_dir("bravebot-cd-servers-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        // Nothing is started by building the set, which is LSP-8: a server comes up on the first
        // question that needs one. What is being asserted is who holds the set afterwards.
        answers.servers = Some(LanguageServers::new(workspace.root().to_path_buf(), None));

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );

        assert!(
            answers.servers.is_none(),
            "the servers of the directory left behind are still the session's"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// The map goes with the session, so it has to keep saying what it said about the same files
    /// once the working directory has moved. A yes given for the directory left behind must not
    /// become a yes for the one arrived at, which is what carrying it across unchanged would do.
    #[test]
    fn changing_directory_leaves_the_previous_answer_where_it_was_given() {
        let root = crate::testutil::scratch_dir("bravebot-cd-rules-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(project.join("vendor")).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        answers.trust.trust(".");
        answers.trust.distrust("vendor");

        let left = workspace.root().to_path_buf();
        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );

        assert!(
            answers.trust.is_trusted(&left.display().to_string()),
            "the answer given for the directory left behind was forgotten"
        );
        assert!(
            !answers
                .trust
                .is_trusted(&left.join("vendor").display().to_string()),
            "a no given inside the directory left behind was forgotten"
        );
        assert_eq!(
            answers.trust.integrity_of("vendor"),
            Some(bravebot_core::label::Integrity::Trusted),
            "a rule about the old vendor directory decided a path in the new one"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// Moving into a directory keeps the nos given inside it. They are about the same files after
    /// the move as before, and vouching for the directory moved to is not vouching for a subtree
    /// somebody has already refused.
    #[test]
    fn moving_into_a_directory_keeps_the_answers_given_inside_it() {
        let root = crate::testutil::scratch_dir("bravebot-cd-inner-test");
        let project = root.join("project");
        std::fs::create_dir_all(project.join("src/vendor")).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        answers.trust.trust(".");
        answers.trust.distrust("src/vendor");

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                "src",
                never_asked,
            ),
            Changed::Moved
        );

        assert!(
            answers.trust.is_trusted("main.rs"),
            "the directory moved into was not vouched for"
        );
        assert!(
            !answers.trust.is_trusted("vendor/lib.js"),
            "an untrusted subtree became trusted by moving into its parent"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// An answer to show a file that holds a credential is kept under the name the file has from
    /// the root. After a move that name is another file, so the answer must not cover it.
    #[test]
    fn an_answer_to_show_a_file_does_not_cover_the_file_by_that_name_after_moving() {
        let root = crate::testutil::scratch_dir("bravebot-cd-exposed-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(project.join("src")).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);

        answers.exposed.allow(".env");
        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                "src",
                never_asked,
            ),
            Changed::Moved
        );
        assert!(
            !answers.exposed.holds(".env"),
            "a yes for the root's .env covered src/.env after moving into src"
        );

        answers.exposed.allow(".env");
        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );
        assert!(
            !answers.exposed.holds(".env"),
            "a yes for one checkout's .env covered another checkout's"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// A program vouched for names the tree it was vouched in, so a move leaves it covering that
    /// tree and no other, and the run prompts already drawn grant nothing. Both are kept.
    #[test]
    fn moving_keeps_the_programs_vouched_for_and_the_prompts_already_drawn() {
        use bravebot_core::programs::Command;
        let root = crate::testutil::scratch_dir("bravebot-cd-programs-test");
        let project = root.join("project");
        let other = root.join("other");
        std::fs::create_dir_all(&project).expect("scratch");
        std::fs::create_dir_all(&other).expect("scratch");

        let mut workspace = Workspace::new(&project).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new(workspace.root());
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        let make = Command::new("/usr/bin/make", vec!["check".into()], workspace.root());
        answers.programs.trust(make.clone());
        answers.asked_about.record(make.clone());
        let (programs, asked_about) = (answers.programs.clone(), answers.asked_about.clone());

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                other.to_str().expect("utf-8 path"),
                never_asked,
            ),
            Changed::Moved
        );
        assert_eq!(
            answers.programs, programs,
            "moving forgot a program vouched for in the tree left behind"
        );
        assert_eq!(
            answers.asked_about, asked_about,
            "moving forgot a run prompt already drawn"
        );
        assert!(
            !answers.programs.contains(
                &make.program,
                &make.started_as,
                &make.args,
                workspace.root()
            ),
            "a program vouched for in one tree covered the tree moved to"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// A path that names nothing moves nothing, and says so. Half a move would leave the session
    /// vouching for a directory it is not in, or asking again about files it has not left.
    #[test]
    fn a_directory_that_is_not_there_moves_nothing() {
        let root = crate::testutil::scratch_dir("bravebot-cd-missing-test");
        std::fs::create_dir_all(&root).expect("scratch");

        let mut workspace = Workspace::new(&root).expect("workspace");
        let mut session = Session::new("none");
        let trust = TrustStore::new("/work");
        let rules = starting_rules(&mut session, &root.join("state"), workspace.root());
        let mut answers = Answers::opening(trust, TrustedPrograms::new(), rules);
        answers.exposed.allow(".env");
        let before = workspace.root().to_path_buf();

        assert_eq!(
            change_directory(
                &mut session,
                &mut workspace,
                &mut answers,
                "a-session",
                "nowhere",
                never_asked,
            ),
            Changed::Stayed
        );
        assert_eq!(workspace.root(), before);
        assert!(
            answers.trust.is_empty(),
            "a refused move vouched for something"
        );
        assert!(
            answers.exposed.holds(".env"),
            "a refused move dropped an answer about a file the session has not left"
        );

        std::fs::remove_dir_all(&root).ok();
    }

    /// An absolute name is left alone. Joining it onto the workspace would name a path inside the
    /// project that nobody asked for.
    #[test]
    fn an_absolute_directory_in_a_settings_file_is_not_joined_onto_the_workspace() {
        assert_eq!(
            named_directory(std::path::Path::new("/tmp/project"), "/opt/other").ok(),
            Some("/opt/other".to_string())
        );
    }

    /// TRUST-9: the leading `.` and `..` of a relative name are cleaned against the working
    /// directory and nothing after a name is. The working directory is canonical, so a leading `..`
    /// is exact, and `../notes` becomes the spelling an opened directory is recorded under. A `..`
    /// after a name is left alone because the name may be a link, whose target the file system
    /// takes the `..` from.
    ///
    /// The failure this rejects is a name joined as typed, which `/add-dir close` cannot match
    /// against the directory it opened without asking where the name leads, and one cleaned
    /// throughout, which reads `sub/../x` as `x` whether or not `sub` is a link.
    #[cfg(unix)]
    #[test]
    fn a_relative_name_is_cleaned_of_its_leading_dots_and_of_nothing_after_a_name() {
        let root = std::path::Path::new("/w/proj");
        for (typed, resolved) in [
            ("../notes", "/w/notes"),
            ("./../notes", "/w/notes"),
            ("../../x", "/x"),
            ("../../../x", "/x"),
            (".", "/w/proj"),
            ("..", "/w"),
            ("./sub/dir", "/w/proj/sub/dir"),
            ("sub/../x", "/w/proj/sub/../x"),
            ("../project/../notes", "/w/project/../notes"),
            ("/opt/other", "/opt/other"),
        ] {
            assert_eq!(
                named_directory(root, typed).ok(),
                Some(resolved.to_string()),
                "{typed}"
            );
        }
    }

    /// TRUST-9 and PATH-003: a relative name is refused against a working directory whose name is
    /// not text, and is resolved against its lookalike, the name that spells the replacement
    /// character. The string made here becomes a reach grant and a trust key, and a rendering of
    /// the first that substitutes for the bytes it cannot show would name the second. An absolute
    /// name needs no working directory and resolves against either.
    ///
    /// The names are built in memory, since the file system of a Mac cannot hold the first.
    #[cfg(unix)]
    #[test]
    fn a_relative_name_is_refused_against_a_working_directory_whose_name_is_not_text() {
        use std::ffi::OsStr;
        use std::os::unix::ffi::OsStrExt;

        let not_text = std::path::Path::new(OsStr::from_bytes(b"/w/proj-\xff"));
        let lookalike = std::path::Path::new("/w/proj-\u{FFFD}");

        for relative in ["notes", "../notes", ".", "./sub"] {
            match named_directory(not_text, relative) {
                Err(bravebot_agent::WorkspaceError::Invalid { path, reason }) => {
                    assert_eq!(path, relative);
                    assert_eq!(reason, t!(session_directory_root_not_text));
                }
                other => {
                    panic!("{relative} was resolved against a name that is not text: {other:?}")
                }
            }
            assert!(
                named_directory(lookalike, relative).is_ok(),
                "{relative} was refused against a working directory that is text"
            );
        }
        assert_eq!(
            named_directory(lookalike, "../notes").ok(),
            Some("/w/notes".to_string())
        );
        for root in [not_text, lookalike] {
            assert_eq!(
                named_directory(root, "/opt/other").ok(),
                Some("/opt/other".to_string()),
                "an absolute name was refused for {root:?}"
            );
        }
    }

    /// A workspace for the tests below, which need one only because a finished turn takes the
    /// first look at anything it asked to have watched.
    fn workspace_for_test() -> Workspace {
        let root = crate::testutil::scratch_dir("bravebot-fold-outcome-workspace");
        std::fs::create_dir_all(&root).expect("scratch");
        Workspace::new(&root).expect("workspace")
    }

    #[test]
    fn a_failed_turn_measures_context_if_requests_were_sent() {
        let mut session = Session::new("none");
        let sink = Trail::new();
        let fallback = TrustStore::new("/work");
        let fallback_programs = TrustedPrograms::new();
        let asked = Asked {
            name: "test-model".to_string(),
            comparable: true,
        };

        fold_outcome(
            &mut session,
            Err(turn::TurnError::Precommit("failed".to_string())),
            sink,
            Carried {
                trust: fallback,
                programs: fallback_programs,
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
            },
            Occupied {
                budget: 100_000,
                guessed: false,
                last_request_tokens: 45_000,
            },
            asked,
            Line {
                text: "",
                addressed: None,
                offered_a_later_look: false,
            },
            &workspace_for_test(),
        );

        assert_eq!(
            session.occupancy(),
            crate::state::Occupancy::Measured {
                used: 45_000,
                budget: 100_000,
                guessed: false,
            }
        );
        assert_eq!(session.fullness(), Some(45));
    }

    /// A model named by the settings file is one somebody expects to be answered by, exactly as
    /// much as a model picked from `/model` is. Recording the asked-for half only where `/model`
    /// had run left a session on its configured default substituted in silence for its whole life,
    /// while `/status` reported the substitution for the same turn.
    #[test]
    fn a_model_the_configuration_named_is_reported_as_substituted_too() {
        let mut session = Session::new("none");
        assert!(
            session.model().is_none(),
            "the fixture picked a model, so it cannot tell the configured default apart"
        );

        record_the_model_that_answered(
            &mut session,
            Asked {
                name: "claude-3-opus".to_string(),
                comparable: true,
            },
            "claude-3-sonnet",
            true,
        );

        assert_eq!(session.substituted_model(), Some("claude-3-opus"));
        let said = said_in_the_transcript(&session).join("\n");
        assert!(
            said.contains("claude-3-opus") && said.contains("claude-3-sonnet"),
            "the substitution was never said out loud: {said:?}"
        );
    }

    /// Said once when it starts happening rather than on every turn, which a session answered by
    /// the same substitute all afternoon would otherwise be.
    #[test]
    fn a_substitution_that_carries_on_is_said_once() {
        let mut session = Session::new("none");
        for _ in 0..3 {
            record_the_model_that_answered(
                &mut session,
                Asked {
                    name: "claude-3-opus".to_string(),
                    comparable: true,
                },
                "claude-3-sonnet",
                true,
            );
        }

        let said = said_in_the_transcript(&session);
        assert_eq!(
            said.iter()
                .filter(|line| line.contains("claude-3-sonnet"))
                .count(),
            1,
            "said again on a later turn: {said:?}"
        );
    }

    /// The automatic entry asks the server to choose per request, so a concrete name coming back
    /// is that entry working. It is the shipped default, so a session that never touched `/model`
    /// is the ordinary way to reach this, and a warning here would be one on almost every session.
    #[test]
    fn the_configured_automatic_entry_resolving_to_a_model_says_nothing() {
        let mut session = Session::new("none");
        record_the_model_that_answered(
            &mut session,
            Asked {
                name: bravebot_config::DEFAULT_MODEL.to_string(),
                comparable: true,
            },
            "claude-3-haiku",
            true,
        );

        assert_eq!(session.substituted_model(), None);
        assert!(
            said_in_the_transcript(&session).is_empty(),
            "the automatic entry doing its job was reported as a substitution"
        );
    }

    /// PREM-9: a turn that ran under an addressed definition's or a skill's model still says which
    /// tier it ran on and which model answered. Skipping the record left `/status` on "nothing sent
    /// yet", or on an earlier turn's tier, after a turn had spent a credential.
    #[test]
    fn a_turn_on_a_definitions_model_records_its_tier_and_model() {
        let mut session = Session::new("none");
        assert_eq!(session.premium(), None);

        record_what_the_turn_ran_on(
            &mut session,
            Asked {
                name: "claude-3-opus".to_string(),
                comparable: true,
            },
            "claude-3-haiku",
            true,
            false,
        );

        assert_eq!(session.premium(), Some(true));
        assert_eq!(session.served_model(), Some("claude-3-haiku"));
        assert_eq!(
            session.substituted_model(),
            None,
            "the session's model was compared with a turn that never ran on it"
        );
        assert!(said_in_the_transcript(&session).is_empty());
    }

    /// An earlier ordinary turn's tier must not survive a later turn on another model.
    #[test]
    fn a_turn_on_a_skills_model_replaces_an_earlier_turns_tier() {
        let mut session = Session::new("none");
        let asked = || Asked {
            name: "claude-3-opus".to_string(),
            comparable: true,
        };
        record_what_the_turn_ran_on(&mut session, asked(), "claude-3-opus", true, true);
        assert_eq!(session.premium(), Some(true));

        record_what_the_turn_ran_on(&mut session, asked(), "claude-3-haiku", false, false);

        assert_eq!(session.premium(), Some(false));
        assert_eq!(session.served_model(), Some("claude-3-haiku"));
    }

    /// What the session put in front of the person, one entry per line.
    fn said_in_the_transcript(session: &Session) -> Vec<String> {
        session
            .viewed()
            .iter()
            .map(|entry| entry.text.clone())
            .collect()
    }

    /// A record written by another build, on a branch this checkout is not on, that spent tokens
    /// and had `/add-dir` open `extra`.
    fn a_recorded_session_in(
        root: &std::path::Path,
        extra: &std::path::Path,
    ) -> bravebot_session::sessions::Record {
        serde_json::from_value(serde_json::json!({
            "id": "7-8",
            "directory": root.display().to_string(),
            "branch": "a-branch-this-checkout-is-not-on",
            "title": "an earlier session",
            "started": 1,
            "updated": 1,
            "tokens": 4321,
            "build": "an-older-build",
            "directories": [extra.display().to_string()],
            "conversation": {"messages": [], "context": "trusted"},
        }))
        .expect("a record")
    }

    /// Resuming puts back what the record holds and says where it differs from now: the same
    /// session id, the spend, the directory `/add-dir` opened, and a line each for the build and
    /// the branch that are not the ones running. The regressions it rejects are a resumed session
    /// that writes to a new record, forgets its spend or its open directories, and one that
    /// continues someone else's work without saying so.
    #[test]
    fn resuming_a_record_restores_its_accounts_directories_and_says_what_differs() {
        let mut workspace = workspace_for_test();
        let extra = crate::testutil::scratch_dir("bravebot-restore-resumed-extra");
        std::fs::create_dir_all(&extra).expect("scratch");
        let record = a_recorded_session_in(workspace.root(), &extra);
        let mut session = Session::new("none");
        let config = a_config_needing_no_sign_in();

        let (conversation, handle, _programs) =
            restore_resumed(&mut session, &config, &mut workspace, &record)
                .expect("the record is free");

        assert_eq!(
            handle.id(),
            "7-8",
            "the resumed session began a record of its own"
        );
        assert_eq!(session.spent_tokens(), 4321, "the spend was not restored");
        assert_eq!(conversation.last_request_tokens(), 0);
        assert_eq!(
            workspace.added_directories(),
            vec![extra.canonicalize().expect("canonical")],
            "the directory `/add-dir` opened was not opened again"
        );
        let said = said_in_the_transcript(&session).join("\n");
        assert!(
            said.contains("resumed session: an earlier session"),
            "{said}"
        );
        assert!(
            said.contains("that session ran on bravebot an-older-build"),
            "a record from another build resumed without saying so: {said}"
        );
        assert!(
            said.contains("this session ran on a-branch-this-checkout-is-not-on"),
            "a record from another branch resumed without saying so: {said}"
        );
        let _ = std::fs::remove_dir_all(&extra);
    }

    /// A record on the build and branch now running says nothing about either, so the notes above
    /// are about a difference and not about every resume.
    #[test]
    fn resuming_a_record_from_this_build_adds_no_caveat() {
        let mut workspace = workspace_for_test();
        let extra = crate::testutil::scratch_dir("bravebot-restore-resumed-same");
        std::fs::create_dir_all(&extra).expect("scratch");
        let mut record = a_recorded_session_in(workspace.root(), &extra);
        record.build = Some(bravebot_stamp::BUILD.to_string());
        record.branch = bravebot_session::sessions::branch_of(workspace.root());
        let mut session = Session::new("none");
        let config = a_config_needing_no_sign_in();

        restore_resumed(&mut session, &config, &mut workspace, &record)
            .expect("the record is free");

        let said = said_in_the_transcript(&session).join("\n");
        assert!(!said.contains("that session ran on bravebot"), "{said}");
        assert!(!said.contains("this session ran on"), "{said}");
        let _ = std::fs::remove_dir_all(&extra);
    }

    /// A level named on the command line outranks what the settings say and is the one in force,
    /// and a limit in the settings is the one the next turn is held to.
    #[test]
    fn adopting_settings_puts_the_asked_level_and_the_limit_in_force() {
        use bravebot_aichat::protocol::Effort;
        let settings = bravebot_config::Settings::parse(r#"{"limit": "250k"}"#);
        let mut asked = Session::new("none");
        let mut unasked = Session::new("none");

        adopt_settings(&mut asked, &settings, Some(Effort::Low));
        adopt_settings(&mut unasked, &settings, None);

        assert_eq!(asked.effort(), Some(Effort::Low));
        assert_ne!(
            unasked.effort(),
            Some(Effort::Low),
            "the level was set without being asked for"
        );
        assert!(
            asked.spend_limit().limit().is_some(),
            "the limit in the settings was not adopted"
        );
    }

    /// The idle time the settings file names reaches the recap through `adopt_settings`, and is
    /// not the built-in five minutes.
    #[test]
    fn adopting_settings_puts_the_recap_idle_time_in_force() {
        use std::time::{Duration, Instant};
        let settings = bravebot_config::Settings::parse(r#"{"awaySummaryIdleSeconds": 90}"#);
        let mut session = Session::new("none");
        adopt_settings(&mut session, &settings, None);

        let start = Instant::now();
        session.away.turn_done(start);
        session.away.focus(false);
        let turns = crate::away::FEWEST_TURNS;
        assert!(
            !session.away.due(start + Duration::from_secs(89), turns),
            "the recap came before the named time"
        );
        assert!(
            session.away.due(start + Duration::from_secs(90), turns),
            "the idle time in the settings was not adopted"
        );
    }

    /// ASK-9: the time the settings file names reaches the session through `adopt_settings`, and a
    /// file that names none leaves a question waiting for as long as it takes.
    #[test]
    fn adopting_settings_puts_the_question_idle_time_in_force() {
        let planners = bravebot_core::ask::Asking {
            closes_when_idle: true,
            ..Default::default()
        };
        let mut session = Session::new("none");
        adopt_settings(
            &mut session,
            &bravebot_config::Settings::parse(r#"{"askIdleSeconds": 90}"#),
            None,
        );
        assert_eq!(
            session.ask_idle_for(&planners),
            Some(std::time::Duration::from_secs(90))
        );

        let mut unset = Session::new("none");
        adopt_settings(&mut unset, &bravebot_config::Settings::parse("{}"), None);
        assert_eq!(unset.ask_idle_for(&planners), None);
    }

    /// MOUSE-4: `tui.mouse` reaches the session through `adopt_settings`. The editor and the pager
    /// take the terminal back with the session's choice, so a session that kept the default after
    /// its settings turned capture off would capture the mouse again after the first round trip.
    #[test]
    fn adopting_settings_puts_the_mouse_choice_in_force() {
        let off = bravebot_config::Settings::parse(r#"{"tui": {"mouse": false}}"#);
        let on = bravebot_config::Settings::parse(r#"{"tui": {"mouse": true}}"#);
        let unset = bravebot_config::Settings::parse("{}");

        let mut turned_off = Session::new("none");
        adopt_settings(&mut turned_off, &off, None);
        let mut turned_on = Session::new("none");
        adopt_settings(&mut turned_on, &on, None);
        let mut unnamed = Session::new("none");
        adopt_settings(&mut unnamed, &unset, None);

        assert!(
            !turned_off.mouse_captured(),
            "tui.mouse off was not adopted"
        );
        assert!(turned_on.mouse_captured());
        assert!(unnamed.mouse_captured(), "an absent key turned capture off");
    }

    /// A loop repeats a line somebody endorsed. The sentence this program writes to carry a goal
    /// on is not one, so a turn running that sentence and asking for a later look gets no loop:
    /// otherwise the driver's own words would come back every quarter of an hour, and the person
    /// would be reading a watch nobody set up over a line nobody typed.
    #[test]
    fn only_a_line_the_person_wrote_becomes_a_watch_the_turn_asked_for() {
        let wakeup = turn::Wakeup::asked(900, false);
        let idle = Session::new("none");
        assert_eq!(
            watch_to_start(Some(wakeup), will_look_again(&idle, Wrote::ThePerson)),
            Some(wakeup),
            "a turn on the person's own line could not arrange a later look"
        );
        assert_eq!(
            watch_to_start(Some(wakeup), will_look_again(&idle, Wrote::TheDriver)),
            None
        );
        assert_eq!(
            watch_to_start(None, will_look_again(&idle, Wrote::ThePerson)),
            None
        );
    }

    /// A self-paced tick asks for its loop's next wait, and `/loop stop` may be typed while it
    /// runs (CMD-8). The tick was offered no later look of its own, its loop being what asks
    /// again, so the wait it asks for once its loop is gone starts nothing: kept, it would start
    /// a new loop on the line the person had just stopped.
    #[test]
    fn a_tick_whose_loop_was_stopped_mid_turn_starts_no_loop() {
        let mut ticking = Session::new("none");
        ticking.start_loop(
            crate::loops::request("5m watch the build"),
            Vec::new(),
            Vec::new(),
        );
        let offered = will_look_again(&ticking, Wrote::ThePerson);
        ticking.stop_loops();

        assert_eq!(
            watch_to_start(Some(turn::Wakeup::asked(900, false)), offered),
            None,
            "the wait a stopped loop's tick asked for started another loop"
        );
    }

    /// And the turn is asked before it runs, not only answered afterwards. A turn whose wait is
    /// going to be discarded and which is offered a way to ask for one is told back that a later
    /// look is arranged and needs nothing from the person, and that sentence is what it writes
    /// into the answer: the person reads that a watch exists, and nothing is watching.
    ///
    /// The four refusals are the four the session makes once the turn has ended. The line has to
    /// be the person's, since a loop repeats a line somebody endorsed; and the session has to
    /// have nothing of its own already running, since it does one of a watch, a loop and a goal
    /// at a time, and a wait arriving under any of the three is dropped.
    #[test]
    fn only_a_turn_whose_wait_would_be_kept_is_offered_a_later_look() {
        let idle = Session::new("none");
        assert!(
            will_look_again(&idle, Wrote::ThePerson),
            "a turn on the person's own line, with the session idle, was offered nothing"
        );
        assert!(
            !will_look_again(&idle, Wrote::TheDriver),
            "a sentence this program wrote was offered a loop over itself"
        );

        let mut init = Session::new("none");
        assert!(
            init.start_init().is_some(),
            "the fixture's workspace already had an AGENTS.md"
        );
        assert!(
            !will_look_again(&init, Wrote::ThePerson),
            "a /init turn was offered a loop over the prompt this program wrote"
        );
        let mut review = Session::new("none");
        review.start_review(&crate::review_command::Asked {
            target: crate::review_command::Target::Uncommitted,
            focus: None,
        });
        assert!(
            !will_look_again(&review, Wrote::ThePerson),
            "a /review turn was offered a loop over the prompt this program wrote"
        );

        let mut looping = Session::new("none");
        looping.start_loop(
            crate::loops::request("5m watch the build"),
            Vec::new(),
            Vec::new(),
        );
        assert!(
            !will_look_again(&looping, Wrote::ThePerson),
            "a line typed during a loop was offered a second one"
        );

        let mut goal = Session::new("none");
        goal.start_goal("cargo test exits 0".to_string());
        assert!(
            !will_look_again(&goal, Wrote::ThePerson),
            "a turn under a goal was offered a loop the goal will refuse"
        );

        let mut watching = Session::new("none");
        watching.arm_watch(
            "a.txt",
            ".",
            bravebot_agent::watch::Looked::Saw("a token".to_string()),
        );
        assert!(
            !will_look_again(&watching, Wrote::ThePerson),
            "a turn under a standing watch was offered a loop the watch will refuse"
        );
    }

    /// A message that was kept moves into the place the prompt was, so the record has to say the
    /// prompt is not in the conversation, or its offset names the message that took its place.
    #[test]
    fn a_prompt_taken_out_of_the_conversation_is_recorded_without_an_offset() {
        use bravebot_aichat::protocol::Message;
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        session.submit().unwrap();
        let mut conversation = Conversation::new();
        let began = conversation.mark();
        conversation.push(Message::user("first"));
        session.prompt_recorded(0);
        conversation.opening_done();
        conversation.push(Message::user("a message from another session"));

        let continued = finish_turn(
            &mut session,
            &a_config_needing_no_sign_in(),
            &workspace_for_test(),
            Line {
                text: "first",
                addressed: None,
                offered_a_later_look: false,
            },
            FinishedTurn {
                decisions: None,
                work: bravebot_agent::Work::default(),
                outcome: Err(turn::TurnError::Cancelled { attempts: Some(0) }),
                conversation,
                sink: Trail::new(),
                servers: None,
            },
            RetainedTurn {
                files: bravebot_core::file_authority::FileAuthority::new(TrustStore::new("/work")),
                programs: TrustedPrograms::new(),
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
                began,
            },
        );
        session.record_turn(0, &continued.conversation);

        assert_eq!(session.input(), "first", "the prompt did not go back");
        assert_eq!(continued.conversation.len(), 1);
        let recorded = session.turn_history().last().expect("the turn is recorded");
        assert_eq!(recorded.prompt, None);
        assert_eq!(
            recorded.prompt_offset, None,
            "the record points at the message that took the prompt's place"
        );
    }

    /// Cancel the turn in flight the way the program does: through `finish_turn`, which is where a
    /// stopped turn goes, and not through the fold a finished one goes to.
    fn stop_through_finish_turn(session: &mut Session, text: &str) {
        finish_turn(
            session,
            &a_config_needing_no_sign_in(),
            &workspace_for_test(),
            Line {
                text,
                addressed: None,
                offered_a_later_look: false,
            },
            FinishedTurn {
                decisions: None,
                work: bravebot_agent::Work::default(),
                outcome: Err(turn::TurnError::Cancelled { attempts: None }),
                conversation: Conversation::new(),
                sink: Trail::new(),
                servers: None,
            },
            RetainedTurn {
                files: bravebot_core::file_authority::FileAuthority::new(TrustStore::new("/work")),
                programs: TrustedPrograms::new(),
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
                began: Conversation::new().mark(),
            },
        );
    }

    /// Any turn cancelled while a loop runs ends the loop, and says so (LOOP-11): here the tick
    /// itself is the turn in flight. Left running, the loop would be neither due nor ended, and
    /// the next line the person typed would go out as a tick of it.
    #[test]
    fn stopping_a_tick_ends_the_loop_and_says_so() {
        let mut session = Session::new("none");
        session.start_loop(
            crate::loops::request("5m watch the build"),
            Vec::new(),
            Vec::new(),
        );
        assert_eq!(
            session.status,
            Status::Working,
            "the first tick is not in flight"
        );

        stop_through_finish_turn(&mut session, "watch the build");

        assert!(
            session.looping().is_none(),
            "the stop left the loop running"
        );
        assert_eq!(
            session
                .transcript
                .iter()
                .filter(|entry| entry.text == t!(loop_stopped))
                .count(),
            1,
            "the ending was not announced exactly once"
        );
    }

    /// And so does the person's own prompt typed in the middle of a loop, which is not a tick.
    #[test]
    fn stopping_a_prompt_typed_during_a_loop_ends_the_loop_and_says_so() {
        let mut session = Session::new("none");
        session.start_loop(
            crate::loops::request("5m watch the build"),
            Vec::new(),
            Vec::new(),
        );
        session.complete("done", Vec::new(), 0);
        session.loop_turn_ended(None);
        assert!(session.looping().is_some(), "the loop ended with its tick");
        type_line(&mut session, "something else");
        session.submit().unwrap();

        stop_through_finish_turn(&mut session, "something else");

        assert!(
            session.looping().is_none(),
            "stopping the person's own turn left the loop running"
        );
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(loop_stopped)),
            "the ending was not announced"
        );
    }

    /// Stopping the turn a watch's fire started ends that watch, and says so. The state method is
    /// tested alone; this is the wiring, which is what a person's key press reaches.
    #[test]
    fn stopping_a_fires_turn_through_the_driver_ends_the_watch_that_fired() {
        let mut session = Session::new("none");
        let saw = |token: &str| bravebot_agent::watch::Looked::Saw(token.to_string());
        session.arm_watch("notes.md", ".", saw("first"));
        session
            .watch_fired(Instant::now() + Duration::from_secs(6), |_, _| {
                saw("second")
            })
            .expect("a fire");
        assert!(session.watch_is_firing());
        stop_through_finish_turn(&mut session, "");

        assert!(
            session.watches().is_empty(),
            "stopping a fire's turn left the watch that fired running"
        );
        assert!(
            session
                .transcript
                .iter()
                .any(|entry| entry.text == t!(watch_stopped_with_its_turn, number = 1)),
            "the watch ended in silence"
        );
    }

    /// A goal is a condition for a session and not for one turn, so stopping a turn going the
    /// wrong way has to leave it: a person who has to retype the condition every time they
    /// interrupt cannot steer the work at all. The stopped turn is recorded as stopped, which is
    /// what keeps it from being judged and sent straight back: there is no answer to judge.
    #[test]
    fn stopping_a_turn_leaves_the_goal_set() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        stop_through_finish_turn(&mut session, "");

        assert_eq!(
            session.goal().map(crate::goals::Running::condition),
            Some("cargo test exits 0"),
            "the stop took the goal off with the turn"
        );
        assert_eq!(
            session.finished.map(|turn| turn.ending),
            Some(bravebot_agent::Ending::Stopped { attempts: None }),
            "a stop was not recorded as one"
        );
        assert!(
            session
                .finished
                .is_some_and(|turn| turn.ending.unanswered()),
            "a stopped turn looked answered, so it would be judged"
        );
    }

    /// A request that never came back says nothing about whether the work is finished, so the
    /// goal waits for a turn there is something to judge rather than being thrown away.
    #[test]
    fn a_turn_that_failed_leaves_the_goal_where_it_was() {
        let mut session = Session::new("none");
        session.start_goal("cargo test exits 0".to_string());
        let asked = Asked {
            name: "test-model".to_string(),
            comparable: true,
        };

        fold_outcome(
            &mut session,
            Err(turn::TurnError::Precommit("failed".to_string())),
            Trail::new(),
            Carried {
                trust: TrustStore::new("/work"),
                programs: TrustedPrograms::new(),
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
            },
            Occupied {
                budget: 100_000,
                guessed: false,
                last_request_tokens: 0,
            },
            asked,
            Line {
                text: "",
                addressed: None,
                offered_a_later_look: false,
            },
            &workspace_for_test(),
        );

        assert!(
            session.goal().is_some(),
            "one failed request ended the goal"
        );
    }

    fn round_that_came_to(context_tokens: u64) -> bravebot_agent::Spent {
        bravebot_agent::Spent {
            tokens: context_tokens + 40,
            output_tokens: 40,
            context_tokens,
            ..Default::default()
        }
    }

    /// A first turn that has completed one round knows what its request came to. Leaving the
    /// reading to the end of the turn kept it at "not measured" for a turn that ran for minutes.
    #[test]
    fn a_turn_in_flight_reads_how_full_the_context_is_after_its_first_round() {
        let mut session = Session::new("none");
        assert_eq!(
            crate::render::context_reading(&session),
            "context not yet measured"
        );

        progress_of_a_turn(&mut session, round_that_came_to(56_000), 100_000, true);

        assert_eq!(
            session.occupancy(),
            crate::state::Occupancy::Measured {
                used: 56_000,
                budget: 100_000,
                guessed: true,
            }
        );
        assert_eq!(crate::render::context_reading(&session), "context ~56%");
    }

    #[test]
    fn each_round_of_a_turn_replaces_the_reading_with_what_its_request_came_to() {
        let mut session = Session::new("none");
        progress_of_a_turn(&mut session, round_that_came_to(30_000), 100_000, false);
        progress_of_a_turn(&mut session, round_that_came_to(48_000), 100_000, false);

        assert_eq!(crate::render::context_reading(&session), "context 48%");
    }

    /// A report that carries no figure, as a compaction's does, must not replace a compaction's
    /// account of the room it won back, or an earlier turn's reading.
    #[test]
    fn a_round_that_reports_no_request_leaves_the_reading_where_it_was() {
        let mut compacted = Session::new("none");
        compacted.compacted(40_000, 100_000);
        progress_of_a_turn(&mut compacted, round_that_came_to(0), 100_000, false);
        assert_eq!(
            compacted.occupancy(),
            crate::state::Occupancy::Compacted {
                won_back: 40_000,
                budget: 100_000,
            }
        );

        let mut measured = Session::new("none");
        measured.measured(20_000, 100_000, false);
        progress_of_a_turn(&mut measured, round_that_came_to(0), 100_000, false);
        assert_eq!(measured.fullness(), Some(20));

        let mut nothing = Session::new("none");
        progress_of_a_turn(&mut nothing, round_that_came_to(0), 100_000, false);
        assert_eq!(nothing.occupancy(), crate::state::Occupancy::Unmeasured);
    }

    /// A report as the agent sends it: every figure is the turn's running total, not the round's.
    fn running_totals(
        prompt_tokens: u64,
        output_tokens: u64,
        read_tokens: u64,
        written_tokens: u64,
    ) -> bravebot_agent::Spent {
        bravebot_agent::Spent {
            tokens: prompt_tokens + output_tokens,
            output_tokens,
            context_tokens: prompt_tokens,
            cached: bravebot_aichat::protocol::Cached {
                read_tokens,
                written_tokens,
            },
            ..Default::default()
        }
    }

    fn panel_rows(session: &Session) -> Vec<String> {
        crate::panel::lines(session, crate::panel::WIDTH, 40)
            .iter()
            .map(|line| line.to_string().trim().to_string())
            .collect()
    }

    fn cache_rows(read: u64, written: u64) -> [String; 2] {
        [
            t!(panel_cache_read, tokens = crate::status::tokens(read)).to_string(),
            t!(panel_cache_written, tokens = crate::status::tokens(written)).to_string(),
        ]
    }

    fn hit_rate(whole: u64, tenth: u64) -> String {
        t!(
            hint_cache_hit_rate,
            rate = format!("{whole}{}{tenth}", t!(number_decimal_separator))
        )
        .to_string()
    }

    /// A first turn has no earlier figure to show, so leaving them to the end of the turn drew
    /// neither row nor the hit rate for as long as the turn ran.
    #[test]
    fn a_first_turn_in_flight_draws_the_cache_figures_after_its_first_round() {
        let mut session = Session::new("none");
        let before = panel_rows(&session);
        for row in cache_rows(12_000, 3_000) {
            assert!(!before.contains(&row), "{row:?} drawn before any report");
        }
        assert_eq!(crate::render::cache_hit_rate(&session), None);

        progress_of_a_turn(
            &mut session,
            running_totals(20_000, 40, 12_000, 3_000),
            100_000,
            false,
        );

        let after = panel_rows(&session);
        for row in cache_rows(12_000, 3_000) {
            assert!(after.contains(&row), "{row:?} missing: {after:#?}");
        }
        assert_eq!(
            crate::render::cache_hit_rate(&session),
            Some(hit_rate(60, 0))
        );
    }

    /// Each report carries the turn's totals so far, so the second replaces the first. Adding it
    /// to the first would count round one twice, and keeping the first would stop at round one.
    #[test]
    fn each_round_of_a_turn_replaces_the_cache_figures_with_the_turns_running_totals() {
        let mut session = Session::new("none");
        progress_of_a_turn(
            &mut session,
            running_totals(20_000, 40, 12_000, 3_000),
            100_000,
            false,
        );
        progress_of_a_turn(
            &mut session,
            running_totals(50_000, 80, 39_000, 4_000),
            100_000,
            false,
        );

        let rows = panel_rows(&session);
        for row in cache_rows(39_000, 4_000) {
            assert!(rows.contains(&row), "{row:?} missing: {rows:#?}");
        }
        for row in cache_rows(12_000, 3_000) {
            assert!(!rows.contains(&row), "{row:?} outlived the second round");
        }
        assert_eq!(
            crate::render::cache_hit_rate(&session),
            Some(hit_rate(78, 0))
        );
    }

    /// A report with nothing spent behind it says nothing about the cache, so it must not zero
    /// the figures of the turn before, nor draw rows in a session that has none.
    #[test]
    fn a_report_with_no_completed_request_leaves_the_cache_figures_where_they_were() {
        let mut session = Session::new("none");
        session.served_from_cache(
            bravebot_aichat::protocol::Cached {
                read_tokens: 12_000,
                written_tokens: 3_000,
            },
            20_000,
        );
        progress_of_a_turn(
            &mut session,
            bravebot_agent::Spent::default(),
            100_000,
            false,
        );

        let rows = panel_rows(&session);
        for row in cache_rows(12_000, 3_000) {
            assert!(rows.contains(&row), "{row:?} missing: {rows:#?}");
        }
        assert_eq!(session.cached_prompt_tokens(), Some(20_000));
        assert_eq!(
            crate::render::cache_hit_rate(&session),
            Some(hit_rate(60, 0))
        );

        let mut nothing = Session::new("none");
        progress_of_a_turn(
            &mut nothing,
            bravebot_agent::Spent::default(),
            100_000,
            false,
        );
        assert_eq!(nothing.cached(), None);
        assert_eq!(nothing.cached_prompt_tokens(), None);
        let none = panel_rows(&nothing);
        assert!(
            !none
                .iter()
                .any(|row| row.contains(&t!(panel_cache_read, tokens = "").to_string())),
            "a cache row was drawn with nothing reported: {none:#?}"
        );
    }

