    /// The stop arm the event loop reaches takes the prompt the turn began with, so it is the
    /// half that can hand it back to the box. An interjection the turn had already taken is part
    /// of the conversation it carries on with, so neither prompt moves: the opening one stays sent
    /// and the stop is recorded under both.
    #[test]
    fn stopping_a_turn_that_took_a_prompt_mid_turn_hands_nothing_back() {
        let mut session = Session::new("none");
        type_line(&mut session, "first");
        handle_key(&mut session, key(KeyCode::Enter));
        assert_eq!(session.status, Status::Working);
        for c in "second".chars() {
            handle_key_while_working(&mut session, key(KeyCode::Char(c)));
        }
        handle_key_while_working(&mut session, key(KeyCode::Enter));
        // What [`crate::remote_confirm::ToMain::Interjected`] does when the turn says it took one.
        session.interjected();

        finish_cancelled_turn(&mut session, "first", Some(0));

        assert_eq!(
            session.input(),
            "",
            "the opening prompt was handed back over an interjection"
        );
        assert_eq!(
            session
                .transcript
                .iter()
                .filter(|entry| entry.speaker == crate::state::Speaker::User)
                .map(|entry| entry.text.as_str())
                .collect::<Vec<_>>(),
            ["first", "second"],
            "the interjection was lifted back out of the transcript"
        );
        assert!(
            session
                .transcript
                .last()
                .is_some_and(|entry| entry.speaker == crate::state::Speaker::Stopped),
            "nothing recorded that it stopped"
        );
    }

    /// Repeated reports must not charge a stopped turn twice, even when restoring its prompt.
    #[test]
    fn the_cancellation_path_charges_progress_before_restoring_or_quitting() {
        for quitting in [false, true] {
            let mut session = Session::new("none");
            type_line(&mut session, "work");
            session.submit().unwrap();
            let spent = bravebot_agent::Spent {
                tokens: 37,
                output_tokens: 12,
                cached: bravebot_aichat::protocol::Cached {
                    read_tokens: 5,
                    ..Default::default()
                },
                timing: bravebot_agent::timing::Timing {
                    inference_ms: 11,
                    tools_ms: 7,
                    stalled_ms: 3,
                    ..Default::default()
                },
                ..Default::default()
            };
            session.progressed(bravebot_agent::Spent {
                tokens: 17,
                ..spent
            });
            session.progressed(spent);
            session.progressed(spent);
            if quitting {
                session.quit();
            }
            finish_cancelled_turn(&mut session, "work", Some(1));
            assert_eq!(session.tokens, 37);
            assert_eq!(
                session.split(),
                bravebot_session::sessions::Split {
                    read: 25,
                    written: 12
                },
                "the split was charged more than once, or not at all"
            );
            assert_eq!(session.spend_by_turn().get(&1), Some(&37));
            assert_eq!(session.finished.unwrap().tokens, 37);
            assert_eq!(
                session.finished.unwrap().ending,
                bravebot_agent::Ending::Stopped { attempts: Some(1) }
            );
            assert_eq!(session.timing_total().inference_ms, 11);
            assert_eq!(session.timing_total().tools_ms, 7);
            assert_eq!(session.timing_total().stalled_ms, 3);
            assert_eq!(session.cached().unwrap().read_tokens, 5);
            assert_eq!(session.is_quitting(), quitting);
            if !quitting {
                assert_eq!(session.input(), "work");
            }
        }
    }

    /// The final outcome owns success accounting; progress must not charge the same work again.
    #[test]
    fn successful_outcomes_replace_progress_and_empty_following_turns_cost_nothing() {
        for stopped in [false, true] {
            let mut session = Session::new("none");
            type_line(&mut session, "first");
            session.submit().unwrap();
            let spent = bravebot_agent::Spent {
                tokens: 73,
                timing: bravebot_agent::timing::Timing {
                    inference_ms: 13,
                    ..Default::default()
                },
                ..Default::default()
            };
            session.progressed(spent);
            session.progressed(spent);
            session.complete("done", vec![], 97);
            session.spent_time(bravebot_agent::timing::Timing {
                inference_ms: 19,
                ..Default::default()
            });
            assert_eq!(session.tokens, 97);
            assert_eq!(session.timing_total().inference_ms, 19);
            type_line(&mut session, "second");
            session.submit().unwrap();
            if stopped {
                finish_cancelled_turn(&mut session, "second", Some(0));
            } else {
                fold_outcome(
                    &mut session,
                    Err(turn::TurnError::Precommit("PRIVATE_ERROR".into())),
                    Trail::new(),
                    Carried {
                        trust: TrustStore::new("/work"),
                        programs: TrustedPrograms::new(),
                        asked: AskedAbout::new(),
                        exposed: Default::default(),
                    },
                    Occupied {
                        budget: 1000,
                        guessed: false,
                        last_request_tokens: 0,
                    },
                    Asked {
                        name: "test-model".into(),
                        comparable: true,
                    },
                    Line {
                        text: "second",
                        addressed: None,
                        offered_a_later_look: false,
                    },
                    &workspace_for_test(),
                );
            }
            assert_eq!(session.tokens, 97);
            assert_eq!(session.finished.unwrap().tokens, 0);
            assert_eq!(session.timing_total().inference_ms, 19);
            assert_eq!(session.spend_by_turn().get(&1), Some(&97));
            assert_eq!(session.spend_by_turn().get(&2).copied().unwrap_or(0), 0);
            assert!(!render::as_markdown(&session, "test").contains("PRIVATE_ERROR"));
        }
    }

    /// Safe error reporting must retain completed usage without putting raw diagnostics in history.
    #[test]
    fn a_failed_outcome_charges_only_the_latest_progress() {
        let mut session = Session::new("none");
        type_line(&mut session, "work");
        session.submit().unwrap();
        for tokens in [17, 43, 43] {
            session.progressed(bravebot_agent::Spent {
                tokens,
                output_tokens: tokens / 4,
                cached: bravebot_aichat::protocol::Cached {
                    read_tokens: 7,
                    ..Default::default()
                },
                timing: bravebot_agent::timing::Timing {
                    inference_ms: 23,
                    tools_ms: 11,
                    stalled_ms: 5,
                    ..Default::default()
                },
                ..Default::default()
            });
        }
        fold_outcome(
            &mut session,
            Err(turn::TurnError::Precommit("PRIVATE_ERROR".into())),
            Trail::new(),
            Carried {
                trust: TrustStore::new("/work"),
                programs: TrustedPrograms::new(),
                asked: AskedAbout::new(),
                exposed: bravebot_core::credentials::Exposed::new(),
            },
            Occupied {
                budget: 1000,
                guessed: false,
                last_request_tokens: 0,
            },
            Asked {
                name: "test-model".into(),
                comparable: true,
            },
            Line {
                text: "work",
                addressed: None,
                offered_a_later_look: false,
            },
            &workspace_for_test(),
        );
        assert_eq!(session.tokens, 43);
        assert_eq!(
            session.split(),
            bravebot_session::sessions::Split {
                read: 33,
                written: 10
            },
            "a failed turn's split was not the latest report's"
        );
        assert_eq!(session.finished.unwrap().tokens, 43);
        assert_eq!(session.spend_by_turn().get(&1), Some(&43));
        assert_eq!(session.timing_total().inference_ms, 23);
        assert_eq!(session.timing_total().tools_ms, 11);
        assert_eq!(session.timing_total().stalled_ms, 5);
        assert_eq!(session.cached().unwrap().read_tokens, 7);
        assert!(!render::as_markdown(&session, "test").contains("PRIVATE_ERROR"));
    }
    /// Rewind's actual save and audit truncation must agree before a turn number is reused.
    #[test]
    fn rewinding_reopened_history_removes_outcomes_plans_and_audit_before_reuse() {
        use bravebot_aichat::protocol::Message;
        use bravebot_session::sessions::{self, Standing};
        fn save(
            stored: &mut sessions::Handle,
            session: &Session,
            conversation: &Conversation,
            root: &std::path::Path,
        ) {
            stored.save(
                "history",
                Standing {
                    conversation: &conversation.snapshot(),
                    history: Some(session.turn_history()),
                    turns: session.turns,
                    tokens: session.tokens,
                    split: Default::default(),
                    spend: session.spend_by_turn(),
                    timing: session.timing_by_turn(),
                    model: None,
                    todos: &session.todos_by_turn(),
                    asides: &[],
                    trust: &TrustStore::new(root),
                    programs: &TrustedPrograms::new(),
                    directories: &[],
                    manifest: None,
                    rewind: session.rewind.points(),
                    checkouts: &[],
                    touched: None,
                    answered_by_mode: false,
                },
            );
        }
        fn reopen(root: &std::path::Path, record: &sessions::Record) -> (Session, Conversation) {
            let conversation = Conversation::restored(record.conversation.clone());
            let mut session = Session::new("test");
            session.replay(
                &conversation,
                &record.title,
                &sessions::recall(root, record),
            );
            session.restore_spend(record.tokens, record.spend.clone());
            session.restore_timing(record.timing.clone());
            session.restore_rewind_points(record.rewind_points(root), &conversation);
            (session, conversation)
        }
        fn audit(stored: &sessions::Handle, turn: usize, detail: &str) {
            stored.append_audit(
                turn,
                &[bravebot_session::audit::Stamped {
                    at: turn as u64,
                    from: None,
                    event: bravebot_core::event::Event::GatePassed {
                        gate: "file_read",
                        detail: detail.into(),
                    },
                }],
            );
        }
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let root = crate::test_profile::project("reopened-history-rewind");
        std::fs::create_dir_all(&root).unwrap();
        let workspace = Workspace::new(&root).unwrap();
        let mut trust = TrustStore::new(&root);
        let mut programs = TrustedPrograms::new();
        let mut stored =
            sessions::Handle::begin(&root, sessions::Front::Terminal, bravebot_stamp::BUILD);
        let mut session = Session::new("test");
        let mut conversation = Conversation::new();
        for (index, prompt) in ["kept", "failed", "cancelled"].into_iter().enumerate() {
            let start = conversation.recounted().len();
            type_line(&mut session, prompt);
            session.submit().unwrap();
            let point = rewind_point(&session, &conversation, &trust, &programs, &stored);
            session.rewind.open(point, prompt.into());
            session.prompt_recorded(conversation.recounted().len());
            conversation.push(Message::user(prompt));
            conversation.push(Message::assistant(format!("working {prompt}")));
            session.narrate(format!("working {prompt}"));
            session.set_todos(bravebot_core::todo::rows(&bravebot_core::todo::List::new(
                vec![bravebot_core::todo::Item::new(
                    prompt,
                    bravebot_core::todo::Status::Active,
                )],
            )));
            session.progressed(bravebot_agent::Spent {
                tokens: (index as u64 + 1) * 10,
                timing: bravebot_agent::timing::Timing {
                    inference_ms: index as u64 + 1,
                    ..Default::default()
                },
                ..Default::default()
            });
            match index {
                0 => session.complete("done", vec![], 10),
                1 => session.fail(
                    "safe failure",
                    bravebot_agent::Ending::Failed(bravebot_agent::Diagnosis::of(
                        bravebot_agent::Category::Transport,
                    )),
                ),
                _ => {
                    finish_cancelled_turn(&mut session, prompt, Some(1));
                }
            }
            session.record_turn(start, &conversation);
            save(&mut stored, &session, &conversation, &root);
            audit(&stored, session.turns, prompt);
        }
        let record = sessions::load(&root, stored.id()).unwrap();
        let (mut session, mut conversation) = reopen(&root, &record);
        rewind(
            &mut session,
            &mut conversation,
            &mut trust,
            &mut programs,
            &mut stored,
            &workspace,
            &mut None,
            2,
        );
        let record = sessions::load(&root, stored.id()).unwrap();
        let (mut session, mut conversation) = reopen(&root, &record);
        assert_eq!(session.turns, 1);
        assert_eq!(session.tokens, 10);
        assert_eq!(
            session.todos_by_turn().keys().copied().collect::<Vec<_>>(),
            [1]
        );
        assert!(!session.transcript.iter().any(|e| matches!(
            e.speaker,
            crate::state::Speaker::Failure | crate::state::Speaker::Stopped
        )));
        let trail = sessions::audit_of(&root, stored.id());
        assert_eq!(trail.keys().copied().collect::<Vec<_>>(), [1]);
        let start = conversation.recounted().len();
        type_line(&mut session, "replacement");
        session.submit().unwrap();
        session.prompt_recorded(conversation.recounted().len());
        conversation.push(Message::user("replacement"));
        session.complete("new answer", vec![], 41);
        session.record_turn(start, &conversation);
        save(&mut stored, &session, &conversation, &root);
        audit(&stored, 2, "replacement");
        let record = sessions::load(&root, stored.id()).unwrap();
        let (session, _) = reopen(&root, &record);
        assert_eq!(session.tokens, 51);
        assert_eq!(session.spend_by_turn()[&2], 41);
        assert_eq!(session.timing_by_turn()[&2].inference_ms, 0);
        assert!(!session.todos_by_turn().contains_key(&2));
        let trail = sessions::audit_of(&root, stored.id());
        assert_eq!(trail[&2].len(), 1);
        assert!(trail[&2][0].text.contains("replacement"));
        assert!(!session.transcript.iter().any(|e| matches!(
            e.speaker,
            crate::state::Speaker::Failure | crate::state::Speaker::Stopped
        )));
    }

    use bravebot_agent::{Ending, PermissionMode};

    /// An answer from an exchange that met something untrusted holds no `kept`, and the driver
    /// does not count it: removing the guard would offer text that content may have shaped as the
    /// person's next prompt. The request is charged either way.
    #[test]
    fn a_suggestion_from_an_exchange_that_met_something_untrusted_is_not_offered() {
        let answer = |kept: Option<&str>| bravebot_agent::aside::Answered {
            shown: "run the tests again".to_string(),
            kept: kept.map(str::to_string),
            usage: bravebot_aichat::protocol::Usage {
                prompt_tokens: 70,
                completion_tokens: 30,
                ..Default::default()
            },
        };
        assert_eq!(suggested_text(Some(answer(None))).0, None);
        for kept in [None, Some("run the tests again")] {
            assert_eq!(
                suggested_text(Some(answer(kept))).1,
                answer(kept).usage,
                "the request was not charged for what it read and wrote"
            );
        }
        assert_eq!(
            suggested_text(Some(answer(Some("run the tests again")))).0,
            Some("run the tests again".to_string())
        );
        assert_eq!(suggested_text(None), (None, Default::default()));
    }

    fn offered(text: &str) -> Session {
        let mut session = Session::new("none");
        session.adopt_suggestions(true);
        session.offer_suggestion(text.to_string());
        session
    }

    fn pressed(code: KeyCode) -> KeyEvent {
        KeyEvent::new(code, KeyModifiers::NONE)
    }

    /// INPUT-43: Tab and Right move the suggestion into the box as text, and nothing sends it.
    #[test]
    fn tab_and_right_move_the_suggestion_into_the_box_and_send_nothing() {
        for code in [KeyCode::Tab, KeyCode::Right] {
            let mut session = offered("run the tests again");
            assert_eq!(handle_key(&mut session, pressed(code)), Action::None);
            assert_eq!(session.input(), "run the tests again");
            assert_eq!(session.suggestion(), None);
        }
    }

    /// a suggestion that begins with a slash is only text once taken, and Enter is what runs
    /// it. Taking it must not run the command.
    #[test]
    fn a_suggestion_that_begins_with_a_slash_is_text_until_enter() {
        let mut session = offered("/clear the old notes");
        assert_eq!(
            handle_key(&mut session, pressed(KeyCode::Tab)),
            Action::None
        );
        assert_eq!(session.input(), "/clear the old notes");
    }

    /// Any other key removes it, and the key is then read as it always was.
    #[test]
    fn any_other_key_removes_the_suggestion_and_still_types() {
        let mut session = offered("run the tests again");
        handle_key(&mut session, pressed(KeyCode::Char('x')));
        assert_eq!(session.suggestion(), None);
        assert_eq!(session.input(), "x");

        let mut session = offered("run the tests again");
        handle_key(&mut session, pressed(KeyCode::Esc));
        assert_eq!(session.suggestion(), None);
        assert_eq!(session.input(), "");
        // And Tab, with nothing on offer, takes nothing into the box.
        handle_key(&mut session, pressed(KeyCode::Tab));
        assert_eq!(session.input(), "");
    }

    /// A modifier pressed on its own is not a key anybody typed.
    #[test]
    fn a_modifier_on_its_own_leaves_the_suggestion_standing() {
        let mut session = offered("run the tests again");
        handle_key(
            &mut session,
            pressed(KeyCode::Modifier(
                ratatui::crossterm::event::ModifierKeyCode::LeftShift,
            )),
        );
        assert_eq!(session.suggestion(), Some("run the tests again"));
    }

    /// A suggestion is not offered where the setting is off, where something has been typed, or
    /// where the session is not idle, and one that goes stale is dropped.
    #[test]
    fn a_suggestion_is_offered_only_to_an_idle_empty_box_with_the_setting_on() {
        let mut off = Session::new("none");
        off.offer_suggestion("run the tests again".to_string());
        assert_eq!(off.suggestion(), None);

        let mut typed = Session::new("none");
        typed.adopt_suggestions(true);
        handle_key(&mut typed, pressed(KeyCode::Char('a')));
        typed.offer_suggestion("run the tests again".to_string());
        assert_eq!(typed.suggestion(), None);

        let mut working = Session::new("none");
        working.adopt_suggestions(true);
        working.status = Status::Working;
        working.offer_suggestion("run the tests again".to_string());
        assert_eq!(working.suggestion(), None);

        let mut stale = offered("run the tests again");
        stale.status = Status::Working;
        stale.settle_suggestion();
        assert_eq!(stale.suggestion(), None);
    }

    /// The request is made after a turn that answered, with the setting on, and in none of the
    /// places the issue lists.
    #[test]
    fn a_suggestion_is_asked_for_only_after_a_turn_that_answered() {
        let done = Some(Ending::Done);
        let ask = PermissionMode::Ask;
        assert!(suggestion_is_due(true, false, ask, done, false));
        assert!(!suggestion_is_due(false, false, ask, done, false));
        assert!(!suggestion_is_due(true, true, ask, done, false));
        assert!(!suggestion_is_due(
            true,
            false,
            PermissionMode::Plan,
            done,
            false
        ));
        assert!(!suggestion_is_due(true, false, ask, None, false));
        assert!(!suggestion_is_due(
            true,
            false,
            ask,
            Some(Ending::Stopped { attempts: None }),
            false
        ));
        assert!(!suggestion_is_due(true, false, ask, done, true));
    }

    /// The request's cost is in the session's total and in the figure for the turn it followed.
    #[test]
    fn a_suggestions_cost_is_charged_to_the_session() {
        let mut session = Session::new("none");
        session.charge_suggestion(bravebot_aichat::protocol::Usage {
            prompt_tokens: 90,
            completion_tokens: 30,
            ..Default::default()
        });
        assert_eq!(session.tokens, 120);
        assert_eq!(session.spend_by_turn().get(&0).copied(), Some(120));
        assert_eq!(
            session.split(),
            bravebot_session::sessions::Split {
                read: 90,
                written: 30
            },
            "a suggestion's request was charged without how it divided"
        );
    }

    fn a_store_for(name: &str) -> (std::path::PathBuf, bravebot_session::sessions::Handle) {
        let root = crate::test_profile::project(name);
        std::fs::create_dir_all(&root).unwrap();
        let stored = bravebot_session::sessions::Handle::begin(
            &root,
            bravebot_session::sessions::Front::Terminal,
            bravebot_stamp::BUILD,
        );
        (root, stored)
    }

    fn a_request_in_flight() -> (Option<Suggesting>, mpsc::Sender<Suggested>) {
        let (worker, answer) = mpsc::channel();
        (Some(Suggesting { answer }), worker)
    }

    /// The request came to `tokens`, a quarter of them written.
    fn what_the_request_did(text: Option<&str>, tokens: u64) -> Suggested {
        Suggested {
            text: text.map(str::to_string),
            usage: bravebot_aichat::protocol::Usage {
                prompt_tokens: tokens - tokens / 4,
                completion_tokens: tokens / 4,
                ..Default::default()
            },
            events: vec![bravebot_session::audit::Stamped {
                at: 1,
                from: None,
                event: bravebot_core::event::Event::GatePassed {
                    gate: "file_read",
                    detail: "suggestion".into(),
                },
            }],
        }
    }

    fn a_session_that_suggests() -> Session {
        let mut session = Session::new("none");
        session.adopt_suggestions(true);
        session
    }

    /// INPUT-43: an answer that comes back is charged to the session, its trail is kept, and the
    /// suggestion is in the box. The screen is then redrawn and the request is not waited on again.
    #[test]
    fn an_answered_request_is_charged_recorded_and_offered() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let (root, mut stored) = a_store_for("suggestion-answered");
        let mut session = a_session_that_suggests();
        let (mut suggesting, worker) = a_request_in_flight();
        worker
            .send(what_the_request_did(Some("run the tests again"), 120))
            .unwrap();

        assert!(take_suggestion(&mut session, &mut stored, &mut suggesting));

        assert!(suggesting.is_none());
        assert_eq!(session.tokens, 120);
        assert_eq!(session.suggestion(), Some("run the tests again"));
        let trail = bravebot_session::sessions::audit_of(&root, stored.id());
        assert_eq!(trail[&session.turns].len(), 1);
    }

    /// The request went out whatever it returned, so an answer outside the counts costs the same
    /// and leaves the same trail, and puts nothing in the box.
    #[test]
    fn an_answer_that_is_not_usable_is_still_charged_and_recorded() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let (root, mut stored) = a_store_for("suggestion-unusable");
        let mut session = a_session_that_suggests();
        let (mut suggesting, worker) = a_request_in_flight();
        worker.send(what_the_request_did(None, 30)).unwrap();

        take_suggestion(&mut session, &mut stored, &mut suggesting);

        assert!(suggesting.is_none());
        assert_eq!(session.tokens, 30);
        assert_eq!(session.suggestion(), None);
        let trail = bravebot_session::sessions::audit_of(&root, stored.id());
        assert_eq!(trail[&session.turns].len(), 1);
    }

    /// A request that has not been answered yet changes nothing and is still waited on, so the
    /// answer is taken when it comes.
    #[test]
    fn a_request_not_yet_answered_is_waited_on() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let (_root, mut stored) = a_store_for("suggestion-pending");
        let mut session = a_session_that_suggests();
        let (mut suggesting, worker) = a_request_in_flight();

        assert!(!take_suggestion(&mut session, &mut stored, &mut suggesting));
        assert!(suggesting.is_some());
        assert_eq!(session.tokens, 0);
        assert_eq!(session.suggestion(), None);

        worker
            .send(what_the_request_did(Some("run the tests again"), 120))
            .unwrap();
        assert!(take_suggestion(&mut session, &mut stored, &mut suggesting));
        assert_eq!(session.suggestion(), Some("run the tests again"));
    }

    /// A worker that ends without answering leaves nothing to wait for, and nothing to charge or
    /// record.
    #[test]
    fn a_worker_that_ends_without_answering_is_forgotten() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let (root, mut stored) = a_store_for("suggestion-disconnected");
        let mut session = a_session_that_suggests();
        let (mut suggesting, worker) = a_request_in_flight();
        drop(worker);

        assert!(!take_suggestion(&mut session, &mut stored, &mut suggesting));

        assert!(suggesting.is_none());
        assert_eq!(session.tokens, 0);
        assert_eq!(session.suggestion(), None);
        assert!(bravebot_session::sessions::audit_of(&root, stored.id()).is_empty());
    }

    /// An answer that comes after the person began typing is a guess about a state that has
    /// passed. It is not put in the box, what was typed is kept, and the request is still charged.
    #[test]
    fn an_answer_that_arrives_after_typing_is_charged_and_not_offered() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let (_root, mut stored) = a_store_for("suggestion-after-typing");
        let mut session = a_session_that_suggests();
        let (mut suggesting, worker) = a_request_in_flight();
        handle_key(&mut session, pressed(KeyCode::Char('a')));
        worker
            .send(what_the_request_did(Some("run the tests again"), 120))
            .unwrap();

        take_suggestion(&mut session, &mut stored, &mut suggesting);

        assert_eq!(session.tokens, 120);
        assert_eq!(session.suggestion(), None);
        assert_eq!(session.input(), "a");
    }

    /// No request goes out where the setting is off, before any turn has ended, or after one that
    /// did not answer. The worker of a request that did go out cannot be driven without a model,
    /// so these are the cases that return before it starts.
    #[test]
    fn no_request_is_made_where_the_setting_is_off_or_no_turn_answered() {
        let config = a_config_needing_no_sign_in();
        let conversation = Conversation::new();
        let trust = TrustStore::new(workspace_for_test().root());

        let mut off = Session::new("none");
        off.complete("done", vec![], 10);
        assert!(suggest_next(&off, &config, &conversation, &trust).is_none());

        let before_any_turn = a_session_that_suggests();
        assert!(suggest_next(&before_any_turn, &config, &conversation, &trust).is_none());

        let mut failed = a_session_that_suggests();
        failed.fail(
            "safe failure",
            Ending::Failed(bravebot_agent::Diagnosis::of(
                bravebot_agent::Category::Transport,
            )),
        );
        assert!(suggest_next(&failed, &config, &conversation, &trust).is_none());
    }

    /// A session wide enough for the panel with `src/a.rs` written once.
    fn session_that_wrote() -> Session {
        let mut session = Session::new("none");
        session.note_layout(crate::state::Laid {
            columns: 120,
            ..crate::state::Laid::default()
        });
        session
            .transcript
            .push(crate::state::Entry::user("edit it"));
        let diff = bravebot_agent::diff::Diff::compute("old\n", "new\n");
        session.transcript.push(crate::state::Entry::tool(
            bravebot_agent::report::Activity::running("Update", "src/a.rs")
                .of_tool("edit_file")
                .with_changes(diff.condensed(3))
                .with_written(Some(bravebot_agent::report::Written {
                    landed: "src/a.rs".into(),
                    added: diff.added(),
                    removed: diff.removed(),
                    numbers: diff.condensed_numbers(3),
                }))
                .done("added 1 line, removed 1 line"),
        ));
        session
    }

    /// FILES-3: `/diff` draws the panel in its files state, opening it where it was closed, and `q`
    /// puts it back as it was: a panel that was open is open and ordinary again.
    #[test]
    fn diff_opens_the_panel_in_its_files_state_and_q_puts_it_back() {
        let mut session = session_that_wrote();
        session.toggle_panel();
        assert!(session.panel_open() && !session.files_open());
        assert_eq!(
            dispatch_command(&mut session, commanded(DIFF_COMMAND)),
            Action::Redraw
        );
        assert!(session.files_open(), "/diff did not open the state");
        assert_eq!(
            handle_key(&mut session, key(KeyCode::Char('q'))),
            Action::Redraw
        );
        assert!(!session.files_open(), "q did not end the state");
        assert!(session.panel_open(), "the panel that was open was closed");
    }

    /// FILES-3: a panel `/diff` opened is closed again when the state ends, whichever key ends it,
    /// and `/diff` again ends it too.
    #[test]
    fn leaving_the_state_closes_a_panel_it_opened() {
        for ending in [KeyCode::Char('q'), KeyCode::Esc] {
            let mut session = session_that_wrote();
            dispatch_command(&mut session, commanded(DIFF_COMMAND));
            assert!(session.panel_open());
            handle_key(&mut session, key(ending));
            assert!(!session.panel_open(), "{ending:?} left the panel open");
        }
        let mut session = session_that_wrote();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        assert!(!session.files_open() && !session.panel_open());
    }

    /// FILES-3, FILES-9: typing `/diff` with the state open reaches nothing, so the state stays, and
    /// the box keeps its line. The same line queued earlier and dispatched ends it.
    #[test]
    fn a_typed_diff_cannot_end_the_state_and_a_queued_one_does() {
        let mut session = session_that_wrote();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        assert!(session.files_open());
        for character in DIFF_COMMAND.chars() {
            handle_key(&mut session, key(KeyCode::Char(character)));
        }
        let action = handle_key(&mut session, key(KeyCode::Enter));
        assert_ne!(action, Action::Submit(DIFF_COMMAND.to_string()));
        assert!(session.files_open(), "typing /diff ended the state");
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        assert!(
            !session.files_open(),
            "a queued /diff did not end the state"
        );
    }

    /// FILES-3: the panel chord hides the panel from the state and ends the state with it.
    #[test]
    fn the_panel_chord_ends_the_state_with_the_panel() {
        let mut session = session_that_wrote();
        session.toggle_panel();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        handle_key(&mut session, ctrl('x'));
        assert!(!session.files_open(), "the chord left the state open");
        assert!(!session.panel_open(), "the chord left the panel open");
    }

    /// FILES-3: with no file written `/diff` answers with a note and changes nothing, and on a
    /// terminal too narrow it says how wide the terminal has to be.
    #[test]
    fn diff_with_nothing_written_answers_with_a_note() {
        let mut session = Session::new("none");
        session.note_layout(crate::state::Laid {
            columns: 120,
            ..crate::state::Laid::default()
        });
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        assert!(!session.files_open() && !session.panel_open());
        let said = session.transcript.last().map(|entry| entry.text.clone());
        assert_eq!(said, Some(t!(files_nothing_written).to_string()));

        let mut narrow = session_that_wrote();
        narrow.note_layout(crate::state::Laid {
            columns: 80,
            ..crate::state::Laid::default()
        });
        dispatch_command(&mut narrow, commanded(DIFF_COMMAND));
        assert!(!narrow.files_open());
        let said = narrow.transcript.last().map(|entry| entry.text.clone());
        assert_eq!(
            said,
            Some(t!(files_too_narrow, columns = crate::panel::NARROWEST).to_string())
        );
    }

    /// FILES-3, CMD-2: typed in full `/diff` opens the state, and no command claims `/files`, so
    /// that line completes to nothing, is not carried out mid-turn and is sent as a prompt like any
    /// other line that starts with a word nobody claims.
    #[test]
    fn diff_is_the_command_and_files_is_not_one() {
        assert_eq!(DIFF_COMMAND, "/diff");
        assert!(commands().iter().any(|command| command.name == "/diff"));
        assert!(!commands().iter().any(|command| command.name == "/files"));
        assert_eq!(command_typed("/diff"), Some("/diff"));
        assert_eq!(command_typed("/files"), None);
        assert!(completions("/files").is_empty());
        assert!(!runs_while_working("/files"));

        let mut session = session_that_wrote();
        type_line(&mut session, "/diff");
        handle_key(&mut session, key(KeyCode::Enter));
        assert!(session.files_open(), "typing /diff did not open the state");
        handle_key(&mut session, key(KeyCode::Char('q')));

        type_line(&mut session, "/files");
        let action = handle_key(&mut session, key(KeyCode::Enter));
        assert!(!session.files_open(), "typing /files opened the state");
        assert_eq!(action, Action::Submit("/files".to_string()));
    }

    /// FILES-9: a character does not reach the box, Enter sends nothing and a paste does not reach
    /// the line.
    #[test]
    fn a_typed_character_does_not_reach_the_box_while_the_files_state_is_open() {
        let mut session = session_that_wrote();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        for c in ['x', 'a', 'z', ' '] {
            handle_key(&mut session, key(KeyCode::Char(c)));
        }
        assert_eq!(session.input(), "");
        assert_eq!(handle_key(&mut session, key(KeyCode::Enter)), Action::None);
        assert_eq!(handle_paste(&mut session, "pasted"), Action::None);
        assert_eq!(session.input(), "");
        assert!(session.files_open());
    }

    /// FILES-9: a key the state does not name does nothing, and leaves the state where it was.
    #[test]
    fn a_key_the_state_does_not_name_does_nothing() {
        let mut session = session_that_wrote();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        let before = session.files_state().cloned();
        for code in [
            KeyCode::Tab,
            KeyCode::Char('?'),
            KeyCode::Char('['),
            KeyCode::Char(']'),
            KeyCode::Backspace,
            KeyCode::F(5),
        ] {
            assert_eq!(
                handle_key(&mut session, key(code)),
                Action::None,
                "{code:?}"
            );
        }
        assert_eq!(handle_key(&mut session, ctrl('a')), Action::None);
        assert_eq!(session.files_state().cloned(), before);
        assert!(session.files_open());
    }

    /// FILES-9: the line keeps its text and caret while the state is open and has both when it ends.
    #[test]
    fn the_line_comes_back_untouched_when_the_state_ends() {
        let mut session = session_that_wrote();
        for c in "half a prompt".chars() {
            session.type_char(c);
        }
        handle_key(&mut session, key(KeyCode::Left));
        let caret = session.caret();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        handle_key(&mut session, key(KeyCode::Char('x')));
        handle_key(&mut session, key(KeyCode::Down));
        handle_key(&mut session, key(KeyCode::Char('q')));
        assert_eq!(session.input(), "half a prompt");
        assert_eq!(session.caret(), caret);
    }

    /// FILES-9: Ctrl-C ends the state and does nothing else, so a turn in flight goes on.
    #[test]
    fn ctrl_c_ends_the_state_and_leaves_the_turn_running() {
        let mut session = session_that_wrote();
        session.status = Status::Working;
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        assert!(
            !stops_the_turn(&session, ctrl('c')),
            "Ctrl-C reaches the turn while the state is open"
        );
        let action = handle_key_while_working(&mut session, ctrl('c'));
        assert_ne!(action, Action::Cancel, "Ctrl-C reached the turn");
        assert!(!session.files_open(), "Ctrl-C did not end the state");
        assert_eq!(session.status, Status::Working);
        // The next press is the one that reaches the turn.
        assert!(stops_the_turn(&session, ctrl('c')));
    }

    /// FILES-3: entering and leaving the state writes nothing to the file that keeps the panel's
    /// choice, so a panel left closed stays closed for the next session.
    #[test]
    fn entering_and_leaving_the_state_writes_no_panel_choice() {
        if !crate::test_profile::in_isolated_profile() {
            return;
        }
        let mut session = session_that_wrote().with_stored_history();
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        handle_key(&mut session, key(KeyCode::Char('q')));
        assert_eq!(bravebot_session::store::load_panel(), None);
        bravebot_session::store::save_panel(true);
        dispatch_command(&mut session, commanded(DIFF_COMMAND));
        handle_key(&mut session, key(KeyCode::Esc));
        assert_eq!(bravebot_session::store::load_panel(), Some(true));
    }

    /// What a request for an enhancement comes back with over an exchange that met nothing
    /// untrusted, which is the one the planner could have held.
    fn an_answer_holding(text: &str) -> Result<bravebot_agent::aside::Answered, Unanswered> {
        Ok(bravebot_agent::aside::Answered {
            shown: text.to_string(),
            kept: Some(text.to_string()),
            usage: Default::default(),
        })
    }

    /// A session with `draft` typed into the box and its enhancement written over it, as it is when
    /// the request comes back.
    fn enhanced_from(draft: &str, rewrite: &str) -> Session {
        let mut session = Session::new("none");
        type_line(&mut session, draft);
        session.begin_aside();
        enhance_answered(&mut session, draft, an_answer_holding(rewrite));
        assert!(session.enhanced_pending(), "the enhancement was not placed");
        session
    }

    /// INPUT-48. Rejects: the chord sending the line as a prompt, clearing the box or being typed
